export interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  lastServiceDate: string;
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  description: string;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'service' | 'ai-assistant';

import { GoogleGenAI, Type } from "@google/genai";
import { Vehicle, ServiceRecord } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const getMaintenanceAdvice = async (vehicle: Vehicle, history: ServiceRecord[]) => {
  const ai = getAIClient();
  const prompt = `Jako expertní automechanik, navrhni plán údržby pro následující vozidlo na základě jeho historie. 
  Vozidlo: ${vehicle.make} ${vehicle.model}, rok ${vehicle.year}, najeto ${vehicle.mileage} km.
  Historie servisů: ${JSON.stringify(history.map(h => ({ date: h.date, desc: h.description })))}
  Odpověz v češtině, stručně a bodově. Zaměř se na kritické komponenty pro tento model.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Nepodařilo se získat AI doporučení. Zkuste to prosím později.";
  }
};

export const diagnoseProblem = async (problemDescription: string, vehicleInfo: string) => {
  const ai = getAIClient();
  const prompt = `Mechanik popsal problém u vozidla (${vehicleInfo}): "${problemDescription}". 
  Uveď 3 nejpravděpodobnější příčiny a na co se má mechanik zaměřit při kontrole. Odpověz v češtině.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Diagnostika selhala.";
  }
};

