import React, { useState } from 'react';
import { BrainCircuit, Sparkles, Send, MessageSquare, Car, History, Loader2, Info } from 'lucide-react';
import { Vehicle, ServiceRecord } from '../types';
import { diagnoseProblem, getMaintenanceAdvice } from '../services/geminiService';

interface AiAssistantProps {
  vehicles: Vehicle[];
  services: ServiceRecord[];
}

const AiAssistant: React.FC<AiAssistantProps> = ({ vehicles, services }) => {
  const [selectedVehicleId, setSelectedVehicleId] = useState<string>(vehicles[0]?.id || '');
  const [problemDescription, setProblemDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState<string | null>(null);
  const [tab, setTab] = useState<'diagnose' | 'maintenance'>('diagnose');

  const handleDiagnose = async () => {
    if (!problemDescription.trim()) return;
    setLoading(true);
    setResponse(null);
    const vehicle = vehicles.find(v => v.id === selectedVehicleId);
    const info = vehicle ? `${vehicle.make} ${vehicle.model} (${vehicle.year}), ${vehicle.mileage}km` : 'neznámé auto';
    const result = await diagnoseProblem(problemDescription, info);
    setResponse(result || null);
    setLoading(false);
  };

  const handleMaintenancePlan = async () => {
    const vehicle = vehicles.find(v => v.id === selectedVehicleId);
    if (!vehicle) return;
    setLoading(true);
    setResponse(null);
    const history = services.filter(s => s.vehicleId === vehicle.id);
    const result = await getMaintenanceAdvice(vehicle, history);
    setResponse(result || null);
    setLoading(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="bg-gradient-to-r from-blue-700 to-indigo-800 rounded-3xl p-8 text-white shadow-2xl shadow-blue-200 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-10 opacity-10">
          <BrainCircuit className="w-48 h-48" />
        </div>
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
          <div className="max-w-2xl">
            <div className="flex items-center gap-2 mb-4 bg-white/20 w-fit px-3 py-1 rounded-full backdrop-blur-md">
              <Sparkles className="w-4 h-4 text-amber-300 fill-amber-300" />
              <span className="text-xs font-bold uppercase tracking-widest">Powered by Gemini AI</span>
            </div>
            <h2 className="text-3xl font-bold mb-3">Chytrý asistent servisu</h2>
            <p className="text-blue-100 text-lg leading-relaxed">
              Pomůžu vám s rychlou diagnostikou závad nebo navrhnu ideální plán údržby pro konkrétní vozidlo na základě ujetých kilometrů a historie.
            </p>
          </div>
          <div className="shrink-0 flex flex-col gap-2">
            <button 
              onClick={() => { setTab('diagnose'); setResponse(null); }}
              className={`px-6 py-3 rounded-xl font-bold transition-all ${tab === 'diagnose' ? 'bg-white text-blue-800 shadow-xl' : 'text-white hover:bg-white/10'}`}
            >
              Rychlá diagnostika
            </button>
            <button 
              onClick={() => { setTab('maintenance'); setResponse(null); }}
              className={`px-6 py-3 rounded-xl font-bold transition-all ${tab === 'maintenance' ? 'bg-white text-blue-800 shadow-xl' : 'text-white hover:bg-white/10'}`}
            >
              Plán údržby
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
              <Car className="w-4 h-4" />
              Vyberte vozidlo
            </label>
            <select 
              value={selectedVehicleId}
              onChange={(e) => setSelectedVehicleId(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-slate-900"
            >
              {vehicles.map(v => (
                <option key={v.id} value={v.id}>{v.make} {v.model} ({v.licensePlate})</option>
              ))}
            </select>

            {tab === 'diagnose' && (
              <div className="mt-6">
                <label className="block text-sm font-bold text-slate-700 mb-2 flex items-center gap-2">
                  <MessageSquare className="w-4 h-4" />
                  Popis problému
                </label>
                <textarea 
                  rows={4}
                  placeholder="Např.: Slyším klepání z přední nápravy při zatáčení doprava..."
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-slate-900 resize-none"
                  value={problemDescription}
                  onChange={(e) => setProblemDescription(e.target.value)}
                />
                <button 
                  onClick={handleDiagnose}
                  disabled={loading || !problemDescription}
                  className="w-full mt-4 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Send className="w-5 h-5" />}
                  Analyzovat závadu
                </button>
              </div>
            )}

            {tab === 'maintenance' && (
              <div className="mt-6 space-y-4">
                <div className="p-4 bg-blue-50 rounded-xl border border-blue-100 flex items-start gap-3">
                  <Info className="w-5 h-5 text-blue-500 shrink-0" />
                  <p className="text-sm text-blue-800">
                    AI zanalyzuje servisní historii a aktuální stav km pro vybrané vozidlo.
                  </p>
                </div>
                <button 
                  onClick={handleMaintenancePlan}
                  disabled={loading}
                  className="w-full bg-slate-900 hover:bg-black text-white font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <History className="w-5 h-5" />}
                  Generovat plán
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-2">
          {response ? (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-8 h-full animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
                <div className="bg-amber-100 p-2 rounded-lg">
                  <Sparkles className="w-5 h-5 text-amber-600" />
                </div>
                <h3 className="text-xl font-bold text-slate-900">
                  {tab === 'diagnose' ? 'Návrh diagnostiky' : 'Doporučený plán údržby'}
                </h3>
              </div>
              <div className="prose prose-slate max-w-none text-slate-700 whitespace-pre-wrap">
                {response}
              </div>
              <div className="mt-8 p-4 bg-slate-50 rounded-xl flex items-center justify-between">
                <p className="text-xs text-slate-400">Tento výstup je generován umělou inteligencí a slouží pouze jako konzultační podklad pro kvalifikovaného mechanika.</p>
                <button className="text-sm font-bold text-blue-600">Vytisknout</button>
              </div>
            </div>
          ) : (
            <div className="bg-slate-50 rounded-2xl border border-dashed border-slate-300 h-full flex flex-col items-center justify-center p-12 text-center">
              <div className="w-20 h-20 rounded-full bg-white flex items-center justify-center shadow-sm mb-6">
                <BrainCircuit className="w-10 h-10 text-slate-300" />
              </div>
              <h3 className="text-lg font-bold text-slate-900 mb-2">Zatím nebyly generovány žádné výstupy</h3>
              <p className="text-slate-500 max-w-xs">Vyberte vozidlo a akci v levém panelu pro spuštění AI asistenta.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AiAssistant;

import { GoogleGenAI } from "@google/genai";
import { Vehicle, ServiceRecord } from "../types";

/**
 * @fix: Updated Gemini client initialization to strictly follow the requirement:
 * `new GoogleGenAI({ apiKey: process.env.API_KEY })`.
 * Models upgraded to 'gemini-3-pro-preview' for complex diagnostic and maintenance reasoning tasks.
 */

export const getMaintenanceAdvice = async (vehicle: Vehicle, history: ServiceRecord[]) => {
