    e.preventDefault();
    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...formData
        });
      }
    } else {
      const newCustomer: Customer = {
        ...formData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      };
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData({ firstName: '', lastName: '', email: '', phone: '', address: '' });
  };

