    const list: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();

    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);

      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      if (diffStk >= 0 && diffStk <= 30) {
        list.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      }
      if (diffService >= 0 && diffService <= 15) {
        list.push({ type: 'service', vehicle: v, daysLeft: diffService });
      }
    });
    return list;
  }, [vehicles]);

  const navItems = [
    { id: 'dashboard', label: 'Přehled', icon: LayoutDashboard },
    { id: 'orders', label: 'Zakázky', icon: ClipboardList },
    { id: 'customers', label: 'Zákazníci', icon: Users },
    { id: 'vehicles', label: 'Vozidla', icon: Car },
    { id: 'settings', label: 'Nastavení', icon: SettingsIcon },
  ];

  const handleAddCustomer = (newCustomer: Customer) => {
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const handleUpdateCustomer = (updatedCustomer: Customer) => {
    setCustomers(prev => prev.map(c => c.id === updatedCustomer.id ? updatedCustomer : c));
  };

  const handleDeleteCustomer = (id: string) => {
    setCustomers(prev => prev.filter(c => c.id !== id));
  };

  const handleAddVehicle = (newVehicle: Vehicle) => {
    setVehicles(prev => [newVehicle, ...prev]);
  };

  const handleUpdateVehicle = (updatedVehicle: Vehicle) => {
    setVehicles(prev => prev.map(v => v.id === updatedVehicle.id ? updatedVehicle : v));
  };

  const handleDeleteVehicle = (id: string) => {
    setVehicles(prev => prev.filter(v => v.id !== id));
  };

  const handleNavigateToVehicle = (vehicleId: string) => {
    setTargetVehicleId(vehicleId);
    setActiveView('vehicles');
  };

  // Reset target vehicle ID when switching views away from vehicles
  useEffect(() => {
    if (activeView !== 'vehicles') {
      setTargetVehicleId(null);
    }
  }, [activeView]);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return (
        <Dashboard 
          customers={customers} 
          vehicles={vehicles} 
          services={services} 
          onNavigate={(view) => setActiveView(view)} 
        />
      );
      case 'orders': return <OrderManager services={services} vehicles={vehicles} customers={customers} />;
      case 'customers': return (
        <CustomerManager 
          customers={customers} 
          vehicles={vehicles} 
          setCustomers={setCustomers} 
          onAddCustomer={handleAddCustomer}
          onUpdateCustomer={handleUpdateCustomer}
          onDeleteCustomer={handleDeleteCustomer}
          onNavigateToVehicle={handleNavigateToVehicle}
        />
      );
      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} 
          customers={customers} 
          services={services} 
          onAddVehicle={handleAddVehicle} 
          onUpdateVehicle={handleUpdateVehicle}
          onDeleteVehicle={handleDeleteVehicle}
          initialVehicleId={targetVehicleId}
        />
      );
      case 'settings': return <Settings />;
      default: return <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={(view) => setActiveView(view)} />;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => setActiveView('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">AutoService <span className="text-blue-600 font-black">Pro</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => setActiveView(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative hidden xl:block">
              <Search className="w-4 h-4 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
              <input 
                type="text" 
                placeholder="Hledat..." 
                className="pl-11 pr-4 py-2 bg-slate-100 border-none rounded-2xl text-sm focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all w-64 outline-none"
              />
            </div>

            <div className="flex items-center gap-2 relative">
              <button 
                onClick={() => setIsNotifOpen(!isNotifOpen)}
                className={`p-2.5 rounded-xl transition-all relative ${isNotifOpen ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}
              >
                <Bell className="w-5 h-5" />
                {notifications.length > 0 && (
                  <span className="absolute top-2 right-2.5 w-4 h-4 bg-red-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-black">
                    {notifications.length}
                  </span>
                )}
              </button>

              {isNotifOpen && (
                <div className="absolute top-14 right-0 w-80 bg-white border border-slate-200 rounded-[2rem] shadow-2xl p-6 z-50 animate-in fade-in zoom-in-95 duration-200">
                  <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-100">
                    <h3 className="font-black text-slate-900 tracking-tight">Oznámení</h3>
                    <button onClick={() => setIsNotifOpen(false)} className="text-slate-400 hover:text-slate-600">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="max-h-96 overflow-y-auto space-y-4 pr-1">
                    {notifications.length === 0 ? (
                      <p className="py-8 text-center text-sm font-bold text-slate-400">Žádná nová upozornění</p>
                    ) : (
                      notifications.map((n, i) => (
                        <div key={i} className={`p-4 rounded-2xl border flex gap-4 ${n.type === 'stk' ? 'border-red-100 bg-red-50/30' : 'border-blue-100 bg-blue-50/30'}`}>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${n.type === 'stk' ? 'bg-white text-red-500' : 'bg-white text-blue-500'}`}>
                            {n.type === 'stk' ? <AlertTriangle className="w-5 h-5" /> : <Calendar className="w-5 h-5" />}
                          </div>
                          <div>
                            <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-0.5">{n.type === 'stk' ? 'STK' : 'Servis'}</p>
                            <p className="text-sm font-bold text-slate-900 leading-tight">{n.vehicle.licensePlate}</p>
                            <p className={`text-[11px] font-black mt-1 ${n.type === 'stk' ? 'text-red-600' : 'text-blue-600'}`}>Za {n.daysLeft} dní</p>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="w-px h-8 bg-slate-200 mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3 pl-2 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-900 leading-none">Jan Mechanik</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Administrátor</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-slate-200 border-2 border-white shadow-sm overflow-hidden ring-2 ring-transparent group-hover:ring-blue-500 transition-all">
                <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Jan" alt="Avatar" />
              </div>
            </div>

            <button 
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl"
            >
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    setActiveView(item.id as AppView);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              <div className="h-px bg-slate-100 my-2"></div>
              <button className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold">
                <LogOut className="w-5 h-5" />
                Odhlásit se
              </button>
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10">
        <div className="max-w-7xl mx-auto pb-10">
          {renderView()}
        </div>
      </main>

      <style>{`
        header nav::-webkit-scrollbar { display: none; }
        header nav { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Car, 
  Fingerprint, 
  Calendar, 
  Gauge, 
  ChevronRight, 
  ChevronDown,
  Cpu, 
  Plus, 
  X, 
  Check, 
  User,
  History,
  CheckCircle2,
  Clock3,
  AlertTriangle,
  Stethoscope,
  Search,
  Edit3,
  MoreHorizontal,
  Trash2,
  AlertCircle
} from 'lucide-react';
import { Vehicle, Customer, ServiceRecord } from '../types';

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle: Vehicle) => void;
  onUpdateVehicle?: (vehicle: Vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  initialVehicleId?: string | null;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  initialVehicleId
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [search, setSearch] = useState('');
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  };

  const [formData, setFormData] = useState(initialFormState);

  // If initialVehicleId is provided, pre-filter or scroll to it
  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) {
        setSearch(v.licensePlate);
      }
    } else {
      setSearch('');
    }
  }, [initialVehicleId, vehicles]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleHistory = (vehicleId: string) => {
    const newExpanded = new Set(expandedHistories);
    if (newExpanded.has(vehicleId)) {
      newExpanded.delete(vehicleId);
    } else {
      newExpanded.add(vehicleId);
    }
    setExpandedHistories(newExpanded);
  };

  const filteredVehicles = vehicles.filter(v => 
    v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
    v.make.toLowerCase().includes(search.toLowerCase()) ||
    v.model.toLowerCase().includes(search.toLowerCase())
  );

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) {
        onUpdateVehicle({
          ...vehicleToUpdate,
          ...formData
        });
      }
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = {
        ...formData,
        id: `v${Date.now()}`,
        lastServiceDate: new Date().toISOString().split('T')[0]
      };
      onAddVehicle(newVehicle);
    }

    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-500 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        {initialVehicleId && search && (
          <button 
            onClick={() => setSearch('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredVehicles.length > 0 ? (
          filteredVehicles.map(v => {
            const owner = customers.find(c => c.id === v.customerId);
            const vehicleServices = services.filter(s => s.vehicleId === v.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            const isHistoryExpanded = expandedHistories.has(v.id);

            return (
              <div key={v.id} className={`bg-white rounded-[2rem] border shadow-sm overflow-hidden hover:shadow-xl transition-all group flex flex-col ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
                <div className="flex flex-col md:flex-row">
                  <div className="md:w-56 bg-slate-50 p-8 flex flex-col items-center justify-center border-r border-slate-100 group-hover:bg-blue-600 group-hover:text-white transition-all duration-500 shrink-0">
                    <div className="w-24 h-24 rounded-full bg-white flex items-center justify-center shadow-lg mb-6 group-hover:scale-110 transition-transform">
                      <Car className="w-12 h-12 text-slate-900" />
                    </div>
                    <div className="bg-slate-900 text-white font-mono font-bold px-4 py-1.5 rounded-lg text-sm border-2 border-slate-700 shadow-sm group-hover:border-white transition-colors uppercase">
                      {v.licensePlate}
                    </div>
                    <p className="mt-4 text-[10px] font-black uppercase tracking-widest opacity-40 group-hover:opacity-100">Registrační značka</p>
                  </div>

                  <div className="flex-1 p-8">
                    <div className="flex justify-between items-start mb-6">
                      <div>
                        <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none mb-2">{v.make} {v.model}</h3>
                        <p className="text-sm font-bold text-blue-600">Vlastník: {owner ? `${owner.firstName} ${owner.lastName}` : 'Neznámý'}</p>
                      </div>
                      <div className="relative">
                        <button 
                          onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)}
                          className={`p-3 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}
                        >
                          <MoreHorizontal className="w-5 h-5" />
                        </button>

                        {openMenuId === v.id && (
                          <div 
                            ref={menuRef}
                            className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                          >
                            <button 
                              onClick={() => handleEdit(v)}
                              className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                            >
                              <Edit3 className="w-4 h-4 text-slate-400" />
                              Upravit kartu
                            </button>
                            <button 
                              onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }}
                              className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                            >
                              <Trash2 className="w-4 h-4" />
                              Smazat kartu
                            </button>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                      <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3">
                        <div className="p-2 bg-white rounded-xl shadow-sm"><Calendar className="w-4 h-4 text-slate-500" /></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Expirace STK</p>
                          <p className="text-sm font-bold text-slate-900">{v.stkExpirationDate}</p>
                        </div>
                      </div>
                      <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3">
                        <div className="p-2 bg-white rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-500" /></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Příští servis</p>
                          <p className="text-sm font-bold text-slate-900">{v.nextServiceDate}</p>
                        </div>
                      </div>
                      <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3">
                        <div className="p-2 bg-white rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-500" /></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Nájezd km</p>
                          <p className="text-sm font-bold text-slate-900">{v.mileage.toLocaleString()}</p>
                        </div>
                      </div>
                      <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3">
                        <div className="p-2 bg-white rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-500" /></div>
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Kód motoru</p>
                          <p className="text-sm font-bold text-slate-900">{v.engineCode || 'N/A'}</p>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                      <div className="flex items-center gap-2">
                        <Fingerprint className="w-4 h-4 text-slate-300" />
                        <span className="text-[11px] font-bold text-slate-400 font-mono">VIN: {v.vin}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={() => toggleHistory(v.id)}
                          className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-wider transition-all ${
                            isHistoryExpanded ? 'bg-slate-900 text-white' : 'text-blue-600 hover:bg-blue-50'
                          }`}
                        >
                          <History className="w-4 h-4" />
                          {isHistoryExpanded ? 'Zavřít historii' : 'Detail historie'}
                          {isHistoryExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>

                {isHistoryExpanded && (
                  <div className="bg-slate-50 border-t border-slate-100 p-8 animate-in slide-in-from-top-4 duration-300">
                    <div className="flex items-center gap-3 mb-6">
                      <History className="w-5 h-5 text-slate-400" />
                      <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">Kompletní servisní historie</h4>
                    </div>

                    {vehicleServices.length > 0 ? (
                      <div className="space-y-4">
                        {vehicleServices.map((service, idx) => (
                          <div key={service.id} className="relative flex gap-6">
                            {idx !== vehicleServices.length - 1 && (
                              <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-200"></div>
                            )}

                            <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 ${
                              service.status === 'hotovo' ? 'bg-emerald-100 text-emerald-600' : 
                              service.status === 'naplánováno' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'
                            }`}>
                              {service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : 
                               service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
                            </div>

                            <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                              <div>
                                <div className="flex items-center gap-2 mb-1">
                                  <span className="text-xs font-black text-slate-900">{service.date}</span>
                                  <span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${
                                    service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-700' : 
                                    service.status === 'naplánováno' ? 'bg-blue-50 text-blue-700' : 'bg-amber-50 text-amber-700'
                                  }`}>
                                    {service.status}
                                  </span>
                                </div>
                                <p className="text-sm font-medium text-slate-600">{service.description}</p>
                                <div className="flex items-center gap-2 mt-2">
                                  <User className="w-3 h-3 text-slate-400" />
                                  <span className="text-[10px] font-bold text-slate-400">Technik: {service.technician}</span>
                                </div>
                              </div>
                              <div className="text-right shrink-0">
                                <p className="text-lg font-black text-slate-900">{service.cost.toLocaleString()} Kč</p>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="text-center py-10 bg-white/50 rounded-3xl border-2 border-dashed border-slate-200">
                        <p className="text-slate-400 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="bg-white/50 border-4 border-dashed border-slate-200 rounded-[2.5rem] py-20 flex flex-col items-center justify-center text-center">
            <Car className="w-16 h-16 text-slate-200 mb-4" />
            <h3 className="text-xl font-bold text-slate-400">Žádná vozidla nebyla nalezena</h3>
          </div>
        )}
      </div>

      {/* Delete Confirmation Modal */}
      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat kartu vozidla <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate})</span>? Tato akce je nevratná.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingVehicle(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal remains the same */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3>
                <p className="text-blue-100 text-xs font-bold uppercase tracking-widest mt-1">
                  {editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}
                </p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník</label>
                <select 
                  required
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                  value={formData.customerId}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                >
                  <option value="">Vyberte zákazníka...</option>
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label>
                <input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label>
                <input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ</label>
                <input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN</label>
                <input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label>
                <input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label>
                <input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.engineCode} onChange={e => setFormData({...formData, engineCode: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nájezd km</label>
                <input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.mileage} onChange={e => setFormData({...formData, mileage: parseInt(e.target.value)})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Barva</label>
                <input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.color} onChange={e => setFormData({...formData, color: e.target.value})} />
              </div>

              <button 
                type="submit"
                className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
}

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle
}) => {
  const [search, setSearch] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: ''
  });

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filtered = customers.filter(c => 
    `${c.firstName} ${c.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
    c.email.toLowerCase().includes(search.toLowerCase()) ||
    c.phone.includes(search)
  );

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData({ firstName: '', lastName: '', email: '', phone: '', address: '' });
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      phone: customer.phone,
      address: customer.address
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...formData
        });
      }
    } else {
      const newCustomer: Customer = {
        ...formData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      };
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData({ firstName: '', lastName: '', email: '', phone: '', address: '' });
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-200"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle jména, emailu nebo telefonu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit kartu
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className="w-16 h-16 rounded-2xl bg-blue-600 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-blue-600/20 group-hover:scale-105 transition-transform">
                {c.firstName[0]}{c.lastName[0]}
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-tight">{c.firstName} {c.lastName}</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Klient od {c.createdAt}</p>
              </div>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Mail className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.email}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Phone className="w-4 h-4" /></div>
                <span className="text-sm font-semibold">{c.phone}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><MapPin className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.address}</span>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
              >
                Detail
              </button>
              <button 
                onClick={() => setSelectedVehiclesCustomer(c)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider"
              >
                Vozidla
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Delete Confirmation Modal */}
      {deletingCustomer && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingCustomer(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat kartu zákazníka <span className="font-bold text-slate-900">{deletingCustomer.firstName} {deletingCustomer.lastName}</span>? Tato akce je nevratná.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingCustomer(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={confirmDelete}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Detail Modal */}
      {selectedDetailCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setSelectedDetailCustomer(null)}></div>
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-blue-600 flex items-center justify-center font-black">
                  {selectedDetailCustomer.firstName[0]}{selectedDetailCustomer.lastName[0]}
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">{selectedDetailCustomer.firstName} {selectedDetailCustomer.lastName}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Kompletní karta zákazníka</p>
                </div>
              </div>
              <button onClick={() => setSelectedDetailCustomer(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Email</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.email}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Telefon</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.phone}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Adresa</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.address || 'Neuvedeno'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Registrován</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.createdAt}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ID Zákazníka</p>
                  <p className="text-sm font-mono font-bold text-blue-600">{selectedDetailCustomer.id}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedDetailCustomer(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicles Modal */}
      {selectedVehiclesCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setSelectedVehiclesCustomer(null)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black tracking-tight">Vozidla zákazníka</h3>
                <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">
                  {selectedVehiclesCustomer.firstName} {selectedVehiclesCustomer.lastName}
                </p>
              </div>
              <button onClick={() => setSelectedVehiclesCustomer(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-8 space-y-4 max-h-[60vh] overflow-y-auto">
              {customerVehicles.length > 0 ? (
                customerVehicles.map(v => (
                  <div 
                    key={v.id} 
                    onClick={() => handleViewVehicle(v.id)}
                    className="bg-slate-50 p-5 rounded-2xl border border-slate-100 flex items-center justify-between group hover:bg-white hover:shadow-lg hover:border-blue-200 transition-all cursor-pointer"
                  >
                    <div className="flex items-center gap-5">
                      <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center">
                        <Car className="w-6 h-6 text-slate-400 group-hover:text-blue-600 transition-colors" />
                      </div>
                      <div>
                        <p className="text-sm font-black text-slate-900">{v.make} {v.model}</p>
                        <p className="text-[10px] font-bold text-blue-600 font-mono tracking-wider">{v.licensePlate}</p>
