    const now = new Date();

    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);

      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      if (diffStk >= 0 && diffStk <= 30) {
        list.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      }
