const INITIAL_SERVICES: ServiceRecord[] = [
  { id: 's1', vehicleId: 'v1', date: '2024-01-10', description: 'Výměna oleje a filtrů, kontrola brzd', cost: 4500, status: 'hotovo', technician: 'Marek' },
