    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleAddCustomer = (newCustomer: Customer) => {
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const handleUpdateCustomer = (updatedCustomer: Customer) => {
    setCustomers(prev => prev.map(c => c.id === updatedCustomer.id ? updatedCustomer : c));
  };

  const handleDeleteCustomer = (id: string) => {
    setCustomers(prev => prev.filter(c => c.id !== id));
  };

  const handleAddVehicle = (newVehicle: Vehicle) => {
    setVehicles(prev => [newVehicle, ...prev]);
  };

  const handleUpdateVehicle = (updatedVehicle: Vehicle) => {
    setVehicles(prev => prev.map(v => v.id === updatedVehicle.id ? updatedVehicle : v));
  };

  const handleDeleteVehicle = (id: string) => {
    setVehicles(prev => prev.filter(v => v.id !== id));
  };

  const handleNavigateToVehicle = (vehicleId: string) => {
    setTargetVehicleId(vehicleId);
    setActiveView('vehicles');
  };

  useEffect(() => {
    if (activeView !== 'vehicles') {
      setTargetVehicleId(null);
    }
  }, [activeView]);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return (
        <Dashboard 
          customers={customers} 
          vehicles={vehicles} 
          services={services} 
          onNavigate={handleNavigate} 
        />
      );
      case 'orders': return (
        <OrderManager 
          services={services} 
          vehicles={vehicles} 
          customers={customers} 
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'customers': return (
        <CustomerManager 
          customers={customers} 
          vehicles={vehicles} 
          setCustomers={setCustomers} 
          onAddCustomer={handleAddCustomer}
          onUpdateCustomer={handleUpdateCustomer}
          onDeleteCustomer={handleDeleteCustomer}
          onNavigateToVehicle={handleNavigateToVehicle}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} 
          customers={customers} 
          services={services} 
          onAddVehicle={handleAddVehicle} 
          onUpdateVehicle={handleUpdateVehicle}
          onDeleteVehicle={handleDeleteVehicle}
          initialVehicleId={targetVehicleId}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
