                <input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.color} onChange={e => setFormData({...formData, color: e.target.value})} />
