import React, { useState, useEffect } from 'react';
import { ClipboardList, Plus, Clock, User, Car, ArrowRight, X, Check, Search } from 'lucide-react';
import { ServiceRecord, Vehicle, Customer } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
}

const OrderManager: React.FC<OrderManagerProps> = ({ services, vehicles, customers, autoOpen, onModalOpened, initialOrderId }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');

  const [formData, setFormData] = useState({
    vehicleId: '',
    description: '',
    date: new Date().toISOString().split('T')[0],
    technician: 'Jan Mechanik',
    cost: 0,
    status: 'naplánováno' as const
  });

  useEffect(() => {
    if (autoOpen) {
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      setSearch(initialOrderId);
    } else {
      setSearch('');
    }
  }, [initialOrderId]);

  const filteredOrders = services.filter(order => {
    if (!search) return order.status === 'naplánováno' || order.status === 'probíhá' || order.status === 'hotovo';

    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);

    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // V reálné aplikaci by zde bylo volání onAddService
    console.log('Nová zakázka:', formData);
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Přehled a evidence servisních prací.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat zakázku podle ID, popisu, SPZ nebo příjmení..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        {search && (
          <button 
            onClick={() => setSearch('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-6">
        {filteredOrders.length > 0 ? (
          filteredOrders.map(order => {
            const vehicle = vehicles.find(v => v.id === order.vehicleId);
            const owner = customers.find(c => c.id === vehicle?.customerId);

            return (
              <div key={order.id} className={`bg-white rounded-[2rem] border shadow-sm p-8 hover:shadow-xl transition-all group flex flex-col lg:flex-row items-start lg:items-center gap-8 ${initialOrderId === order.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
                <div className="flex items-center gap-6 min-w-[300px]">
                  <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${order.status === 'probíhá' ? 'bg-amber-500 shadow-amber-500/20' : order.status === 'hotovo' ? 'bg-emerald-500 shadow-emerald-500/20' : 'bg-blue-500 shadow-blue-500/20'}`}>
                    {order.status === 'hotovo' ? <Check className="w-8 h-8" /> : <Clock className="w-8 h-8" />}
                  </div>
                  <div>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2.5 py-1 rounded-full mb-2 inline-block ${order.status === 'probíhá' ? 'bg-amber-50 text-amber-600' : order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                      {order.status}
                    </span>
                    <h3 className="text-xl font-black text-slate-900 leading-none">#{order.id} - {order.date}</h3>
                  </div>
                </div>

                <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6 w-full">
                  <div className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl">
                    <div className="p-2 bg-white rounded-xl"><Car className="w-5 h-5 text-slate-400" /></div>
                    <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Vozidlo</p>
                      <p className="text-sm font-bold text-slate-800">{vehicle?.make} {vehicle?.model} ({vehicle?.licensePlate})</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 bg-slate-50 p-4 rounded-2xl">
                    <div className="p-2 bg-white rounded-xl"><User className="w-5 h-5 text-slate-400" /></div>
                    <div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Zákazník</p>
                      <p className="text-sm font-bold text-slate-800">{owner?.firstName} {owner?.lastName}</p>
                    </div>
                  </div>
                </div>

                <div className="lg:w-64">
                   <p className="text-sm font-medium text-slate-500 italic">"{order.description}"</p>
                </div>

                <button className="w-full lg:w-auto px-6 py-4 bg-slate-900 text-white rounded-2xl font-bold text-xs hover:bg-slate-800 transition-all flex items-center justify-center gap-2 group-hover:translate-x-1 transition-transform">
                  DETAIL <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            );
          })
        ) : (
          <div className="bg-white/50 border-4 border-dashed border-slate-100 rounded-[2.5rem] py-20 flex flex-col items-center justify-center text-center">
             <ClipboardList className="w-16 h-16 text-slate-200 mb-4" />
             <h3 className="text-xl font-bold text-slate-400">Žádné odpovídající zakázky</h3>
          </div>
        )}
      </div>

      {/* New Order Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">Nová servisní zakázka</h3>
                <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">Založení servisního listu</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vozidlo</label>
                <select 
                  required
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                  value={formData.vehicleId}
                  onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                >
                  <option value="">Vyberte vozidlo...</option>
                  {vehicles.map(v => (
                    <option key={v.id} value={v.id}>{v.make} {v.model} ({v.licensePlate})</option>
                  ))}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Popis závady / práce</label>
                <textarea 
                  required
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold min-h-[100px] resize-none"
                  placeholder="Např. výměna oleje, kontrola brzd..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Datum přijetí</label>
                  <input 
                    type="date"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Technik</label>
                  <input 
                    type="text"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                    value={formData.technician}
                    onChange={e => setFormData({...formData, technician: e.target.value})}
                  />
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                ZALOŽIT ZAKÁZKU
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

