                      <select 
                        required
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-11 pr-4 py-3.5 outline-none transition-all font-bold appearance-none"
                        value={formData.vehicleId}
                        onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                      >
                        <option value="">Vyberte vozidlo...</option>
                        {vehicles.map(v => (
                          <option key={v.id} value={v.id}>{v.make} {v.model} ({v.licensePlate})</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  {selectedVehicle && (
                    <div className="bg-blue-50 p-5 rounded-[2rem] border border-blue-100 animate-in fade-in slide-in-from-top-2 duration-300">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-sm">
                          <User className="w-6 h-6 text-blue-600" />
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-blue-400 uppercase">Majitel vozidla</p>
                          <p className="text-sm font-black text-blue-900">{selectedCustomer?.firstName} {selectedCustomer?.lastName}</p>
                          <p className="text-[10px] font-bold text-blue-800/60">{selectedCustomer?.phone} | {selectedCustomer?.email}</p>
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Přijetí do opravy</label>
                      <input 
                        required
                        type="date"
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3.5 outline-none transition-all font-bold"
                        value={formData.date}
                        onChange={e => setFormData({...formData, date: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Termín dokončení</label>
                      <input 
                        type="date"
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3.5 outline-none transition-all font-bold"
                        value={formData.endDate}
                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Popis závady / Účel zakázky</label>
                    <textarea 
                      required
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-4 outline-none transition-all font-bold min-h-[120px] resize-none"
                      placeholder="Uveďte důvod návštěvy nebo zjištěné závady..."
                      value={formData.description}
                      onChange={e => setFormData({...formData, description: e.target.value})}
                    />
                  </div>
                </div>

                {/* Right Column: Parts & Cost */}
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                      <Package className="w-3 h-3" /> Použité díly a materiál
                    </label>
                    <textarea 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-4 outline-none transition-all font-bold min-h-[120px] resize-none"
                      placeholder="Vypište použité náhradní díly a spotřební materiál..."
                      value={formData.parts}
                      onChange={e => setFormData({...formData, parts: e.target.value})}
                    />
                  </div>

                  <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 space-y-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200 pb-3 flex items-center gap-2">
                      <Calculator className="w-3 h-3" /> Kalkulace ceny
                    </h4>

                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-500 uppercase">Práce (hodin)</label>
                        <input 
                          type="number"
                          step="0.5"
                          min="0"
                          className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 font-black text-sm outline-none focus:ring-2 focus:ring-blue-500"
                          value={formData.laborHours}
                          onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})}
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-500 uppercase">Sazba/hod</label>
                        <p className="px-4 py-2 font-black text-sm text-slate-400 bg-slate-100 rounded-xl">{hourlyRate} Kč</p>
                      </div>
                      <div className="col-span-2 space-y-1">
                        <label className="text-[10px] font-black text-slate-500 uppercase">Materiál a díly celkem (Kč)</label>
                        <div className="relative">
                          <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                          <input 
                            type="number"
                            min="0"
                            className="w-full bg-white border border-slate-200 rounded-xl pl-9 pr-4 py-2 font-black text-sm outline-none focus:ring-2 focus:ring-blue-500"
                            value={formData.materialCost}
                            onChange={e => setFormData({...formData, materialCost: parseInt(e.target.value) || 0})}
                          />
                        </div>
                      </div>
                    </div>

                    <div className="pt-4 border-t border-slate-200 flex items-center justify-between">
                      <p className="text-[10px] font-black text-blue-600 uppercase">Předpokládaná cena</p>
                      <p className="text-2xl font-black text-blue-900">{calculatedCost.toLocaleString()} Kč</p>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Status zakázky</label>
                    <select 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3.5 outline-none transition-all font-bold"
                      value={formData.status}
                      onChange={e => setFormData({...formData, status: e.target.value as any})}
                    >
                      <option value="naplánováno">Naplánováno</option>
                      <option value="probíhá">Probíhá</option>
                      <option value="hotovo">Hotovo</option>
                      <option value="zrušeno">Zrušeno</option>
                    </select>
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl shadow-2xl shadow-blue-600/30 transition-all flex items-center justify-center gap-2 mt-4 text-lg"
              >
                <Check className="w-6 h-6" />
                VYTVOŘIT SERVISNÍ ZAKÁZKU
              </button>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

export default OrderManager;

export interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string; // Datum vypršení technické kontroly
  nextServiceDate: string;    // Datum příštího plánovaného servisu
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  description: string;
  parts?: string;
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  // New fields based on professional form
  fuelLevel?: string;
  accessories?: string[];
  mileageAtEntry?: number;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'orders' | 'settings';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, Clock, User, Car, ArrowRight, X, Check, 
  Search, Package, Calculator, DollarSign, Gauge, Fuel, ShieldCheck 
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  onAddService: (service: ServiceRecord) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
}

const ACCESSORIES_LIST = [
  'Rezerva', 'Trojúhelník', 'Lékárna', 'Klíč kolový', 'Nářadí', 'Hustilka', 'Rádio/Přehrávač'
];

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  onAddService,
  autoOpen, 
  onModalOpened, 
  initialOrderId 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');

  const [formData, setFormData] = useState({
    vehicleId: '',
    description: '',
    parts: '',
    date: new Date().toISOString().split('T')[0],
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    materialCost: 0,
    status: 'naplánováno' as const,
    fuelLevel: '1/2',
    mileageAtEntry: 0,
    accessories: [] as string[]
  });

  const selectedVehicle = useMemo(() => 
    vehicles.find(v => v.id === formData.vehicleId),
  [formData.vehicleId, vehicles]);

  const selectedCustomer = useMemo(() => 
    selectedVehicle ? customers.find(c => c.id === selectedVehicle.customerId) : null,
  [selectedVehicle, customers]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + formData.materialCost;
  }, [formData.laborHours, formData.materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (selectedVehicle) {
      setFormData(prev => ({ ...prev, mileageAtEntry: selectedVehicle.mileage }));
    }
  }, [selectedVehicle]);

  const toggleAccessory = (acc: string) => {
    setFormData(prev => ({
      ...prev,
      accessories: prev.accessories.includes(acc) 
        ? prev.accessories.filter(a => a !== acc) 
        : [...prev.accessories, acc]
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newService: ServiceRecord = {
      id: `s${Date.now()}`,
      vehicleId: formData.vehicleId,
      date: formData.date,
      endDate: formData.endDate || undefined,
      description: formData.description,
      parts: formData.parts,
      laborHours: formData.laborHours,
      cost: calculatedCost,
      status: formData.status,
      technician: formData.technician,
      fuelLevel: formData.fuelLevel,
      accessories: formData.accessories,
      mileageAtEntry: formData.mileageAtEntry
    };

    onAddService(newService);
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      vehicleId: '',
      description: '',
      parts: '',
      date: new Date().toISOString().split('T')[0],
      endDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      materialCost: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      accessories: []
    });
  };

  const filteredOrders = services.filter(order => {
    if (!search) return true;
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence zakázkových listů.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat zakázku..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12">
        {filteredOrders.map(order => {
          const vehicle = vehicles.find(v => v.id === order.vehicleId);
          const owner = customers.find(c => c.id === vehicle?.customerId);
          return (
            <div key={order.id} className="bg-white rounded-[2rem] border border-slate-100 shadow-sm p-8 hover:shadow-xl transition-all group flex flex-col lg:flex-row items-start lg:items-center gap-8">
              <div className="flex items-center gap-6 min-w-[250px]">
                <div className="w-16 h-16 rounded-2xl bg-blue-500 flex items-center justify-center text-white shadow-lg">
                  <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-blue-600 bg-blue-50 px-2 py-1 rounded-full">{order.status}</span>
                  <h3 className="text-xl font-black text-slate-900 mt-1">#{order.id.slice(-6)}</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase">{order.date}</p>
                </div>
              </div>
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div className="flex items-center gap-3">
                    <Car className="w-4 h-4 text-slate-400" />
                    <span className="text-sm font-bold text-slate-700">{vehicle?.make} {vehicle?.model} ({vehicle?.licensePlate})</span>
                 </div>
                 <div className="flex items-center gap-3">
                    <User className="w-4 h-4 text-slate-400" />
                    <span className="text-sm font-bold text-slate-700">{owner?.lastName} {owner?.firstName}</span>
                 </div>
              </div>
              <div className="text-right">
                <p className="text-xl font-black text-slate-900">{order.cost.toLocaleString()} Kč</p>
                <button className="text-blue-600 text-xs font-black uppercase tracking-widest mt-1 hover:underline flex items-center gap-1">Detail <ArrowRight className="w-3 h-3"/></button>
              </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh]">

            {/* Modal Header */}
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-md">
                   <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-3xl font-black tracking-tight uppercase">ZAKÁZKOVÝ LIST</h3>
                  <p className="text-blue-100 text-[10px] font-black uppercase tracking-[0.2em] mt-1">Nová objednávka zakázky</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-8 h-8" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">

              {/* Top Info Grid */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-1 bg-slate-200 border border-slate-200 rounded-3xl overflow-hidden">
                <div className="bg-white p-6 space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">ZÁKAZNÍK</label>
                  <select 
                    required
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 outline-none transition-all font-bold appearance-none"
                    value={formData.vehicleId}
                    onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                  >
                    <option value="">Vyberte vozidlo...</option>
                    {vehicles.map(v => (
                      <option key={v.id} value={v.id}>{v.licensePlate} - {v.make} {v.model}</option>
                    ))}
                  </select>
                  {selectedCustomer && (
                    <div className="mt-2 space-y-1">
                      <p className="text-sm font-black text-slate-900">{selectedCustomer.companyName || `${selectedCustomer.firstName} ${selectedCustomer.lastName}`}</p>
                      <p className="text-xs font-bold text-slate-500">{selectedCustomer.phone}</p>
                      <p className="text-xs text-slate-400">{selectedCustomer.address}</p>
                    </div>
                  )}
                </div>

                <div className="bg-white p-6 grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">VOZIDLO</label>
                    <p className="text-sm font-black text-slate-900">{selectedVehicle ? `${selectedVehicle.make} ${selectedVehicle.model}` : '---'}</p>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">RZ</label>
                    <p className="text-sm font-mono font-bold text-blue-600">{selectedVehicle?.licensePlate || '---'}</p>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">TACHOMETR</label>
                    <div className="flex items-center gap-2 mt-1">
                      <Gauge className="w-4 h-4 text-slate-300" />
                      <input 
                        type="number" 
                        className="bg-transparent font-bold text-sm w-full outline-none focus:text-blue-600"
                        value={formData.mileageAtEntry}
                        onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">ČÍSLO MOTORU</label>
                    <p className="text-sm font-bold text-slate-500">{selectedVehicle?.engineCode || '---'}</p>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PHM</label>
                    <select 
                      className="bg-transparent font-bold text-sm w-full outline-none"
                      value={formData.fuelLevel}
                      onChange={e => setFormData({...formData, fuelLevel: e.target.value})}
                    >
                      <option value="1/4">1/4</option>
                      <option value="1/2">1/2</option>
                      <option value="3/4">3/4</option>
                      <option value="Plná">Plná</option>
                    </select>
                  </div>
                </div>

                <div className="bg-white p-6 space-y-4">
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PŘIJATO DNE</label>
                        <input type="date" className="text-sm font-bold text-slate-900 bg-slate-50 rounded-lg p-2 w-full mt-1" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">TERMÍN DOKONČENÍ</label>
                        <input type="date" className="text-sm font-bold text-slate-900 bg-slate-50 rounded-lg p-2 w-full mt-1" value={formData.endDate} onChange={e => setFormData({...formData, endDate: e.target.value})} />
                      </div>
                   </div>
                   <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100 flex items-center justify-between">
                      <p className="text-[10px] font-black text-slate-400 uppercase">PŘEDBĚŽNÁ CENA</p>
                      <p className="text-xl font-black text-blue-600">{calculatedCost.toLocaleString()} Kč</p>
                   </div>
                </div>
              </div>

              {/* Accessories Grid */}
              <div className="bg-white p-8 rounded-[2rem] border border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                  <ShieldCheck className="w-4 h-4 text-emerald-500" /> PŘEVZATO S PŘÍSLUŠENSTVÍM
                </h4>
                <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-7 gap-4">
                  {ACCESSORIES_LIST.map(acc => (
                    <button 
                      key={acc}
                      type="button"
                      onClick={() => toggleAccessory(acc)}
                      className={`px-3 py-4 rounded-2xl text-[10px] font-black uppercase text-center transition-all border-2 ${
                        formData.accessories.includes(acc) 
                          ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-200' 
                          : 'bg-slate-50 text-slate-400 border-transparent hover:border-slate-200'
                      }`}
                    >
                      {acc}
                    </button>
                  ))}
                </div>
              </div>

              {/* Main Form Body (Split) */}
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-1 bg-slate-200 border border-slate-200 rounded-[2.5rem] overflow-hidden">

                {/* Left: Scope of Repair */}
                <div className="lg:col-span-7 bg-white p-8 space-y-6">
                  <div className="flex items-center gap-3 border-b border-slate-100 pb-4">
                    <ClipboardList className="w-5 h-5 text-blue-600" />
                    <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">ROZSAH OBJEDNANÉ OPRAVY</h4>
                  </div>
                  <textarea 
                    required
                    className="w-full min-h-[300px] text-sm font-medium text-slate-600 outline-none resize-none leading-relaxed placeholder:italic"
                    placeholder="Popište podrobně požadované práce, zjištěné závady nebo specifické požadavky zákazníka..."
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
