      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} 
          customers={customers} 
          services={services} 
          onAddVehicle={(v) => setVehicles([v, ...vehicles])} 
          onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))}
          onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))}
          initialVehicleId={targetVehicleId}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
        />
