                    <div className="flex items-center gap-2 mt-1">
                      <Gauge className="w-4 h-4 text-slate-300" />
                      <input 
                        type="number" 
                        className="bg-transparent font-bold text-sm w-full outline-none focus:text-blue-600"
                        value={formData.mileageAtEntry}
                        onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PHM</label>
                    <select 
                      className="bg-transparent font-bold text-sm w-full outline-none"
