import React, { useState, useMemo, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Users, 
  Car, 
  Search,
  Plus,
  Bell,
  LogOut,
  X,
  ClipboardList,
  Settings as SettingsIcon,
  AlertTriangle,
  Calendar,
  Wrench,
