                    placeholder="Popište úkony, závady..."
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                  />
                  <div className="pt-4 space-y-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block flex items-center gap-2">
                      <Package className="w-4 h-4" /> MATERIÁL A DÍLY
                    </label>
                    <textarea 
                      className="w-full min-h-[100px] bg-slate-50 p-4 rounded-2xl text-sm font-bold text-slate-700 outline-none border-2 border-transparent focus:border-blue-500 transition-all resize-none"
                      placeholder="Rozpis použitého materiálu..."
                      value={formData.parts}
                      onChange={e => setFormData({...formData, parts: e.target.value})}
                    />
                  </div>
                </div>

                <div className="lg:col-span-5 bg-slate-50 p-8 flex flex-col">
                  <div className="flex items-center gap-3 border-b border-slate-200 pb-4 mb-6">
                    <Calculator className="w-5 h-5 text-blue-600" />
                    <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">KALKULACE</h4>
