                  <div className="space-y-6 flex-1">
                    <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-6">
                      <div className="flex justify-between items-center text-xs font-black text-slate-400 uppercase">
                        <span>Hodinová sazba</span>
                        <span className="text-slate-900">{hourlyRate} Kč</span>
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PRÁCE (HODIN)</label>
                        <input 
                          type="number" step="0.5" 
                          className="w-full text-2xl font-black text-blue-600 bg-slate-50 rounded-2xl p-4 outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                          value={formData.laborHours}
                          onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})}
                        />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">MATERIÁL (Kč)</label>
                        <div className="relative">
                          <DollarSign className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                          <input 
                            type="number" 
                            className="w-full text-2xl font-black text-slate-900 bg-slate-50 rounded-2xl pl-12 pr-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                            value={formData.materialCost}
                            onChange={e => setFormData({...formData, materialCost: parseInt(e.target.value) || 0})}
                          />
                        </div>
                      </div>
                    </div>

                    <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-2xl relative mt-auto">
                      <div className="space-y-4">
                        <div className="flex justify-between items-center opacity-60 text-[10px] font-black uppercase">
                          <span>Technik</span>
                          <span>{formData.technician}</span>
                        </div>
                        <div className="flex justify-between items-end pt-2">
                          <div>
                            <span className="text-[10px] font-black uppercase text-blue-400 tracking-widest">FINÁLNÍ ČÁSTKA</span>
                            <p className="text-4xl font-black leading-none mt-2">{calculatedCost.toLocaleString()} Kč</p>
