                  </div>
                </div>
              </div>

              <div className="flex flex-col md:flex-row gap-6 pt-4 items-center justify-end">
                <button 
                  type="submit"
                  className={`w-full md:w-auto font-black py-5 px-16 rounded-[2rem] shadow-2xl transition-all flex items-center justify-center gap-3 text-lg group ${
                    editingOrderId ? 'bg-slate-900 hover:bg-slate-800 shadow-slate-300' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'
                  }`}
                >
                  <Check className="w-6 h-6 group-hover:scale-110 transition-transform" />
                  {editingOrderId ? 'AKTUALIZOVAT ZAKÁZKU' : 'VYSTAVIT ZAKÁZKU'}
