          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh]">

            <div className={`p-8 text-white flex justify-between items-center shrink-0 ${editingOrderId ? 'bg-slate-900' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-md">
                   <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-3xl font-black tracking-tight uppercase">
                    {editingOrderId ? `ZAKÁZKA ${editingOrderId}` : 'NOVÝ ZAKÁZKOVÝ LIST'}
