                <div className="lg:col-span-5 bg-slate-50 p-8 flex flex-col">
                  <div className="flex items-center gap-3 border-b border-slate-200 pb-4 mb-6">
                    <Calculator className="w-5 h-5 text-blue-600" />
                    <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">KALKULACE</h4>
                  </div>

                  <div className="space-y-6 flex-1">
                    <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-6">
                      <div className="flex justify-between items-center text-xs font-black text-slate-400 uppercase">
                        <span>Hodinová sazba</span>
                        <span className="text-slate-900">{hourlyRate} Kč</span>
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PRÁCE (HODIN)</label>
                        <input 
                          type="number" step="0.5" 
                          className="w-full text-2xl font-black text-blue-600 bg-slate-50 rounded-2xl p-4 outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                          value={formData.laborHours}
                          onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})}
                        />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">MATERIÁL (Kč)</label>
                        <div className="relative">
                          <DollarSign className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                          <input 
                            type="number" 
                            className="w-full text-2xl font-black text-slate-900 bg-slate-50 rounded-2xl pl-12 pr-4 py-4 outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                            value={formData.materialCost}
                            onChange={e => setFormData({...formData, materialCost: parseInt(e.target.value) || 0})}
                          />
                        </div>
                      </div>
                    </div>

                    <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-2xl relative mt-auto">
                      <div className="space-y-4">
                        <div className="flex justify-between items-center opacity-60 text-[10px] font-black uppercase">
                          <span>Technik</span>
                          <span>{formData.technician}</span>
                        </div>
                        <div className="flex justify-between items-end pt-2">
                          <div>
                            <span className="text-[10px] font-black uppercase text-blue-400 tracking-widest">FINÁLNÍ ČÁSTKA</span>
                            <p className="text-4xl font-black leading-none mt-2">{calculatedCost.toLocaleString()} Kč</p>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex flex-col md:flex-row gap-6 pt-4 items-center justify-end">
                <button 
                  type="submit"
                  className={`w-full md:w-auto font-black py-5 px-16 rounded-[2rem] shadow-2xl transition-all flex items-center justify-center gap-3 text-lg group ${
                    editingOrderId ? 'bg-slate-900 hover:bg-slate-800 shadow-slate-300' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'
                  }`}
                >
                  <Check className="w-6 h-6 group-hover:scale-110 transition-transform" />
                  {editingOrderId ? 'AKTUALIZOVAT ZAKÁZKU' : 'VYSTAVIT ZAKÁZKU'}
                </button>
              </div>

            </form>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f8fafc;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }

        /* Ruled paper look for textarea */
        .ruled-textarea {
          background-image: linear-gradient(#e2e8f0 1px, transparent 1px);
          background-size: 100% 1.625rem; /* Matches leading-relaxed line height */
          background-attachment: local;
          line-height: 1.625rem;
          padding-top: 0.5rem;
          padding-bottom: 0.5rem;
        }

        .ruled-textarea:focus {
          background-image: linear-gradient(#cbd5e1 1px, transparent 1px);
        }
      `}</style>
    </div>
  );
};

const CheckCircle2 = (props: any) => (
  <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"/><path d="m9 12 2 2 4-4"/></svg>
);

export default OrderManager;

export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
}

export interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string; // Datum vypršení technické kontroly
  nextServiceDate: string;    // Datum příštího plánovaného servisu
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  description: string;
  parts?: PartItem[];
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  // New fields based on professional form
  fuelLevel?: string;
  accessories?: string[];
  mileageAtEntry?: number;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'orders' | 'settings';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, Clock, User, Car, ArrowRight, X, Check, 
  Search, Package, Calculator, DollarSign, Gauge, Fuel, ShieldCheck,
  RotateCcw, Trash2
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
}

const ACCESSORIES_LIST = [
  'Rezerva', 'Trojúhelník', 'Lékárna', 'Klíč kolový', 'Nářadí', 'Hustilka', 'Rádio/Přehrávač'
];

type StatusFilter = 'all' | 'waiting' | 'active' | 'done';

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  onAddService,
  onUpdateService,
  autoOpen, 
  onModalOpened, 
  initialOrderId 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2',
    mileageAtEntry: 0,
    accessories: [] as string[]
  });

  const selectedVehicle = useMemo(() => 
    vehicles.find(v => v.id === formData.vehicleId),
  [formData.vehicleId, vehicles]);

  const selectedCustomer = useMemo(() => 
    selectedVehicle ? customers.find(c => c.id === selectedVehicle.customerId) : null,
  [selectedVehicle, customers]);

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
      }
    }
  }, [initialOrderId, services]);

  const toggleAccessory = (acc: string) => {
    setFormData(prev => ({
      ...prev,
      accessories: prev.accessories.includes(acc) 
        ? prev.accessories.filter(a => a !== acc) 
        : [...prev.accessories, acc]
    }));
  };

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      accessories: order.accessories || []
    });
    setIsModalOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;

    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');

