                        className="bg-transparent font-bold text-sm w-full outline-none focus:text-blue-600"
                        value={formData.mileageAtEntry}
                        onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PHM</label>
                    <select 
                      className="bg-transparent font-bold text-sm w-full outline-none"
                      value={formData.fuelLevel}
                      onChange={e => setFormData({...formData, fuelLevel: e.target.value})}
                    >
                      <option value="1/4">1/4 nádrže</option>
                      <option value="1/2">1/2 nádrže</option>
                      <option value="3/4">3/4 nádrže</option>
                      <option value="Plná">Plná nádrž</option>
                    </select>
                  </div>
                  <div className="col-span-2 mt-2">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">STAV ZAKÁZKY</label>
                     <div className="grid grid-cols-3 gap-1 bg-slate-100 p-1 rounded-xl mt-1">
                        {(['naplánováno', 'probíhá', 'hotovo'] as ServiceRecord['status'][]).map(s => (
                          <button
                            key={s}
                            type="button"
                            onClick={() => setFormData({...formData, status: s})}
                            className={`py-2 rounded-lg text-[9px] font-black uppercase tracking-tight transition-all ${
                              formData.status === s 
