                   <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">DATUM PŘÍJMU</label>
                        <input type="date" className="text-sm font-bold text-slate-900 bg-slate-50 rounded-lg p-2 w-full mt-1" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
