                        <input type="date" className="text-sm font-bold text-slate-900 bg-slate-50 rounded-lg p-2 w-full mt-1" value={formData.endDate} onChange={e => setFormData({...formData, endDate: e.target.value})} />
                      </div>
                   </div>
                   <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between text-slate-900 shadow-sm">
                      <p className="text-[10px] font-black uppercase text-slate-400">ZAKÁZKA č.</p>
                      <p className="text-xl font-black font-mono">
                        {editingOrderId ? editingOrderId : generateNewId()}
                      </p>
                   </div>
                </div>
              </div>

              <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
