  { id: '24/01/001', vehicleId: 'v1', date: '2024-01-10', description: 'Výměna oleje a filtrů, kontrola brzd', cost: 4500, status: 'hotovo', technician: 'Marek' },
  { id: '25/02/001', vehicleId: 'v2', date: '2024-05-20', description: 'Garanční prohlídka', cost: 3200, status: 'naplánováno', technician: 'Tomáš' },
  { id: '25/02/002', vehicleId: 'v4', date: '2024-05-25', description: 'Výměna brzdových destiček', cost: 12000, status: 'probíhá', technician: 'Filip' },
];

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [services, setServices] = useState<ServiceRecord[]>(INITIAL_SERVICES);
  const [hourlyRate, setHourlyRate] = useState(850);
  const [selectedPrinter, setSelectedPrinter] = useState<string>('Systémová tiskárna (výchozí)');

  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  const notifications = useMemo(() => {
    const list: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();

    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);

      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      if (diffStk >= 0 && diffStk <= 30) {
        list.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      }
      if (diffService >= 0 && diffService <= 15) {
        list.push({ type: 'service', vehicle: v, daysLeft: diffService });
      }
    });
    return list;
  }, [vehicles]);

  const navItems = [
    { id: 'dashboard', label: 'Přehled', icon: LayoutDashboard },
    { id: 'orders', label: 'Zakázky', icon: ClipboardList },
    { id: 'customers', label: 'Zákazníci', icon: Users },
    { id: 'vehicles', label: 'Vozidla', icon: Car },
    { id: 'settings', label: 'Nastavení', icon: SettingsIcon },
  ];

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  /**
   * Synchronizes vehicle mileage if the order mileage is higher than current record.
   */
  const syncVehicleMileage = (vehicleId: string, orderMileage: number | undefined) => {
    if (!orderMileage) return;
    setVehicles(prev => prev.map(v => {
      if (v.id === vehicleId && orderMileage > v.mileage) {
        return { ...v, mileage: orderMileage };
      }
      return v;
    }));
  };

  const handleAddService = (newService: ServiceRecord) => {
    setServices(prev => [newService, ...prev]);
    syncVehicleMileage(newService.vehicleId, newService.mileageAtEntry);
  };

  const handleUpdateService = (updatedService: ServiceRecord) => {
    setServices(prev => prev.map(s => s.id === updatedService.id ? updatedService : s));
    syncVehicleMileage(updatedService.vehicleId, updatedService.mileageAtEntry);
  };

  const handleNavigateToVehicle = (vehicleId: string) => {
    setTargetVehicleId(vehicleId);
    setActiveView('vehicles');
  };

  const handleNavigateToOrder = (orderId: string) => {
    setTargetOrderId(orderId);
    setActiveView('orders');
  };

  const handleNavigateToCustomer = (customerId: string) => {
    setTargetCustomerId(customerId);
    setActiveView('customers');
  };

  useEffect(() => {
    if (activeView !== 'vehicles') {
      setTargetVehicleId(null);
    }
    if (activeView !== 'orders') {
      setTargetOrderId(null);
    }
    if (activeView !== 'customers') {
      setTargetCustomerId(null);
    }
  }, [activeView]);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return (
        <Dashboard 
          customers={customers} 
          vehicles={vehicles} 
          services={services} 
          onNavigate={handleNavigate} 
          onViewVehicle={handleNavigateToVehicle}
          onViewOrder={handleNavigateToOrder}
        />
      );
      case 'orders': return (
        <OrderManager 
          services={services} 
          vehicles={vehicles} 
          customers={customers} 
          hourlyRate={hourlyRate}
          onAddService={handleAddService}
          onUpdateService={handleUpdateService}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
          initialOrderId={targetOrderId}
          selectedPrinter={selectedPrinter}
        />
      );
      case 'customers': return (
        <CustomerManager 
          customers={customers} 
          vehicles={vehicles} 
          setCustomers={setCustomers} 
          onAddCustomer={(c) => setCustomers([c, ...customers])}
          onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))}
          onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))}
          onNavigateToVehicle={handleNavigateToVehicle}
          initialCustomerId={targetCustomerId}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} 
          customers={customers} 
          services={services} 
          onAddVehicle={(v) => setVehicles([v, ...vehicles])} 
          onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))}
          onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))}
          onNavigateToCustomer={handleNavigateToCustomer}
          onNavigateToOrder={handleNavigateToOrder}
          initialVehicleId={targetVehicleId}
          autoOpen={shouldOpenModal}
          onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'settings': return (
        <Settings 
          hourlyRate={hourlyRate} 
          onRateChange={setHourlyRate} 
          selectedPrinter={selectedPrinter}
          onPrinterChange={setSelectedPrinter}
        />
      );
      default: return <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} />;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">AutoService <span className="text-blue-600 font-black">Pro</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 relative">
              <button 
                onClick={() => setIsNotifOpen(!isNotifOpen)}
                className={`p-2.5 rounded-xl transition-all relative ${isNotifOpen ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}
              >
                <Bell className="w-5 h-5" />
                {notifications.length > 0 && (
                  <span className="absolute top-2 right-2.5 w-4 h-4 bg-red-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-black">
                    {notifications.length}
                  </span>
                )}
              </button>

              {isNotifOpen && (
                <div className="absolute top-14 right-0 w-80 bg-white border border-slate-200 rounded-[2rem] shadow-2xl p-6 z-50 animate-in fade-in zoom-in-95 duration-200">
                  <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-100">
                    <h3 className="font-black text-slate-900 tracking-tight">Oznámení</h3>
                    <button onClick={() => setIsNotifOpen(false)} className="text-slate-400 hover:text-slate-600">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="max-h-96 overflow-y-auto space-y-4 pr-1">
                    {notifications.length === 0 ? (
                      <p className="py-8 text-center text-sm font-bold text-slate-400">Žádná nová upozornění</p>
                    ) : (
                      notifications.map((n, i) => (
                        <div key={i} className={`p-4 rounded-2xl border flex gap-4 ${n.type === 'stk' ? 'border-red-100 bg-red-50/30' : 'border-blue-100 bg-blue-50/30'}`}>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${n.type === 'stk' ? 'bg-white text-red-500' : 'bg-white text-blue-500'}`}>
                            {n.type === 'stk' ? <AlertTriangle className="w-5 h-5" /> : <Calendar className="w-5 h-5" />}
                          </div>
                          <div>
                            <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-0.5">{n.type === 'stk' ? 'STK' : 'Servis'}</p>
                            <p className="text-sm font-bold text-slate-900 leading-tight">{n.vehicle.licensePlate}</p>
                            <p className={`text-[11px] font-black mt-1 ${n.type === 'stk' ? 'text-red-600' : 'text-blue-600'}`}>Za {n.daysLeft} dní</p>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="w-px h-8 bg-slate-200 mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3 pl-2 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-900 leading-none">Jan Mechanik</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Administrátor</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-slate-200 border-2 border-white shadow-sm overflow-hidden ring-2 ring-transparent group-hover:ring-blue-500 transition-all">
                <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Jan" alt="Avatar" />
              </div>
            </div>

            <button 
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl"
            >
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    handleNavigate(item.id as AppView);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              <div className="h-px bg-slate-100 my-2"></div>
              <button className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold">
                <LogOut className="w-5 h-5" />
                Odhlásit se
              </button>
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {renderView()}
        </div>
      </main>

      <style>{`
        header nav::-webkit-scrollbar { display: none; }
        header nav { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle,
  Building2,
  Briefcase
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
}

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened
}) => {
  const [search, setSearch] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    if (initialCustomerId) {
      const c = customers.find(item => item.id === initialCustomerId);
      if (c) {
        setSearch(c.lastName || c.companyName || '');
      }
    } else if (!autoOpen) {
      setSearch('');
    }
  }, [initialCustomerId, customers, autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filtered = customers.filter(c => 
    `${c.firstName} ${c.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
    c.email.toLowerCase().includes(search.toLowerCase()) ||
    (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
    c.phone.includes(search)
  );

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      phone: customer.phone,
      address: customer.address,
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Clean up empty optional fields
    const submissionData = {
      ...formData,
      companyName: formData.companyName.trim() || undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        });
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      };
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-200"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle jména, emailu, firmy nebo telefonu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        {initialCustomerId && search && (
          <button 
            onClick={() => setSearch('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit kartu
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105 ${c.companyName ? 'bg-slate-900 shadow-slate-900/20' : 'bg-blue-600 shadow-blue-600/20'}`}>
                {c.companyName ? <Building2 className="w-8 h-8" /> : <>{c.firstName[0]}{c.lastName[0]}</>}
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-tight">
                  {c.companyName || `${c.firstName} ${c.lastName}`}
                </h3>
                {c.companyName && (
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter mt-0.5">
                    Kontakt: {c.firstName} {c.lastName}
                  </p>
                )}
                <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter mt-0.5">Klient od {c.createdAt}</p>
              </div>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Mail className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.email}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><Phone className="w-4 h-4" /></div>
                <span className="text-sm font-semibold">{c.phone}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <div className="p-2 bg-slate-50 rounded-lg"><MapPin className="w-4 h-4" /></div>
                <span className="text-sm font-semibold truncate">{c.address}</span>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
              >
                Detail
              </button>
              <button 
                onClick={() => setSelectedVehiclesCustomer(c)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider"
              >
                Vozidla
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Delete Confirmation Modal */}
      {deletingCustomer && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingCustomer(null)}></div>
