               <div>Tiskárna: {selectedPrinter}</div>
               <div>Vytištěno ze systému AutoService Pro &bull; {new Date().toLocaleString()}</div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f8fafc;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }

        /* Ruled paper look for textarea */
        .ruled-textarea {
          background-image: linear-gradient(#e2e8f0 1px, transparent 1px);
          background-size: 100% 1.625rem; /* Matches leading-relaxed line height */
          background-attachment: local;
          line-height: 1.625rem;
          padding-top: 0.5rem;
          padding-bottom: 0.5rem;
        }

        .ruled-textarea:focus {
          background-image: linear-gradient(#cbd5e1 1px, transparent 1px);
        }

        @media print {
          body * {
            visibility: hidden;
          }
          .print-block, .print-block * {
            visibility: visible;
          }
          .print-block {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
          }
          @page {
            size: A4;
            margin: 0;
          }
          body {
            background: white !important;
          }
        }
      `}</style>
    </div>
  );
};

