const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [users, setUsers] = useState<UserAccount[]>(INITIAL_USERS);
  const [currentUser, setCurrentUser] = useState<UserAccount>(INITIAL_USERS[0]);
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [services, setServices] = useState<ServiceRecord[]>(INITIAL_SERVICES);
  const [hourlyRate, setHourlyRate] = useState(850);
  const [selectedPrinter, setSelectedPrinter] = useState<string>('Systémová tiskárna (výchozí)');

  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  const isAdmin = currentUser.role === 'admin';

  useEffect(() => {
    // If a host is somehow on a restricted view, redirect to vehicles
    if (!isAdmin && ['customers', 'orders', 'settings'].includes(activeView)) {
      setActiveView('vehicles');
    }
  }, [currentUser, activeView]);

  const notifications = useMemo(() => {
    const list: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();
    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);
      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (diffStk >= 0 && diffStk <= 30) list.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      if (diffService >= 0 && diffService <= 15) list.push({ type: 'service', vehicle: v, daysLeft: diffService });
    });
    return list;
  }, [vehicles]);

  const navItems = [
    { id: 'dashboard', label: 'Přehled', icon: LayoutDashboard, visible: true },
    { id: 'orders', label: 'Zakázky', icon: ClipboardList, visible: isAdmin },
    { id: 'customers', label: 'Zákazníci', icon: Users, visible: isAdmin },
    { id: 'vehicles', label: 'Vozidla', icon: Car, visible: true },
    { id: 'settings', label: 'Nastavení', icon: SettingsIcon, visible: true },
  ].filter(item => item.visible);

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const syncVehicleMileage = (vehicleId: string, orderMileage: number | undefined) => {
    if (!orderMileage || !isAdmin) return;
    setVehicles(prev => prev.map(v => (v.id === vehicleId && orderMileage > v.mileage) ? { ...v, mileage: orderMileage } : v));
  };

  const handleAddService = (newService: ServiceRecord) => {
    if (!isAdmin) return;
    setServices(prev => [newService, ...prev]);
    syncVehicleMileage(newService.vehicleId, newService.mileageAtEntry);
  };

  const handleUpdateService = (updatedService: ServiceRecord) => {
    if (!isAdmin) return;
    setServices(prev => prev.map(s => s.id === updatedService.id ? updatedService : s));
    syncVehicleMileage(updatedService.vehicleId, updatedService.mileageAtEntry);
  };

  const handleDeleteService = (orderId: string) => {
    if (!isAdmin) return;
    setServices(prev => prev.filter(s => s.id !== orderId));
  };

  const handleNavigateToVehicle = (vehicleId: string) => {
    setTargetVehicleId(vehicleId);
    setActiveView('vehicles');
  };

  const handleNavigateToOrder = (orderId: string) => {
    if (!isAdmin) return;
    setTargetOrderId(orderId);
    setActiveView('orders');
  };

  const handleNavigateToCustomer = (customerId: string) => {
    if (!isAdmin) return;
    setTargetCustomerId(customerId);
    setActiveView('customers');
  };

  const handleSwitchUser = (user: UserAccount) => {
    setCurrentUser(user);
    setIsMobileMenuOpen(false);
    setActiveView('dashboard');
  };

  const handleAddUser = (user: UserAccount) => {
    setUsers([...users, user]);
  };

  const handleDeleteUser = (userId: string) => {
    if (users.length <= 1) return;
    setUsers(users.filter(u => u.id !== userId));
  };

  useEffect(() => {
    if (activeView !== 'vehicles') setTargetVehicleId(null);
    if (activeView !== 'orders') setTargetOrderId(null);
    if (activeView !== 'customers') setTargetCustomerId(null);
  }, [activeView]);

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return (
        <Dashboard 
          customers={customers} 
          vehicles={vehicles} 
          services={services} 
          onNavigate={handleNavigate} 
          onViewVehicle={handleNavigateToVehicle}
          onViewOrder={handleNavigateToOrder}
          currentUser={currentUser}
        />
      );
      case 'orders': return isAdmin ? (
        <OrderManager 
          services={services} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate}
          onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={handleDeleteService}
          autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter}
        />
      ) : null;
      case 'customers': return isAdmin ? (
        <CustomerManager 
          customers={customers} vehicles={vehicles} setCustomers={setCustomers} 
          onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))}
          onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)}
        />
      ) : null;
      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} customers={customers} services={services} 
          onAddVehicle={isAdmin ? (v) => setVehicles([v, ...vehicles]) : undefined} 
          onUpdateVehicle={isAdmin ? (v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item)) : undefined}
          onDeleteVehicle={isAdmin ? (id) => setVehicles(prev => prev.filter(item => item.id !== id)) : undefined}
          onNavigateToCustomer={isAdmin ? handleNavigateToCustomer : undefined}
          onNavigateToOrder={isAdmin ? handleNavigateToOrder : undefined}
          initialVehicleId={targetVehicleId} autoOpen={isAdmin && shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)}
          currentUser={currentUser}
        />
      );
      case 'settings': return (
        <Settings 
          hourlyRate={hourlyRate} onRateChange={setHourlyRate} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter}
          users={users} currentUser={currentUser} onSwitchUser={handleSwitchUser} onAddUser={handleAddUser} onDeleteUser={handleDeleteUser}
        />
      );
      default: return null;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">AutoService <span className="text-blue-600 font-black">Pro</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 relative">
              <button onClick={() => setIsNotifOpen(!isNotifOpen)} className={`p-2.5 rounded-xl transition-all relative ${isNotifOpen ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}>
                <Bell className="w-5 h-5" />
                {notifications.length > 0 && <span className="absolute top-2 right-2.5 w-4 h-4 bg-red-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-black">{notifications.length}</span>}
              </button>

              {isNotifOpen && (
                <div className="absolute top-14 right-0 w-80 bg-white border border-slate-200 rounded-[2rem] shadow-2xl p-6 z-50 animate-in fade-in zoom-in-95 duration-200">
                  <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-100">
                    <h3 className="font-black text-slate-900 tracking-tight">Oznámení</h3>
                    <button onClick={() => setIsNotifOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-4 h-4" /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto space-y-4 pr-1">
                    {notifications.length === 0 ? <p className="py-8 text-center text-sm font-bold text-slate-400">Žádná nová upozornění</p> : 
                      notifications.map((n, i) => (
                        <div key={i} className={`p-4 rounded-2xl border flex gap-4 ${n.type === 'stk' ? 'border-red-100 bg-red-50/30' : 'border-blue-100 bg-blue-50/30'}`}>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${n.type === 'stk' ? 'bg-white text-red-500' : 'bg-white text-blue-500'}`}>{n.type === 'stk' ? <AlertTriangle className="w-5 h-5" /> : <Calendar className="w-5 h-5" />}</div>
                          <div><p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-0.5">{n.type === 'stk' ? 'STK' : 'Servis'}</p><p className="text-sm font-bold text-slate-900 leading-tight">{n.vehicle.licensePlate}</p><p className={`text-[11px] font-black mt-1 ${n.type === 'stk' ? 'text-red-600' : 'text-blue-600'}`}>Za {n.daysLeft} dní</p></div>
                        </div>
                      ))}
                  </div>
                </div>
              )}
            </div>

            <div className="w-px h-8 bg-slate-200 mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3 pl-2 group cursor-pointer" onClick={() => setActiveView('settings')}>
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-900 leading-none">{currentUser.name}</p>
                <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-1">{currentUser.role === 'admin' ? 'Administrátor' : 'Host'}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-slate-200 border-2 border-white shadow-sm overflow-hidden ring-2 ring-transparent group-hover:ring-blue-500 transition-all">
                <img src={currentUser.avatar} alt="Avatar" />
              </div>
            </div>

            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              <div className="h-px bg-slate-100 my-2"></div>
              <button 
                onClick={() => { setIsMobileMenuOpen(false); setActiveView('settings'); }} 
                className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
              >
                <LogOut className="w-5 h-5" />
                Přepnout uživatele
              </button>
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { 
  AlertCircle, 
  Plus, 
  Car, 
  Wrench, 
  ShieldAlert, 
  UserPlus,
  ClipboardPlus,
  Clock,
  ChevronRight,
  ClipboardList
} from 'lucide-react';
import { Customer, Vehicle, ServiceRecord, AppView, UserAccount } from '../types';

interface DashboardProps {
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onNavigate: (view: AppView, autoOpen?: boolean) => void;
  onViewVehicle: (vehicleId: string) => void;
  onViewOrder: (orderId: string) => void;
  currentUser: UserAccount;
}

const Dashboard: React.FC<DashboardProps> = ({ vehicles, customers, services, onNavigate, onViewVehicle, onViewOrder, currentUser }) => {
  const [isQuickActionOpen, setIsQuickActionOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const isAdmin = currentUser.role === 'admin';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsQuickActionOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const vehicleAlerts = useMemo(() => {
    const alerts: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();
    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);
      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (diffStk >= 0 && diffStk <= 30) alerts.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      if (diffService >= 0 && diffService <= 15) alerts.push({ type: 'service', vehicle: v, daysLeft: diffService });
    });
    return alerts.sort((a, b) => a.daysLeft - b.daysLeft);
  }, [vehicles]);

  const activeOrders = useMemo(() => {
    return services.filter(s => s.status === 'naplánováno' || s.status === 'probíhá')
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [services]);

  const quickActions = [
