              <AlertCircle className="w-6 h-6" />
              <h3 className="text-2xl font-black tracking-tight">Důležitá upozornění</h3>
            </div>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar relative">
              {vehicleAlerts.length > 0 ? vehicleAlerts.map((alert, idx) => (
                <div key={idx} className={`p-6 rounded-3xl border transition-all hover:scale-[1.02] cursor-pointer ${alert.type === 'stk' ? 'bg-red-500/10 border-red-500/30 text-red-100 hover:bg-red-500/20' : 'bg-blue-500/10 border-blue-500/30 text-blue-100 hover:bg-blue-500/20'}`} onClick={() => onViewVehicle(alert.vehicle.id)}>
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-2">{alert.type === 'stk' ? <ShieldAlert className="w-4 h-4" /> : <Wrench className="w-4 h-4" />}<span className="text-[10px] font-black uppercase tracking-widest">{alert.type === 'stk' ? 'Expirace STK' : 'Plánovaný servis'}</span></div>
                    <span className={`text-[11px] font-black px-2 py-0.5 rounded-full ${alert.daysLeft <= 5 ? 'bg-red-500 text-white shadow-lg shadow-red-500/20' : 'bg-white/10 text-white'}`}>Zbývá {alert.daysLeft} dní</span>
