            </div>
            <div className="mt-8 flex items-center gap-4 text-slate-400 text-sm font-bold relative z-10 border-t border-white/5 pt-6 shrink-0"><span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>Zobrazeno {vehicleAlerts.length} upozornění</div>
          </div>
        </div>

        <div className="bg-indigo-950 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
