            </div>
            <div className="mt-8 flex items-center justify-between text-slate-400 text-sm font-bold relative z-10 border-t border-white/5 pt-6 shrink-0">
              <div className="flex items-center gap-4"><span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>{activeOrders.length} rozpracovaných úloh</div>
