              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">AutoService <span className="text-blue-600 font-black">Pro</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 relative">
              <button onClick={() => setIsNotifOpen(!isNotifOpen)} className={`p-2.5 rounded-xl transition-all relative ${isNotifOpen ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}>
                <Bell className="w-5 h-5" />
                {notifications.length > 0 && <span className="absolute top-2 right-2.5 w-4 h-4 bg-red-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-black">{notifications.length}</span>}
              </button>

              {isNotifOpen && (
                <div className="absolute top-14 right-0 w-80 bg-white border border-slate-200 rounded-[2rem] shadow-2xl p-6 z-50 animate-in fade-in zoom-in-95 duration-200">
                  <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-100">
                    <h3 className="font-black text-slate-900 tracking-tight">Oznámení</h3>
                    <button onClick={() => setIsNotifOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-4 h-4" /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto space-y-4 pr-1">
                    {notifications.length === 0 ? <p className="py-8 text-center text-sm font-bold text-slate-400">Žádná nová upozornění</p> : 
                      notifications.map((n, i) => (
                        <div key={i} className={`p-4 rounded-2xl border flex gap-4 ${n.type === 'stk' ? 'border-red-100 bg-red-50/30' : 'border-blue-100 bg-blue-50/30'}`}>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${n.type === 'stk' ? 'bg-white text-red-500' : 'bg-white text-blue-500'}`}>{n.type === 'stk' ? <AlertTriangle className="w-5 h-5" /> : <Calendar className="w-5 h-5" />}</div>
                          <div><p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-0.5">{n.type === 'stk' ? 'STK' : 'Servis'}</p><p className="text-sm font-bold text-slate-900 leading-tight">{n.vehicle.licensePlate}</p><p className={`text-[11px] font-black mt-1 ${n.type === 'stk' ? 'text-red-600' : 'text-blue-600'}`}>Za {n.daysLeft} dní</p></div>
                        </div>
                      ))}
                  </div>
                </div>
              )}
            </div>

            <div className="w-px h-8 bg-slate-200 mx-2 hidden sm:block"></div>

            <div className="flex items-center gap-3 pl-2 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-900 leading-none">Jan Mechanik</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Administrátor</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-slate-200 border-2 border-white shadow-sm overflow-hidden ring-2 ring-transparent group-hover:ring-blue-500 transition-all">
                <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Jan" alt="Avatar" />
              </div>
            </div>

            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              <div className="h-px bg-slate-100 my-2"></div>
              <button className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold">
                <LogOut className="w-5 h-5" />
                Odhlásit se
              </button>
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

