const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [services, setServices] = useState<ServiceRecord[]>(INITIAL_SERVICES);

  // Settings States
  const [hourlyRate, setHourlyRate] = useState(850);
  const [selectedPrinter, setSelectedPrinter] = useState<string>('HP LaserJet Pro M404dn (Kancelář)');
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>({
    name: 'AutoService Pro Praha',
    address: 'Průmyslová 1024/12, 102 00 Praha 10',
    ico: '12345678',
    dic: 'CZ12345678',
    phone: '+420 222 333 444',
    email: 'servis@autoservice.pro'
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>({
    stkThresholdDays: 30,
    serviceThresholdDays: 15
  });
  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  const [directoryHandle, setDirectoryHandle] = useState<FileSystemDirectoryHandle | null>(null);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  // XML Generation Logic
  const generateXmlData = useCallback(() => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<AutoServiceBackup version="1.0" timestamp="${timestamp}">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += `      <FirstName>${c.firstName}</FirstName>\n`;
      xml += `      <LastName>${c.lastName}</LastName>\n`;
      xml += `      <Email>${c.email}</Email>\n`;
      xml += `      <Phone>${c.phone}</Phone>\n`;
      xml += `      <Address>${c.address}</Address>\n`;
      xml += `      <CreatedAt>${c.createdAt}</CreatedAt>\n`;
      if (c.companyName) xml += `      <CompanyName>${c.companyName}</CompanyName>\n`;
      if (c.ico) xml += `      <ICO>${c.ico}</ICO>\n`;
      if (c.dic) xml += `      <DIC>${c.dic}</DIC>\n`;
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += `      <Make>${v.make}</Make>\n`;
      xml += `      <Model>${v.model}</Model>\n`;
      xml += `      <Year>${v.year}</Year>\n`;
      xml += `      <VIN>${v.vin}</VIN>\n`;
      xml += `      <LicensePlate>${v.licensePlate}</LicensePlate>\n`;
      xml += `      <Mileage>${v.mileage}</Mileage>\n`;
      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  }, [customers, vehicles, services]);

  // Persistent background check for auto-backup
  useEffect(() => {
    if (!autoBackupSettings.enabled) return;

    const checkBackup = async () => {
      const now = new Date();
      const currentHour = now.getHours();
      const currentDateStr = now.toISOString().split('T')[0];

      if (currentHour === autoBackupSettings.hour && autoBackupSettings.lastBackupDate !== currentDateStr) {
        try {
          if (directoryHandle) {
            const xmlData = generateXmlData();
            const fileName = `autoservice_daily_backup.xml`;

            const options = { mode: 'readwrite' };
            // In most browsers queryPermission requires user interaction, 
            // but if we have the handle from current session it should be granted.
            const permission = await directoryHandle.queryPermission(options);

            if (permission === 'granted') {
              const fileHandle = await directoryHandle.getFileHandle(fileName, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(xmlData);
              await writable.close();

              const updatedSettings = { ...autoBackupSettings, lastBackupDate: currentDateStr };
              setAutoBackupSettings(updatedSettings);
              localStorage.setItem('autoBackupSettings', JSON.stringify(updatedSettings));
              console.log("Auto-backup successful at", now.toLocaleTimeString());
            }
          }
        } catch (err) {
          console.error("Auto-backup background process failed:", err);
        }
      }
    };

    const interval = setInterval(checkBackup, 60000); // Check every 1 minute
    return () => clearInterval(interval);
  }, [autoBackupSettings, directoryHandle, generateXmlData]);

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (newCustomers: Customer[], newVehicles: Vehicle[], newServices: ServiceRecord[]) => {
    setCustomers(newCustomers);
    setVehicles(newVehicles);
    setServices(newServices);
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return (
        <Dashboard 
          customers={customers} 
          vehicles={vehicles} 
          services={services} 
          onNavigate={handleNavigate} 
          onViewVehicle={handleNavigateToVehicle}
          onViewOrder={handleNavigateToOrder}
          notifSettings={notifSettings}
        />
      );
      case 'orders': return (
        <OrderManager 
          services={services} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate}
          onAddService={(s) => setServices([s, ...services])} onUpdateService={(s) => setServices(prev => prev.map(item => item.id === s.id ? s : item))} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))}
          autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter}
        />
      );
      case 'customers': return (
        <CustomerManager 
          customers={customers} vehicles={vehicles} setCustomers={setCustomers} 
          onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))}
          onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'vehicles': return (
        <VehicleManager 
          vehicles={vehicles} customers={customers} services={services} 
          onAddVehicle={(v) => setVehicles([v, ...vehicles])} 
          onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))}
          onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))}
          onNavigateToCustomer={handleNavigateToCustomer}
          onNavigateToOrder={handleNavigateToOrder}
          initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)}
        />
      );
      case 'settings': return (
        <Settings 
          hourlyRate={hourlyRate} 
          onRateChange={setHourlyRate} 
          selectedPrinter={selectedPrinter} 
          onPrinterChange={setSelectedPrinter}
          companyInfo={companyInfo}
          onCompanyChange={setCompanyInfo}
          notifSettings={notifSettings}
          onNotifSettingsChange={setNotifSettings}
          customers={customers}
          vehicles={vehicles}
          services={services}
          onRestoreData={handleRestoreData}
          autoBackupSettings={autoBackupSettings}
          onAutoBackupSettingsChange={(s) => {
            setAutoBackupSettings(s);
            localStorage.setItem('autoBackupSettings', JSON.stringify(s));
          }}
          setDirectoryHandle={setDirectoryHandle}
          directoryHandle={directoryHandle}
        />
      );
      default: return null;
    }
  };

  const handleNavigateToVehicle = (vehicleId: string) => {
    setTargetVehicleId(vehicleId);
    setActiveView('vehicles');
  };

  const handleNavigateToOrder = (orderId: string) => {
    setTargetOrderId(orderId);
    setActiveView('orders');
  };

  const handleNavigateToCustomer = (customerId: string) => {
    setTargetCustomerId(customerId);
    setActiveView('customers');
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">AutoService <span className="text-blue-600 font-black">Pro</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              <div className="h-px bg-slate-100 my-2"></div>
              <button className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold">
                <LogOut className="w-5 h-5" />
                Odhlásit se
              </button>
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Shield, Mail, Check, Save, 
  Clock, DollarSign, Printer, Search, Loader2, CheckCircle2,
  Settings as SettingsIcon, Wifi, Laptop, MapPin, Hash, Phone, CalendarRange,
  Wrench, Database, DownloadCloud, FileCode, AlertCircle, UploadCloud, RotateCcw,
  FolderPlus, ToggleLeft, ToggleRight, Laptop2
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, PartItem, AutoBackupSettings } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  // Data for backup
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  // Data restoration
  onRestoreData: (customers: Customer[], vehicles: Vehicle[], services: ServiceRecord[]) => void;
  // Auto backup
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: any) => void;
  directoryHandle: any;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, 
  onRateChange, 
  selectedPrinter, 
  onPrinterChange,
  companyInfo,
  onCompanyChange,
  notifSettings,
  onNotifSettingsChange,
  customers,
  vehicles,
  services,
  onRestoreData,
  autoBackupSettings,
  onAutoBackupSettingsChange,
  setDirectoryHandle,
  directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'printers' | 'backups'>('company');
  const [isScanning, setIsScanning] = useState(false);
  const [foundPrinters, setFoundPrinters] = useState<string[]>([]);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [restoreStatus, setRestoreStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScanPrinters = () => {
    setIsScanning(true);
    setTimeout(() => {
      setFoundPrinters([
        'HP LaserJet Pro M404dn (Kancelář)',
        'Brother HL-L2350DW (Dílna)',
        'Epson Stylus Photo P50',
        'Zebra ZD421 (Štítkovač)',
        'Microsoft Print to PDF'
      ]);
      setIsScanning(false);
    }, 1500);
  };

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<AutoServiceBackup version="1.0" timestamp="${timestamp}">\n`;

    // Customers
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += `      <FirstName>${c.firstName}</FirstName>\n`;
      xml += `      <LastName>${c.lastName}</LastName>\n`;
      xml += `      <Email>${c.email}</Email>\n`;
      xml += `      <Phone>${c.phone}</Phone>\n`;
      xml += `      <Address>${c.address}</Address>\n`;
      xml += `      <CreatedAt>${c.createdAt}</CreatedAt>\n`;
      if (c.companyName) xml += `      <CompanyName>${c.companyName}</CompanyName>\n`;
      if (c.ico) xml += `      <ICO>${c.ico}</ICO>\n`;
      if (c.dic) xml += `      <DIC>${c.dic}</DIC>\n`;
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // Vehicles
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += `      <Make>${v.make}</Make>\n`;
      xml += `      <Model>${v.model}</Model>\n`;
      xml += `      <Year>${v.year}</Year>\n`;
      xml += `      <VIN>${v.vin}</VIN>\n`;
      xml += `      <LicensePlate>${v.licensePlate}</LicensePlate>\n`;
      xml += `      <Mileage>${v.mileage}</Mileage>\n`;
      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // Services
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const dateStr = new Date().toISOString().split('T')[0];
      const timeStr = new Date().toLocaleTimeString('cs-CZ').replace(/:/g, '-');
      const fileName = `autoservice_backup_${dateStr}_${timeStr}.xml`;

      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      link.click();
      URL.revokeObjectURL(url);

      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) {
      console.error('Backup error:', err);
      setBackupStatus('error');
      setTimeout(() => setBackupStatus('idle'), 3000);
    }
  };

  const handleRestoreBackup = (file: File) => {
    setRestoreStatus('processing');
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const xmlText = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlText, 'text/xml');

        const customersNode = xmlDoc.getElementsByTagName('Customers')[0];
        const vehiclesNode = xmlDoc.getElementsByTagName('Vehicles')[0];
        const servicesNode = xmlDoc.getElementsByTagName('Services')[0];

        if (!customersNode || !vehiclesNode || !servicesNode) {
          throw new Error('Neplatný formát zálohy XML.');
        }

        const restoredCustomers: Customer[] = [];
        const customerElements = customersNode.getElementsByTagName('Customer');
        for (let i = 0; i < customerElements.length; i++) {
          const el = customerElements[i];
          restoredCustomers.push({
            id: el.getAttribute('id') || '',
            firstName: el.getElementsByTagName('FirstName')[0]?.textContent || '',
            lastName: el.getElementsByTagName('LastName')[0]?.textContent || '',
            email: el.getElementsByTagName('Email')[0]?.textContent || '',
            phone: el.getElementsByTagName('Phone')[0]?.textContent || '',
            address: el.getElementsByTagName('Address')[0]?.textContent || '',
            createdAt: el.getElementsByTagName('CreatedAt')[0]?.textContent || '',
            companyName: el.getElementsByTagName('CompanyName')[0]?.textContent || undefined,
            ico: el.getElementsByTagName('ICO')[0]?.textContent || undefined,
            dic: el.getElementsByTagName('DIC')[0]?.textContent || undefined,
          });
        }

        const restoredVehicles: Vehicle[] = [];
        const vehicleElements = vehiclesNode.getElementsByTagName('Vehicle');
        for (let i = 0; i < vehicleElements.length; i++) {
          const el = vehicleElements[i];
          restoredVehicles.push({
            id: el.getAttribute('id') || '',
            customerId: el.getAttribute('customerId') || '',
            make: el.getElementsByTagName('Make')[0]?.textContent || '',
            model: el.getElementsByTagName('Model')[0]?.textContent || '',
            year: parseInt(el.getElementsByTagName('Year')[0]?.textContent || '0'),
            vin: el.getElementsByTagName('VIN')[0]?.textContent || '',
            licensePlate: el.getElementsByTagName('LicensePlate')[0]?.textContent || '',
            mileage: parseInt(el.getElementsByTagName('Mileage')[0]?.textContent || '0'),
            engineCode: el.getElementsByTagName('EngineCode')[0]?.textContent || '',
            color: el.getElementsByTagName('Color')[0]?.textContent || '',
            lastServiceDate: '', 
            stkExpirationDate: el.getElementsByTagName('STKExpiration')[0]?.textContent || '',
            nextServiceDate: el.getElementsByTagName('NextService')[0]?.textContent || '',
          });
        }

        const restoredServices: ServiceRecord[] = [];
        const serviceElements = servicesNode.getElementsByTagName('ServiceRecord');
        for (let i = 0; i < serviceElements.length; i++) {
          const el = serviceElements[i];
          const parts: PartItem[] = [];
          const partsNode = el.getElementsByTagName('Parts')[0];
          if (partsNode) {
            const partElements = partsNode.getElementsByTagName('Part');
            for (let j = 0; j < partElements.length; j++) {
              const pEl = partElements[j];
              parts.push({
                id: `p${Date.now()}_${j}`,
                description: pEl.getElementsByTagName('Description')[0]?.textContent || '',
                quantity: parseFloat(pEl.getElementsByTagName('Quantity')[0]?.textContent || '0'),
                unitPrice: parseFloat(pEl.getElementsByTagName('UnitPrice')[0]?.textContent || '0'),
                unit: 'ks',
              });
            }
          }

          restoredServices.push({
            id: el.getAttribute('id') || '',
            vehicleId: el.getAttribute('vehicleId') || '',
            date: el.getElementsByTagName('Date')[0]?.textContent || '',
            description: el.getElementsByTagName('Description')[0]?.textContent || '',
            cost: parseFloat(el.getElementsByTagName('Cost')[0]?.textContent || '0'),
            status: el.getElementsByTagName('Status')[0]?.textContent as any || 'hotovo',
            technician: el.getElementsByTagName('Technician')[0]?.textContent || '',
            parts: parts.length > 0 ? parts : undefined,
          });
        }

        onRestoreData(restoredCustomers, restoredVehicles, restoredServices);
        setRestoreStatus('success');
        setTimeout(() => setRestoreStatus('idle'), 3000);
      } catch (err) {
        console.error('Restore error:', err);
        setRestoreStatus('error');
        setTimeout(() => setRestoreStatus('idle'), 3000);
      }
    };
    reader.readAsText(file);
  };

  const handlePickAutoBackupFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const dirHandle = await (window as any).showDirectoryPicker();
        setDirectoryHandle(dirHandle);
        onAutoBackupSettingsChange({
          ...autoBackupSettings,
          folderName: dirHandle.name
        });
      } catch (err) {
        console.error('Pick directory error:', err);
      }
    } else {
      alert('Tento prohlížeč nepodporuje přímý přístup k složkám. Zkuste Google Chrome nebo Microsoft Edge.');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu a uživatelského prostředí.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-4 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'printers', label: 'Tiskárna', icon: Printer },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id 
                ? 'bg-white text-slate-900 shadow-sm' 
                : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se budou zobrazovat na zakázkových listech</p>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Building className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.name}
                    onChange={e => onCompanyChange({...companyInfo, name: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Sídlo / Adresa</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><MapPin className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.address}
                    onChange={e => onCompanyChange({...companyInfo, address: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Hash className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.ico}
                    onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Hash className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.dic}
                    onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefon</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Phone className="w-4 h-4" /></div>
                  <input 
                    type="tel" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.phone}
                    onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Mail className="w-4 h-4" /></div>
                  <input 
                    type="email" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.email}
                    onChange={e => onCompanyChange({...companyInfo, email: e.target.value})}
                  />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center">
                    <Database className="w-8 h-8 text-slate-900" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tight">Zálohování a obnova</h3>
                    <p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">SPRÁVA DATABÁZE SERVISU</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-900 p-8 rounded-3xl text-white space-y-6 relative overflow-hidden border border-slate-800 shadow-2xl">
                <div className="absolute right-0 top-0 w-32 h-32 bg-blue-500/10 rounded-full blur-2xl -mr-16 -mt-16"></div>
                <div className="flex items-center gap-3 relative z-10">
                    <DownloadCloud className="w-6 h-6 text-blue-400" />
                    <h4 className="font-black">Rychlá záloha</h4>
                </div>
                <div className="space-y-4 relative z-10">
                  <p className="text-sm font-medium text-slate-400 leading-relaxed">
                    Okamžitě vygeneruje XML soubor obsahující veškerá data servisu a nabídne jej ke stažení. Tato metoda je nejspolehlivější pro bezpečné uchování vašich dat.
                  </p>
                  <button 
                    onClick={handleDownloadBackup}
                    disabled={backupStatus === 'processing'}
                    className={`w-full py-4 rounded-2xl font-black text-xs transition-all flex items-center justify-center gap-3 shadow-xl ${
                      backupStatus === 'success' ? 'bg-emerald-500' : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                  >
                    {backupStatus === 'processing' ? <Loader2 className="w-4 h-4 animate-spin" /> : backupStatus === 'success' ? <Check className="w-4 h-4" /> : <FileCode className="w-4 h-4" />}
                    {backupStatus === 'processing' ? 'GENERUJI XML...' : backupStatus === 'success' ? 'ZÁLOHA DOKONČENA' : 'STÁHNOUT XML ZÁLOHU'}
                  </button>
                </div>
              </div>

              <div className="bg-white p-8 rounded-3xl border-4 border-dashed border-slate-200 space-y-6 relative overflow-hidden hover:border-blue-300 transition-all group">
                <div className="flex items-center gap-3 relative z-10">
                    <UploadCloud className="w-6 h-6 text-blue-600" />
                    <h4 className="font-black text-slate-900">Obnovit ze zálohy</h4>
                </div>
                <div className="space-y-4 relative z-10">
                  <p className="text-sm font-medium text-slate-500 leading-relaxed">
                    Vyberte dříve stažený XML soubor pro obnovení celé databáze. 
                    <span className="block mt-2 font-black text-red-500 uppercase text-[10px]">POZOR: AKTUÁLNÍ DATA BUDOU PŘEPSÁNA!</span>
                  </p>
                  <input 
                    type="file" 
                    accept=".xml" 
                    ref={fileInputRef} 
                    onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) handleRestoreBackup(file);
                    }} 
                    className="hidden" 
                  />
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    disabled={restoreStatus === 'processing'}
                    className={`w-full py-4 rounded-2xl font-black text-xs transition-all flex items-center justify-center gap-3 shadow-xl ${
                      restoreStatus === 'success' ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-900 hover:bg-slate-200'
                    }`}
                  >
                    {restoreStatus === 'processing' ? <Loader2 className="w-4 h-4 animate-spin" /> : restoreStatus === 'success' ? <Check className="w-4 h-4" /> : <RotateCcw className="w-4 h-4" />}
                    {restoreStatus === 'processing' ? 'PARSUJI DATA...' : restoreStatus === 'success' ? 'DATA OBNOVENA' : 'NAHRÁT ZÁLOHU (XML)'}
                  </button>
                </div>
              </div>
            </div>

            <div className="bg-blue-50 border-2 border-blue-100 p-10 rounded-[2.5rem] space-y-8">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
                  <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-blue-200">
                      <RotateCcw className="w-8 h-8" />
                    </div>
                    <div>
                      <h4 className="text-2xl font-black text-slate-900 tracking-tight">Automatické denní zálohování</h4>
                      <p className="text-blue-600/70 text-[10px] font-black uppercase tracking-[0.2em] mt-1">KNIHOVNA NABÍZÍ AUTOMATICKÉ UKLÁDÁNÍ DO VYBRANÉ SLOŽKY</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => onAutoBackupSettingsChange({...autoBackupSettings, enabled: !autoBackupSettings.enabled})}
                    className={`flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all shadow-md ${
                      autoBackupSettings.enabled ? 'bg-emerald-500 text-white' : 'bg-slate-200 text-slate-500'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                        <div className={`w-3.5 h-3.5 rounded-full border-2 border-current ${autoBackupSettings.enabled ? 'bg-white' : ''}`}></div>
                        {autoBackupSettings.enabled ? 'ZÁLOHOVÁNÍ AKTIVNÍ' : 'ZÁLOHOVÁNÍ VYPNUTO'}
                    </div>
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-top-4 duration-500">
                    <div className="bg-white p-10 rounded-[2rem] shadow-sm space-y-6 flex flex-col items-start border border-slate-100">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">1. VYTVOŘTE / VYBERTE SLOŽKU PRO UKLÁDÁNÍ ZÁLOH</label>
                      <button 
                        onClick={handlePickAutoBackupFolder}
                        className={`w-full p-8 border-4 border-dashed rounded-[1.5rem] transition-all flex flex-col items-center justify-center gap-4 group ${
                          directoryHandle ? 'border-emerald-100 bg-emerald-50/30' : 'border-slate-100 bg-slate-50/50 hover:border-blue-200 hover:bg-blue-50/30'
                        }`}
                      >
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${
                            directoryHandle ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' : 'bg-white text-slate-400 shadow-sm group-hover:text-blue-500'
                        }`}>
                          <FolderPlus className="w-7 h-7" />
                        </div>
                        <div className="text-center">
                            <span className={`text-sm font-black transition-all ${directoryHandle ? 'text-emerald-700' : 'text-slate-500 group-hover:text-blue-700'}`}>
                                {autoBackupSettings.folderName ? autoBackupSettings.folderName : 'Vybrat složku v počítači...'}
                            </span>
                            {directoryHandle && (
                                <div className="flex items-center justify-center gap-1.5 mt-1 text-emerald-500">
                                    <CheckCircle2 className="w-3.5 h-3.5" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Složka propojena</span>
                                </div>
                            )}
                        </div>
                      </button>
                      <p className="text-[9px] font-bold text-slate-400 italic leading-relaxed">Záloha probíhá v libovolný čas, ale vždy ve stejnou hodinu. Dojde k přepsání staré zálohy.</p>
                    </div>

                    <div className="bg-white p-10 rounded-[2rem] shadow-sm space-y-6 border border-slate-100">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">2. NAPLÁNOVAT ČAS (PROBÍHÁ DENNĚ)</label>
                      <div className="flex flex-col sm:flex-row items-stretch gap-6">
                        <div className="relative flex-1">
                          <div className="absolute left-6 top-1/2 -translate-y-1/2 flex items-center gap-3">
                              <Clock className="w-5 h-5 text-slate-300" />
                          </div>
                          <select 
                            className="w-full pl-16 pr-6 py-6 bg-slate-50 border-none rounded-2xl font-black text-2xl text-slate-900 outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-100 transition-all"
                            value={autoBackupSettings.hour}
                            onChange={(e) => onAutoBackupSettingsChange({...autoBackupSettings, hour: parseInt(e.target.value)})}
                          >
                            {Array.from({length: 24}).map((_, h) => (
                              <option key={h} value={h}>{h.toString().padStart(2, '0')}:00</option>
                            ))}
                          </select>
                        </div>
                        <div className="p-6 bg-blue-50 border-2 border-blue-100 rounded-3xl flex flex-col justify-center min-w-[160px]">
                          <p className="text-[9px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1">STATUS</p>
                          <p className="text-xs font-black text-slate-700">
                            {autoBackupSettings.lastBackupDate 
                              ? `Poslední: ${autoBackupSettings.lastBackupDate}` 
                              : 'Čeká na první zálohu'}
                          </p>
                        </div>
                      </div>
                    </div>
                </div>
            </div>

            <div className="bg-amber-50 border border-amber-100 p-6 rounded-[2rem] flex gap-4">
              <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center shrink-0">
                <AlertCircle className="w-6 h-6 text-amber-500" />
              </div>
              <div>
                <h4 className="text-sm font-black text-amber-900 uppercase tracking-widest mb-1">DŮLEŽITÉ UPOZORNĚNÍ</h4>
                <p className="text-xs font-bold text-amber-700 leading-relaxed">
                  Záloha obsahuje citlivé údaje o zákaznících a jejich vozidlech. XML soubory ukládejte na bezpečné místo. Zálohy doporučujeme provádět minimálně jednou týdně. Automatické zálohování vyžaduje, aby byla aplikace otevřena v prohlížeči.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
