const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, 
  onRateChange, 
  selectedPrinter, 
  onPrinterChange,
  companyInfo,
  onCompanyChange,
  notifSettings,
  onNotifSettingsChange,
  customers,
  vehicles,
