  directoryHandle,
  userSettings,
  onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'printers' | 'backups' | 'users'>('company');
  const [isScanning, setIsScanning] = useState(false);
  const [foundPrinters, setFoundPrinters] = useState<string[]>([]);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [restoreStatus, setRestoreStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScanPrinters = () => {
    setIsScanning(true);
    setFoundPrinters([]);
    setTimeout(() => {
      setFoundPrinters([
        'HP LaserJet Pro M404dn (Kancelář)',
        'Brother HL-L2350DW (Dílna)',
        'Epson Stylus Photo P50',
        'Zebra ZD421 (Štítkovač)',
        'Microsoft Print to PDF'
      ]);
      setIsScanning(false);
    }, 1500);
  };

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<AutoServiceBackup version="1.0" timestamp="${timestamp}">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += `      <FirstName>${c.firstName}</FirstName>\n`;
      xml += `      <LastName>${c.lastName}</LastName>\n`;
      xml += `      <Email>${c.email}</Email>\n`;
      xml += `      <Phone>${c.phone}</Phone>\n`;
      xml += `      <Address>${c.address}</Address>\n`;
      xml += `      <CreatedAt>${c.createdAt}</CreatedAt>\n`;
      if (c.companyName) xml += `      <CompanyName>${c.companyName}</CompanyName>\n`;
      if (c.ico) xml += `      <ICO>${c.ico}</ICO>\n`;
      if (c.dic) xml += `      <DIC>${c.dic}</DIC>\n`;
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += `      <Make>${v.make}</Make>\n`;
      xml += `      <Model>${v.model}</Model>\n`;
      xml += `      <Year>${v.year}</Year>\n`;
      xml += `      <VIN>${v.vin}</VIN>\n`;
      xml += `      <LicensePlate>${v.licensePlate}</LicensePlate>\n`;
      xml += `      <Mileage>${v.mileage}</Mileage>\n`;
      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const fileName = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      link.click();
      URL.revokeObjectURL(url);
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) {
      console.error('Backup error:', err);
      setBackupStatus('error');
      setTimeout(() => setBackupStatus('idle'), 3000);
    }
  };

  const handleRestoreBackup = (file: File) => {
    setRestoreStatus('processing');
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const xmlText = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(xmlText, 'text/xml');

        const getT = (node: any, tag: string) => node.getElementsByTagName(tag)[0]?.textContent || '';

        // Extract customers
        const customerNodes = xmlDoc.getElementsByTagName('Customer');
        const restoredCustomers: Customer[] = Array.from(customerNodes).map(node => ({
          id: node.getAttribute('id') || `c${Math.random()}`,
          firstName: getT(node, 'FirstName'),
          lastName: getT(node, 'LastName'),
          email: getT(node, 'Email'),
          phone: getT(node, 'Phone'),
          address: getT(node, 'Address'),
          createdAt: getT(node, 'CreatedAt') || new Date().toISOString().split('T')[0],
          companyName: getT(node, 'CompanyName') || undefined,
          ico: getT(node, 'ICO') || undefined,
          dic: getT(node, 'DIC') || undefined,
        }));

        // Extract vehicles
        const vehicleNodes = xmlDoc.getElementsByTagName('Vehicle');
        const restoredVehicles: Vehicle[] = Array.from(vehicleNodes).map(node => ({
          id: node.getAttribute('id') || `v${Math.random()}`,
          customerId: node.getAttribute('customerId') || '',
          make: getT(node, 'Make'),
          model: getT(node, 'Model'),
          year: parseInt(getT(node, 'Year')) || 2024,
          vin: getT(node, 'VIN'),
          licensePlate: getT(node, 'LicensePlate'),
          mileage: parseInt(getT(node, 'Mileage')) || 0,
          engineCode: getT(node, 'EngineCode'),
          color: getT(node, 'Color'),
          lastServiceDate: new Date().toISOString().split('T')[0],
          stkExpirationDate: getT(node, 'STKExpiration') || new Date().toISOString().split('T')[0],
          nextServiceDate: getT(node, 'NextService') || new Date().toISOString().split('T')[0],
        }));

        // Extract services
        const serviceNodes = xmlDoc.getElementsByTagName('ServiceRecord');
        const restoredServices: ServiceRecord[] = Array.from(serviceNodes).map(node => {
          const partNodes = node.getElementsByTagName('Part');
          const restoredParts: PartItem[] = Array.from(partNodes).map((p, idx) => ({
            id: `p-${idx}`,
            description: getT(p, 'Description'),
            quantity: parseFloat(getT(p, 'Quantity')) || 0,
            unit: 'ks',
            unitPrice: parseFloat(getT(p, 'UnitPrice')) || 0,
          }));

          return {
            id: node.getAttribute('id') || `s${Math.random()}`,
            vehicleId: node.getAttribute('vehicleId') || '',
            date: getT(node, 'Date'),
            description: getT(node, 'Description'),
            cost: parseFloat(getT(node, 'Cost')) || 0,
            status: getT(node, 'Status') as any,
            technician: getT(node, 'Technician'),
            parts: restoredParts
          };
        });

        if (restoredCustomers.length === 0 && restoredVehicles.length === 0) throw new Error('Invalid XML structure');

        onRestoreData(restoredCustomers, restoredVehicles, restoredServices);
        setRestoreStatus('success');
        setTimeout(() => setRestoreStatus('idle'), 3000);
      } catch (err) {
        console.error('Restore error:', err);
        setRestoreStatus('error');
        setTimeout(() => setRestoreStatus('idle'), 3000);
      }
    };
    reader.readAsText(file);
  };

  const handlePickAutoBackupFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const dirHandle = await (window as any).showDirectoryPicker();
        setDirectoryHandle(dirHandle);
        onAutoBackupSettingsChange({...autoBackupSettings, folderName: dirHandle.name});
      } catch (err) { console.error(err); }
    } else {
      alert('Tento prohlížeč nepodporuje přímý přístup k složkám.');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu a zabezpečení.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-4 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'users', label: 'Uživatelé', icon: Lock },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'printers', label: 'Tiskárna', icon: Printer },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id 
                ? 'bg-white text-slate-900 shadow-sm' 
                : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'users' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-slate-900 text-white rounded-2xl flex items-center justify-center">
                    <ShieldCheck className="w-8 h-8" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Zabezpečení systému</h3>
                    <p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Nastavení přístupových údajů a zámku aplikace</p>
                </div>
              </div>
              <button 
                onClick={() => onUserSettingsChange({...userSettings, enabled: !userSettings.enabled})}
                className={`flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all shadow-md ${
                  userSettings.enabled ? 'bg-emerald-500 text-white' : 'bg-slate-200 text-slate-500'
                }`}
              >
                <div className={`w-3.5 h-3.5 rounded-full border-2 border-current ${userSettings.enabled ? 'bg-white' : ''}`}></div>
                {userSettings.enabled ? 'ZABEZPEČENÍ AKTIVNÍ' : 'ZABEZPEČENÍ VYPNUTO'}
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Uživatelské jméno</label>
                <div className="relative">
                  <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                  <input 
                    type="text" 
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={userSettings.username}
                    onChange={e => onUserSettingsChange({...userSettings, username: e.target.value})}
                    placeholder="admin"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nové heslo</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                  <input 
                    type="password" 
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={userSettings.password}
                    onChange={e => onUserSettingsChange({...userSettings, password: e.target.value})}
                    placeholder="Zadejte nové heslo"
                  />
                </div>
              </div>
            </div>

            <div className="bg-blue-50 border border-blue-100 p-6 rounded-[2rem] flex gap-4">
              <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center shrink-0">
                <AlertCircle className="w-6 h-6 text-blue-500" />
              </div>
              <div>
                <h4 className="text-sm font-black text-blue-900 uppercase tracking-widest mb-1">DŮLEŽITÉ UPOZORNĚNÍ</h4>
                <p className="text-xs font-bold text-blue-700 leading-relaxed">
                  Pokud zapnete zabezpečení, bude systém při každém spuštění vyžadovat výše uvedené údaje. Doporučujeme si heslo pečlivě uschovat. V případě deaktivace zabezpečení bude aplikace přístupná komukoliv bez nutnosti přihlášení.
                </p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se budou zobrazovat na zakázkových listech</p>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Building className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.name}
                    onChange={e => onCompanyChange({...companyInfo, name: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Sídlo / Adresa</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><MapPin className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.address}
                    onChange={e => onCompanyChange({...companyInfo, address: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Hash className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.ico}
                    onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Hash className="w-4 h-4" /></div>
                  <input 
                    type="text" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.dic}
                    onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefon</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Phone className="w-4 h-4" /></div>
                  <input 
                    type="tel" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.phone}
                    onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Mail className="w-4 h-4" /></div>
                  <input 
                    type="email" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={companyInfo.email}
                    onChange={e => onCompanyChange({...companyInfo, email: e.target.value})}
                  />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'services' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center">
                  <DollarSign className="w-8 h-8 text-emerald-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Ceník & Služby</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Globální nastavení sazeb a poplatků</p>
               </div>
            </div>

            <div className="max-w-md">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Hodinová sazba (Kč)</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><DollarSign className="w-4 h-4" /></div>
                  <input 
                    type="number" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={hourlyRate}
                    onChange={e => onRateChange(parseInt(e.target.value) || 0)}
                  />
                </div>
                <p className="text-[10px] text-slate-400 font-bold mt-2 ml-1 uppercase tracking-tighter italic">
                  * Tato sazba se automaticky aplikuje na nové zakázky.
                </p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'printers' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                    <Printer className="w-8 h-8 text-blue-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Správa tiskáren</h3>
                    <p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Konfigurace výstupu pro zakázkové listy</p>
                </div>
              </div>
              <button 
                onClick={handleScanPrinters}
                disabled={isScanning}
                className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-slate-800 disabled:opacity-50 transition-all"
              >
                {isScanning ? <Loader2 className="w-4 h-4 animate-spin" /> : <Wifi className="w-4 h-4" />}
                {isScanning ? 'HLEDÁM...' : 'HLEDAT TISKÁRNY'}
              </button>
            </div>

            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vybraná výchozí tiskárna</label>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(foundPrinters.length > 0 ? foundPrinters : [selectedPrinter]).map(printer => (
                  <button 
                    key={printer}
                    onClick={() => onPrinterChange(printer)}
                    className={`flex items-center justify-between p-5 rounded-2xl border-2 transition-all ${
                      selectedPrinter === printer 
                        ? 'bg-blue-50 border-blue-500 shadow-md' 
                        : 'bg-slate-50 border-transparent hover:bg-slate-100'
                    }`}
                  >
                    <div className="flex items-center gap-4 text-left">
                      <div className={`p-2 rounded-lg ${selectedPrinter === printer ? 'bg-blue-600 text-white' : 'bg-white text-slate-400'}`}>
                        <Printer className="w-5 h-5" />
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-900">{printer}</p>
                        <p className="text-[10px] font-black text-slate-400 uppercase">Aktivní &bull; WiFi</p>
                      </div>
                    </div>
                    {selectedPrinter === printer && <CheckCircle2 className="w-5 h-5 text-blue-600" />}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'notifications' && (
