                  <Bell className="w-8 h-8 text-amber-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Upozornění</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Nastavení limitů pro servisní hlášení</p>
