                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={notifSettings.stkThresholdDays}
                    onChange={e => onNotifSettingsChange({...notifSettings, stkThresholdDays: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Servis limit (dny předem)</label>
                <div className="relative">
                  <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"><Wrench className="w-4 h-4" /></div>
                  <input 
                    type="number" 
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-slate-900 transition-all" 
                    value={notifSettings.serviceThresholdDays}
                    onChange={e => onNotifSettingsChange({...notifSettings, serviceThresholdDays: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>
            </div>
            <div className="bg-amber-50 border border-amber-100 p-6 rounded-[2rem] flex gap-4">
               <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center shrink-0">
                  <Info className="w-6 h-6 text-amber-500" />
               </div>
               <p className="text-xs font-bold text-amber-800 leading-relaxed">
                 Tato nastavení určují, jak dlouho předem se budou objevovat vozidla v sekci "Důležitá upozornění" na hlavní nástěnce. 
               </p>
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center">
                    <Database className="w-8 h-8 text-slate-900" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tight">Zálohování a obnova</h3>
                    <p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">SPRÁVA DATABÁZE SERVISU</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 space-y-6">
                <div>
                  <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-1">Ruční export</h4>
                  <p className="text-xs font-medium text-slate-400">Stáhnout celou databázi do souboru XML.</p>
                </div>
                <button 
                  onClick={handleDownloadBackup}
                  disabled={backupStatus === 'processing'}
                  className="w-full bg-white border-2 border-slate-200 hover:border-blue-500 hover:text-blue-600 transition-all py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 shadow-sm"
                >
                  {backupStatus === 'processing' ? <Loader2 className="w-4 h-4 animate-spin" /> : backupStatus === 'success' ? <Check className="w-4 h-4" /> : <DownloadCloud className="w-5 h-5" />}
                  {backupStatus === 'processing' ? 'EXPORTOVÁNÍ...' : backupStatus === 'success' ? 'HOTOVO' : 'STÁHNOUT ZÁLOHU'}
                </button>
              </div>

              <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 space-y-6">
                <div>
                  <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-1">Obnova dat</h4>
                  <p className="text-xs font-medium text-slate-400">Nahrát data z dříve staženého XML souboru.</p>
                </div>
                <input 
                  type="file" 
                  accept=".xml" 
                  className="hidden" 
                  ref={fileInputRef} 
                  onChange={e => e.target.files?.[0] && handleRestoreBackup(e.target.files[0])} 
                />
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  disabled={restoreStatus === 'processing'}
                  className="w-full bg-slate-900 text-white hover:bg-slate-800 transition-all py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 shadow-lg"
                >
                  {restoreStatus === 'processing' ? <Loader2 className="w-4 h-4 animate-spin" /> : restoreStatus === 'success' ? <Check className="w-4 h-4" /> : <UploadCloud className="w-5 h-5" />}
                  {restoreStatus === 'processing' ? 'OBNOVOVÁNÍ...' : restoreStatus === 'success' ? 'OBNOVENO' : 'OBNOVIT ZE SOUBORU'}
                </button>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 space-y-8">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center shadow-sm">
                      <Clock className="w-6 h-6" />
                   </div>
                   <div>
                      <h4 className="text-lg font-black text-slate-900 tracking-tight leading-none">Automatické zálohy</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Denní zabezpečení dat v PC</p>
                   </div>
                </div>
                <button 
                  onClick={() => onAutoBackupSettingsChange({...autoBackupSettings, enabled: !autoBackupSettings.enabled})}
                  className={`flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
                    autoBackupSettings.enabled ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-200 text-slate-500'
                  }`}
                >
                  {autoBackupSettings.enabled ? <ToggleRight className="w-6 h-6" /> : <ToggleLeft className="w-6 h-6" />}
                  {autoBackupSettings.enabled ? 'AKTIVNÍ' : 'VYPNUTO'}
                </button>
              </div>

              {autoBackupSettings.enabled && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 animate-in slide-in-from-top-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Čas zálohování</label>
                    <select 
                      className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl font-bold outline-none"
                      value={autoBackupSettings.hour}
                      onChange={e => onAutoBackupSettingsChange({...autoBackupSettings, hour: parseInt(e.target.value)})}
                    >
                      {Array.from({length: 24}).map((_, i) => (
                        <option key={i} value={i}>{i.toString().padStart(2, '0')}:00</option>
                      ))}
                    </select>
                  </div>

                  <div className="md:col-span-2 space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Cílový adresář (Váš počítač)</label>
                    <div 
                      onClick={handlePickAutoBackupFolder}
                      className="border-2 border-dashed border-slate-200 rounded-[2rem] p-8 flex flex-col items-center justify-center gap-3 cursor-pointer hover:bg-slate-50 hover:border-blue-400 transition-all group min-h-[160px]"
                    >
                      <div className="w-12 h-12 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 group-hover:text-blue-600 group-hover:bg-blue-50 transition-all">
                        <FolderPlus className="w-6 h-6" />
                      </div>
                      <div className="text-center">
                        <p className="text-sm font-black text-slate-900">
                          {autoBackupSettings.folderName || 'Vyberte složku pro zálohy'}
                        </p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                          {autoBackupSettings.folderName ? 'Kliknutím změníte složku' : 'Cílový adresář v tomto počítači'}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {autoBackupSettings.lastBackupDate && (
                <div className="bg-emerald-50 text-emerald-700 p-4 rounded-2xl border border-emerald-100 flex items-center gap-3">
                   <CheckCircle2 className="w-5 h-5" />
                   <p className="text-xs font-bold">Poslední úspěšná záloha proběhla: <span className="font-black">{autoBackupSettings.lastBackupDate}</span></p>
                </div>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

