import React, { useState, useRef, useEffect } from 'react';
import { 
  Building, Bell, Shield, Mail, Check, Save, 
  Clock, DollarSign, Printer, Search, Loader2, CheckCircle2,
  Settings as SettingsIcon, Wifi, Laptop, MapPin, Hash, Phone, CalendarRange,
  Wrench, Database, DownloadCloud, FileCode, AlertCircle, UploadCloud, RotateCcw,
  FolderPlus, ToggleLeft, ToggleRight, Laptop2, Lock, User as UserIcon, ShieldCheck,
  Monitor, Download, Info
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, PartItem, AutoBackupSettings, UserSettings } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onRestoreData: (customers: Customer[], vehicles: Vehicle[], services: ServiceRecord[]) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: any) => void;
  directoryHandle: any;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, selectedPrinter, onPrinterChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  userSettings, onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'printers' | 'backups' | 'users' | 'app'>('company');
  const [isScanning, setIsScanning] = useState(false);
  const [foundPrinters, setFoundPrinters] = useState<string[]>([]);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [restoreStatus, setRestoreStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallApp = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    } else {
      alert("Aplikace je již pravděpodobně nainstalována nebo prohlížeč instalaci nepodporuje. Použijte Chrome nebo Edge a v adresním řádku klikněte na ikonu 'Instalovat'.");
    }
  };

  const handleScanPrinters = () => {
    setIsScanning(true);
    setFoundPrinters([]);
    setTimeout(() => {
      setFoundPrinters([
        'HP LaserJet Pro M404dn (Kancelář)',
        'Brother HL-L2350DW (Dílna)',
        'Epson Stylus Photo P50',
        'Zebra ZD421 (Štítkovač)',
        'Microsoft Print to PDF'
      ]);
      setIsScanning(false);
    }, 1500);
  };

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}">\n`;
    xml += `  <Customers>${customers.map(c => `\n    <Customer id="${c.id}"><FirstName>${c.firstName}</FirstName><LastName>${c.lastName}</LastName></Customer>`).join('')}\n  </Customers>\n`;
    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handlePickAutoBackupFolder = async () => {
    try {
      const dirHandle = await (window as any).showDirectoryPicker();
      setDirectoryHandle(dirHandle);
      onAutoBackupSettingsChange({...autoBackupSettings, folderName: dirHandle.name});
    } catch (err) { console.error(err); }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu a zabezpečení.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'users', label: 'Uživatelé', icon: Lock },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'printers', label: 'Tiskárna', icon: Printer },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database },
          { id: 'app', label: 'Desktop App', icon: Monitor }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se budou zobrazovat na zakázkových listech</p>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Adresa</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'services' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center">
                  <DollarSign className="w-8 h-8 text-emerald-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Ceník & Služby</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Globální nastavení sazeb</p>
               </div>
            </div>
            <div className="max-w-sm">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Hodinová sazba (Kč)</label>
              <input type="number" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl font-bold" value={hourlyRate} onChange={e => onRateChange(parseInt(e.target.value) || 0)} />
            </div>
          </div>
        )}

        {activeTab === 'printers' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Printer className="w-8 h-8 text-blue-600" /></div>
                <div><h3 className="text-2xl font-black text-slate-900">Správa tiskáren</h3><p className="text-slate-400 text-xs font-bold mt-1">Konfigurace výstupu</p></div>
              </div>
              <button onClick={handleScanPrinters} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-xs">HLEDAT TISKÁRNY</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {foundPrinters.map(p => (
                <button key={p} onClick={() => onPrinterChange(p)} className={`p-5 rounded-2xl border-2 text-left flex justify-between items-center ${selectedPrinter === p ? 'bg-blue-50 border-blue-500' : 'bg-slate-50 border-transparent'}`}>
                  <span className="font-bold text-sm">{p}</span>
                  {selectedPrinter === p && <CheckCircle2 className="w-5 h-5 text-blue-600" />}
                </button>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center"><Database className="w-8 h-8 text-slate-900" /></div>
              <div><h3 className="text-2xl font-black text-slate-900">Zálohování</h3><p className="text-slate-400 text-xs font-bold mt-1">Správa databáze</p></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-6">
                <h4 className="font-black text-sm uppercase">Ruční export</h4>
                <button onClick={handleDownloadBackup} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3">
                  <DownloadCloud className="w-5 h-5" /> STÁHNOUT ZÁLOHU
                </button>
              </div>
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-6">
                <h4 className="font-black text-sm uppercase">Automatické zálohy</h4>
                <button onClick={() => onAutoBackupSettingsChange({...autoBackupSettings, enabled: !autoBackupSettings.enabled})} className={`w-full py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 ${autoBackupSettings.enabled ? 'bg-emerald-500 text-white' : 'bg-slate-200 text-slate-500'}`}>
                  {autoBackupSettings.enabled ? 'AKTIVNÍ' : 'VYPNUTO'}
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'app' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center">
                  <Monitor className="w-8 h-8 text-indigo-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Desktopová Aplikace</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Instalace systému přímo do Windows</p>
               </div>
