  { id: 'fs4', name: 'Plnění klimatizace', price: 1500 },
  { id: 'fs5', name: 'PC diagnostika', price: 850 },
  { id: 'fs6', name: 'EK+TK', price: 3800 },
  { id: 'fs7', name: 'Geometrie nápravy', price: 1200 },
];

const navItems = [
  { id: 'dashboard', label: 'Nástěnka', icon: LayoutDashboard },
  { id: 'orders', label: 'Zakázky', icon: ClipboardList },
  { id: 'customers', label: 'Zákazníci', icon: Users },
  { id: 'vehicles', label: 'Vozidla', icon: Car },
  { id: 'settings', label: 'Nastavení', icon: SettingsIcon },
];

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [services, setServices] = useState<ServiceRecord[]>(INITIAL_SERVICES);

  // Security State
  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  // Settings States
  const [hourlyRate, setHourlyRate] = useState(850);
  const [fixedServices, setFixedServices] = useState<FixedService[]>(() => {
    const saved = localStorage.getItem('fixedServices');
    return saved ? JSON.parse(saved) : INITIAL_FIXED_SERVICES;
  });

  const [selectedPrinter, setSelectedPrinter] = useState<string>('HP LaserJet Pro M404dn (Kancelář)');
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>({
    name: 'AutoService Pro Praha',
    address: 'Průmyslová 1024/12, 102 00 Praha 10',
    ico: '12345678',
    dic: 'CZ12345678',
    phone: '+420 222 333 444',
    email: 'servis@autoservice.pro'
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>({
    stkThresholdDays: 30,
    serviceThresholdDays: 15
  });
  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  const [directoryHandle, setDirectoryHandle] = useState<FileSystemDirectoryHandle | null>(null);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  // Sync settings with local storage
  useEffect(() => {
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) {
      setIsAuthenticated(true);
    }
  }, [userSettings]);

  useEffect(() => {
    localStorage.setItem('fixedServices', JSON.stringify(fixedServices));
  }, [fixedServices]);

  // XML Generation Logic
  const generateXmlData = useCallback(() => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<AutoServiceBackup version="1.0" timestamp="${timestamp}">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += `      <FirstName>${c.firstName}</FirstName>\n`;
      xml += `      <LastName>${c.lastName}</LastName>\n`;
      xml += `      <Email>${c.email}</Email>\n`;
      xml += `      <Phone>${c.phone}</Phone>\n`;
      xml += `      <Address>${c.address}</Address>\n`;
      xml += `      <CreatedAt>${c.createdAt}</CreatedAt>\n`;
      if (c.companyName) xml += `      <CompanyName>${c.companyName}</CompanyName>\n`;
      if (c.ico) xml += `      <ICO>${c.ico}</ICO>\n`;
      if (c.dic) xml += `      <DIC>${c.dic}</DIC>\n`;
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += `      <Make>${v.make}</Make>\n`;
      xml += `      <Model>${v.model}</Model>\n`;
      xml += `      <Year>${v.year}</Year>\n`;
      xml += `      <VIN>${v.vin}</VIN>\n`;
      xml += `      <LicensePlate>${v.licensePlate}</LicensePlate>\n`;
      xml += `      <Mileage>${v.mileage}</Mileage>\n`;
      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <DeliveryDate>${s.deliveryDate || ''}</DeliveryDate>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  }, [customers, vehicles, services]);

  // Auto-backup check
  useEffect(() => {
    if (!autoBackupSettings.enabled) return;
    const checkBackup = async () => {
      const now = new Date();
      if (now.getHours() === autoBackupSettings.hour && autoBackupSettings.lastBackupDate !== now.toISOString().split('T')[0]) {
        try {
          if (directoryHandle) {
            const xmlData = generateXmlData();
            const options = { mode: 'readwrite' };
            const permission = await directoryHandle.queryPermission(options);
            if (permission === 'granted') {
              const fileHandle = await directoryHandle.getFileHandle(`autoservice_daily_backup.xml`, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(xmlData);
              await writable.close();
              const updated = { ...autoBackupSettings, lastBackupDate: now.toISOString().split('T')[0] };
              setAutoBackupSettings(updated);
              localStorage.setItem('autoBackupSettings', JSON.stringify(updated));
            }
          }
        } catch (err) { console.error("Auto-backup failed:", err); }
      }
    };
    const interval = setInterval(checkBackup, 60000);
    return () => clearInterval(interval);
  }, [autoBackupSettings, directoryHandle, generateXmlData]);

  // Function to sync vehicle mileage based on service record entry
  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices([service, ...services]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (newCustomers: Customer[], newVehicles: Vehicle[], newServices: ServiceRecord[]) => {
    setCustomers(newCustomers);
    setVehicles(newVehicles);
    setServices(newServices);
  };

  const handleNavigateToVehicle = (vId: string) => { setTargetVehicleId(vId); setActiveView('vehicles'); };
  const handleNavigateToOrder = (oId: string) => { setTargetOrderId(oId); setActiveView('orders'); };
  const handleNavigateToCustomer = (cId: string) => { setTargetCustomerId(cId); setActiveView('customers'); };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">{companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'settings' && <Settings hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, Clock, User, Car, ArrowRight, X, Check, 
  Search, Package, Calculator, DollarSign, Gauge, Fuel, ShieldCheck,
  RotateCcw, Trash2, Printer, Wrench, Info, AlertCircle, Building,
  Tag, ListPlus
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
}

const ACCESSORIES_LIST = [
  'Rezerva', 'Trojúhelník', 'Lékárna', 'Klíč kolový', 'Nářadí', 'Hustilka', 'Rádio/Přehrávač'
];

type StatusFilter = 'all' | 'waiting' | 'active' | 'done';

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  selectedPrinter = 'Systémová tiskárna'
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '', // Nové pole pro předání
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2',
    mileageAtEntry: 0,
    accessories: [] as string[]
  });

  const selectedVehicle = useMemo(() => 
    vehicles.find(v => v.id === formData.vehicleId),
  [formData.vehicleId, vehicles]);

  const selectedCustomer = useMemo(() => 
    selectedVehicle ? customers.find(c => c.id === selectedVehicle.customerId) : null,
  [selectedVehicle, customers]);

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
      }
    }
  }, [initialOrderId, services]);

  const toggleAccessory = (acc: string) => {
    setFormData(prev => ({
      ...prev,
      accessories: prev.accessories.includes(acc) 
        ? prev.accessories.filter(a => a !== acc) 
        : [...prev.accessories, acc]
    }));
  };

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '', // Načtení z objektu
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      accessories: order.accessories || []
    });
    setIsModalOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;

    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');

    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalId = editingOrderId || generateNewId();

    const serviceData: ServiceRecord = {
      id: finalId,
      vehicleId: formData.vehicleId,
      date: formData.date,
      deliveryDate: formData.deliveryDate || undefined, // Uložení do objektu
      endDate: formData.endDate || undefined,
      description: formData.description,
      parts: formData.parts,
      laborHours: formData.laborHours,
      cost: calculatedCost,
      status: formData.status,
      technician: formData.technician,
      fuelLevel: formData.fuelLevel,
      accessories: formData.accessories,
      mileageAtEntry: formData.mileageAtEntry
    };

    if (editingOrderId) {
      onUpdateService(serviceData);
    } else {
      onAddService(serviceData);
    }

    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      accessories: []
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: `p${Date.now()}`, description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { 
        id: `p${Date.now()}`, 
        description: item.name, 
        quantity: 1, 
        unit: 'ks', 
        unitPrice: item.price 
      }]
    });
    setIsPriceListPickerOpen(false);
  };

  const removePart = (id: string) => {
    setFormData({
      ...formData,
      parts: formData.parts.filter(p => p.id !== id)
    });
  };

  const updatePart = (id: string, field: keyof PartItem, value: string | number) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const handlePrint = () => {
    window.print();
  };

  const confirmDeleteOrder = () => {
    if (deletingOrder) {
      onDeleteService(deletingOrder.id);
      setDeletingOrder(null);
    }
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);

    if (statusFilter === 'waiting' && order.status !== 'naplánováno') return false;
    if (statusFilter === 'active' && order.status !== 'probíhá') return false;
    if (statusFilter === 'done' && order.status !== 'hotovo') return false;

    if (!search) return true;
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence zakázkových listů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 print:hidden">
        <div className="flex-1 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat zakázku..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="bg-slate-200/50 p-1.5 rounded-2xl flex items-center gap-1 shrink-0">
          {(['all', 'waiting', 'active', 'done'] as StatusFilter[]).map((f) => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                statusFilter === f 
                  ? 'bg-white text-blue-600 shadow-sm scale-105' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              {f === 'all' ? 'Vše' : f === 'waiting' ? 'Čeká' : f === 'active' ? 'Aktivní' : 'Dokončené'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12 print:hidden">
        {filteredOrders.length > 0 ? (
          filteredOrders.map(order => {
            const vehicle = vehicles.find(v => v.id === order.vehicleId);
            const owner = customers.find(c => c.id === vehicle?.customerId);
            return (
              <div 
                key={order.id} 
                className={`bg-white rounded-[2rem] border shadow-sm p-8 hover:shadow-xl transition-all group flex flex-col lg:flex-row items-start lg:items-center gap-8 border-slate-100 ${
                  order.status === 'probíhá' ? 'border-l-4 border-l-amber-500' : 
                  order.status === 'hotovo' ? 'border-l-4 border-l-emerald-500' : 
                  'border-l-4 border-l-blue-500'
                }`}
              >
                <div className="flex items-center gap-6 min-w-[250px]">
                  <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${
                    order.status === 'hotovo' ? 'bg-emerald-500 shadow-emerald-200' : 
                    order.status === 'probíhá' ? 'bg-amber-500 shadow-amber-200' : 
                    'bg-blue-600 shadow-blue-200'
                  }`}>
                    {order.status === 'hotovo' ? <CheckCircle2 className="w-8 h-8" /> : <ClipboardList className="w-8 h-8" />}
                  </div>
                  <div>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-full ${
                      order.status === 'hotovo' ? 'text-emerald-600 bg-emerald-50' : 
                      order.status === 'probíhá' ? 'text-amber-600 bg-amber-50' : 
                      'text-blue-600 bg-blue-50'
                    }`}>
                      {order.status === 'naplánováno' ? 'Čeká' : order.status}
                    </span>
                    <h3 className="text-xl font-black text-slate-900 mt-1">{order.id}</h3>
                    <p className="text-xs font-bold text-slate-400 uppercase">{order.date}</p>
                  </div>
                </div>
                <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                   <div className="flex items-center gap-3">
                      <Car className="w-4 h-4 text-slate-400" />
                      <span className="text-sm font-bold text-slate-700">{vehicle?.make} {vehicle?.model}</span>
                      <span className="text-xs font-mono bg-slate-100 px-2 py-0.5 rounded text-slate-500">{vehicle?.licensePlate}</span>
                   </div>
                   <div className="flex items-center gap-3">
                      <User className="w-4 h-4 text-slate-400" />
                      <span className="text-sm font-bold text-slate-700">{owner?.lastName} {owner?.firstName}</span>
                   </div>
                </div>
                <div className="text-right flex flex-col items-end gap-2">
                  <p className="text-xl font-black text-slate-900">{order.cost.toLocaleString()} Kč</p>
                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => setDeletingOrder(order)}
                      className="p-2 text-slate-300 hover:text-red-500 transition-colors rounded-xl hover:bg-red-50"
                      title="Smazat zakázku"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                    <button 
                      onClick={() => handleEdit(order)}
                      className="text-blue-600 text-xs font-black uppercase tracking-widest hover:underline flex items-center gap-1"
                    >
                      Detail & Editace <ArrowRight className="w-3 h-3"/>
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        ) : (
          <div className="bg-white/50 border-4 border-dashed border-slate-200 rounded-[2.5rem] py-20 flex flex-col items-center justify-center text-center">
            <ClipboardList className="w-16 h-16 text-slate-200 mb-4" />
            <h3 className="text-xl font-bold text-slate-400">Žádné zakázky k zobrazení</h3>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:p-0 print:static print:block print:bg-white">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300 print:hidden" onClick={() => setIsModalOpen(false)}></div>

          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh] print:shadow-none print:rounded-none print:max-w-none print:max-h-none print:overflow-visible print:static print:z-0 print:hidden">

            <div className={`p-8 text-white flex justify-between items-center shrink-0 ${editingOrderId ? 'bg-slate-900' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-md">
                   <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-3xl font-black tracking-tight uppercase">
                    {editingOrderId ? `ZAKÁZKA ${editingOrderId}` : 'NOVÝ ZAKÁZKOVÝ LIST'}
                  </h3>
                  <p className="text-blue-100 text-[10px] font-black uppercase tracking-[0.2em] mt-1">
                    {editingOrderId ? 'Editace stávající objednávky' : 'Nová objednávka zakázky'} &bull; {companyInfo.name}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                  <X className="w-8 h-8" />
                </button>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar flex-1 bg-slate-50/50">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-1 bg-slate-200 border border-slate-200 rounded-3xl overflow-hidden">
                <div className="bg-white p-6 space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">ZÁKAZNÍK A VOZIDLO</label>
                  <select 
                    required
                    disabled={!!editingOrderId}
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 outline-none transition-all font-bold appearance-none disabled:opacity-70"
                    value={formData.vehicleId}
                    onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                  >
                    <option value="">Vyberte vozidlo...</option>
                    {vehicles.map(v => (
                      <option key={v.id} value={v.id}>{v.licensePlate} - {v.make} {v.model}</option>
                    ))}
                  </select>
                </div>

                <div className="bg-white p-6 grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">TACHOMETR</label>
                    <input 
                      type="number" 
                      className="bg-slate-50 border-none rounded-xl p-2 font-bold text-sm w-full mt-1"
                      value={formData.mileageAtEntry}
                      onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})}
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">STAV</label>
                    <select 
                      className="bg-slate-50 border-none rounded-xl p-2 font-bold text-sm w-full mt-1"
                      value={formData.status}
                      onChange={e => setFormData({...formData, status: e.target.value as any})}
                    >
                      <option value="naplánováno">Naplánováno</option>
                      <option value="probíhá">Probíhá</option>
                      <option value="hotovo">Hotovo</option>
                    </select>
                  </div>
                </div>

                <div className="bg-white p-6 space-y-4">
                   <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">DATUM PŘÍJMU</label>
                        <input type="date" className="text-sm font-bold text-slate-900 bg-slate-50 rounded-lg p-2 w-full mt-1" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block text-emerald-600">DATUM PŘEDÁNÍ</label>
                        <input type="date" className="text-sm font-bold text-slate-900 bg-emerald-50/50 rounded-lg p-2 w-full mt-1 border border-emerald-100" value={formData.deliveryDate} onChange={e => setFormData({...formData, deliveryDate: e.target.value})} />
                      </div>
                   </div>
                </div>
              </div>

              <div className="bg-white p-8 rounded-[2rem] border border-slate-100">
                <div className="flex items-center justify-between border-b border-slate-100 pb-4 mb-6">
                  <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2">
                    <Package className="w-4 h-4 text-blue-600" /> ROZSAH A MATERIÁL
                  </h4>
                  <div className="flex gap-4">
                    <div className="relative">
                      <button 
                        type="button" 
                        onClick={() => setIsPriceListPickerOpen(!isPriceListPickerOpen)}
                        className="bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-100 transition-all flex items-center gap-2"
                      >
                        <Tag className="w-4 h-4" /> Přidat z ceníku
                      </button>

                      {isPriceListPickerOpen && (
                        <div className="absolute right-0 top-12 w-64 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[70] animate-in fade-in slide-in-from-top-2">
                          <div className="p-2 border-b border-slate-50 mb-2">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dostupné úkony</p>
                          </div>
                          <div className="max-h-60 overflow-y-auto custom-scrollbar">
                            {fixedServices.map(item => (
                              <button
                                key={item.id}
                                type="button"
                                onClick={() => addFromPriceList(item)}
                                className="w-full text-left p-3 rounded-xl hover:bg-slate-50 flex justify-between items-center group"
                              >
                                <span className="text-xs font-bold text-slate-700">{item.name}</span>
                                <span className="text-[10px] font-black text-blue-600 opacity-0 group-hover:opacity-100 transition-all">{item.price} Kč</span>
                              </button>
                            ))}
                            {fixedServices.length === 0 && (
                              <p className="p-4 text-[10px] font-bold text-slate-400 italic text-center">Ceník je prázdný</p>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                    <button 
                      type="button" 
                      onClick={addPart}
                      className="bg-blue-50 text-blue-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-100 transition-all flex items-center gap-2"
                    >
                      <Plus className="w-4 h-4" /> Vlastní položka
                    </button>
                  </div>
                </div>

                <textarea 
                  required
                  className="w-full min-h-[100px] text-sm font-medium text-slate-600 outline-none resize-none p-4 bg-slate-50 rounded-2xl mb-6"
                  placeholder="Popis závady a provedených prací..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />

                <div className="overflow-x-auto">
                  <table className="w-full text-left text-[11px] font-bold">
                    <thead>
                      <tr className="border-b border-slate-100 text-slate-400 uppercase">
                        <th className="py-2 pr-4">Položka</th>
                        <th className="py-2 pr-4 w-20">Množství</th>
                        <th className="py-2 pr-4 w-24">Cena/jedn.</th>
                        <th className="py-2 pr-4 w-24 text-right">Celkem</th>
                        <th className="py-2 w-8"></th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {formData.parts.map((part) => (
                        <tr key={part.id}>
                          <td className="py-2 pr-4">
                            <input 
                              type="text" 
                              className="w-full bg-slate-50 rounded-lg px-2 py-1.5 outline-none font-bold"
                              value={part.description}
                              onChange={(e) => updatePart(part.id, 'description', e.target.value)}
                            />
                          </td>
                          <td className="py-2 pr-4">
                            <input 
                              type="number" 
                              className="w-full bg-slate-50 rounded-lg px-2 py-1.5 outline-none font-bold"
                              value={part.quantity}
                              onChange={(e) => updatePart(part.id, 'quantity', parseFloat(e.target.value) || 0)}
                            />
                          </td>
                          <td className="py-2 pr-4">
                            <input 
                              type="number" 
                              className="w-full bg-slate-50 rounded-lg px-2 py-1.5 outline-none font-bold"
                              value={part.unitPrice}
                              onChange={(e) => updatePart(part.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                            />
                          </td>
                          <td className="py-2 pr-4 text-right text-slate-900 font-black">
                            {(part.quantity * part.unitPrice).toLocaleString()} Kč
                          </td>
                          <td className="py-2 text-right">
                            <button type="button" onClick={() => removePart(part.id)} className="text-slate-300 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hodinová práce</label>
                    <input 
                      type="number" step="0.5" 
                      className="w-full text-2xl font-black text-blue-600 bg-slate-50 rounded-2xl p-4 outline-none"
                      value={formData.laborHours}
                      onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})}
                    />
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest text-right">Sazba: {hourlyRate} Kč / hod</p>
                 </div>
                 <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-2xl flex flex-col justify-center">
                    <p className="text-[10px] font-black uppercase text-blue-400 tracking-widest mb-1">Celkem k úhradě</p>
                    <p className="text-4xl font-black">{calculatedCost.toLocaleString()} Kč</p>
                 </div>
              </div>

              <div className="flex justify-end gap-4 pt-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 py-4 rounded-2xl font-black text-sm bg-slate-100 hover:bg-slate-200 text-slate-900">ZRUŠIT</button>
                <button type="submit" className="px-12 py-4 rounded-2xl font-black text-sm bg-blue-600 hover:bg-blue-700 text-white shadow-xl shadow-blue-600/20">{editingOrderId ? 'AKTUALIZOVAT' : 'VYSTAVIT'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f8fafc;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
      `}</style>
    </div>
  );
};

const CheckCircle2 = (props: any) => (
  <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"/><path d="m9 12 2 2 4-4"/></svg>
);

export default OrderManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, Clock, User, Car, ArrowRight, X, Check, 
  Search, Package, Calculator, DollarSign, Gauge, Fuel, ShieldCheck,
  RotateCcw, Trash2, Printer, Wrench, Info, AlertCircle, Building,
  Tag, ListPlus, FileText
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  selectedPrinter = 'Systémová tiskárna'
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [printOrder, setPrintOrder] = useState<ServiceRecord | null>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2',
    mileageAtEntry: 0,
    accessories: [] as string[]
  });

  const selectedVehicle = useMemo(() => 
    vehicles.find(v => v.id === formData.vehicleId),
  [formData.vehicleId, vehicles]);

  const selectedCustomer = useMemo(() => 
    selectedVehicle ? customers.find(c => c.id === selectedVehicle.customerId) : null,
  [selectedVehicle, customers]);

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
      }
    }
  }, [initialOrderId, services]);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      accessories: order.accessories || []
    });
    setIsModalOpen(true);
  };

  const handlePrintAction = (order: ServiceRecord) => {
    setPrintOrder(order);
    setTimeout(() => {
      window.print();
    }, 100);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      id: finalId,
      vehicleId: formData.vehicleId,
      date: formData.date,
      deliveryDate: formData.deliveryDate || undefined,
      endDate: formData.endDate || undefined,
      description: formData.description,
      parts: formData.parts,
      laborHours: formData.laborHours,
      cost: calculatedCost,
      status: formData.status,
      technician: formData.technician,
      fuelLevel: formData.fuelLevel,
      accessories: formData.accessories,
      mileageAtEntry: formData.mileageAtEntry
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      accessories: []
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: `p${Date.now()}`, description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { 
        id: `p${Date.now()}`, 
        description: item.name, 
        quantity: 1, 
        unit: 'ks', 
        unitPrice: item.price 
      }]
    });
    setIsPriceListPickerOpen(false);
  };

  const removePart = (id: string) => {
    setFormData({
      ...formData,
      parts: formData.parts.filter(p => p.id !== id)
    });
  };

  const updatePart = (id: string, field: keyof PartItem, value: string | number) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
