  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onRestoreData: (customers: Customer[], vehicles: Vehicle[], services: ServiceRecord[]) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: any) => void;
  directoryHandle: any;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  selectedPrinter, onPrinterChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'printers' | 'backups'>('company');
  const [isScanning, setIsScanning] = useState(false);
  const [foundPrinters, setFoundPrinters] = useState<string[]>([]);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScanPrinters = () => {
    setIsScanning(true);
    setFoundPrinters([]);
    setTimeout(() => {
      setFoundPrinters([
        'HP LaserJet Pro M404dn (Kancelář)',
        'Brother HL-L2350DW (Dílna)',
        'Epson Stylus Photo P50',
        'Zebra ZD421 (Štítkovač)',
        'Microsoft Print to PDF'
      ]);
      setIsScanning(false);
    }, 1500);
  };

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const confirmRemoveFixedService = () => {
    if (deletingFixedService) {
      onFixedServicesChange(fixedServices.filter(fs => fs.id !== deletingFixedService.id));
      setDeletingFixedService(null);
    }
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}">\n`;
    xml += `  <Customers>${customers.map(c => `\n    <Customer id="${c.id}"><FirstName>${c.firstName}</FirstName><LastName>${c.lastName}</LastName></Customer>`).join('')}\n  </Customers>\n`;
    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handlePickAutoBackupFolder = async () => {
    if (!('showDirectoryPicker' in window)) {
      alert('Váš prohlížeč nepodporuje přímý přístup k souborovému systému.');
      return;
    }
    try {
      const dirHandle = await (window as any).showDirectoryPicker();
      setDirectoryHandle(dirHandle);
      onAutoBackupSettingsChange({...autoBackupSettings, folderName: dirHandle.name});
    } catch (err: any) {
      console.error('Directory Picker Error:', err);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'printers', label: 'Tiskárna', icon: Printer },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se tisknou na zakázkové listy</p>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Fakturační adresa</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                <input type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Oficiální Email</label>
                <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'services' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center"><DollarSign className="w-8 h-8 text-emerald-600" /></div>
                 <div><h3 className="text-2xl font-black text-slate-900">Standardní sazba</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Základní hodinová cena práce</p></div>
              </div>
              <div className="max-w-xs">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Hodinová sazba (Kč)</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-2xl font-black text-lg mt-2 outline-none" value={hourlyRate} onChange={e => onRateChange(parseInt(e.target.value) || 0)} />
              </div>
            </div>

            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                   {/* Fix: Added Tag to imports above and using it here */}
                   <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Tag className="w-8 h-8 text-blue-600" /></div>
                   <div><h3 className="text-2xl font-black text-slate-900">Položkový ceník</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Služby s fixní cenou</p></div>
                </div>
                <button 
                  onClick={addFixedService}
                  className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold text-xs flex items-center gap-2"
                >
                  <Plus className="w-4 h-4" /> PŘIDAT ÚKON
                </button>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {fixedServices.map(fs => (
                  <div key={fs.id} className="flex flex-col sm:flex-row gap-4 p-4 bg-slate-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                    <div className="flex-1 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Název úkonu</label>
                      <input 
                        type="text"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-bold"
                        placeholder="Např. Výměna brzdové kapaliny..."
                        value={fs.name}
                        onChange={e => updateFixedService(fs.id, 'name', e.target.value)}
                      />
                    </div>
                    <div className="w-full sm:w-40 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Cena (Kč)</label>
                      <input 
                        type="number"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-black text-blue-600"
                        value={fs.price}
                        onChange={e => updateFixedService(fs.id, 'price', parseInt(e.target.value) || 0)}
                      />
                    </div>
                    <div className="flex items-end pb-1">
                      <button 
                        onClick={() => setDeletingFixedService(fs)}
                        className="p-3 text-slate-300 hover:text-red-500 transition-colors"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'printers' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Printer className="w-8 h-8 text-blue-600" /></div>
                <div><h3 className="text-2xl font-black text-slate-900">Správa tiskáren</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Výběr tiskového zařízení</p></div>
              </div>
              <button onClick={handleScanPrinters} disabled={isScanning} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-xs">
                {isScanning ? 'HLEDÁM...' : 'HLEDAT TISKÁRNY'}
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(foundPrinters.length > 0 ? foundPrinters : [selectedPrinter]).map(p => (
                <button key={p} onClick={() => onPrinterChange(p)} className={`p-5 rounded-2xl border-2 text-left flex justify-between items-center ${selectedPrinter === p ? 'bg-blue-50 border-blue-500' : 'bg-slate-50 border-transparent'}`}>
                  <span className="font-bold text-sm">{p}</span>
                  {selectedPrinter === p && <CheckCircle2 className="w-5 h-5 text-blue-600" />}
                </button>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'notifications' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-amber-50 rounded-2xl flex items-center justify-center"><Bell className="w-8 h-8 text-amber-600" /></div>
               <div><h3 className="text-2xl font-black text-slate-900">Upozornění</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Limity pro hlášení (dny)</p></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">STK expirace</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.stkThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, stkThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Servisní prohlídka</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.serviceThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, serviceThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center"><Database className="w-8 h-8 text-slate-900" /></div>
              <div><h3 className="text-2xl font-black text-slate-900">Zálohování a obnova</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Správa databáze</p></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Ruční export</h4>
                <button onClick={handleDownloadBackup} disabled={backupStatus === 'processing'} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3">
                  {backupStatus === 'processing' ? <Loader2 className="animate-spin" /> : <DownloadCloud className="w-5 h-5" />} STÁHNOUT ZÁLOHU
                </button>
              </div>
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Obnovit data</h4>
                <input type="file" accept=".xml" className="hidden" ref={fileInputRef} onChange={e => e.target.files?.[0] && alert('Funkce obnovy vyžaduje plnou verzi systému.')} />
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3">
                  <UploadCloud className="w-5 h-5" /> OBNOVIT ZE SOUBORU
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {deletingFixedService && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingFixedService(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat položku?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat službu <span className="font-bold text-slate-900">{deletingFixedService.name}</span> z ceníku?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingFixedService(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={confirmRemoveFixedService} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Settings;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Printer, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, FolderPlus, Clock, CheckCircle2, Lock, User as UserIcon, AlertCircle, Check,
  Tag
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PartItem } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onRestoreData: (customers: Customer[], vehicles: Vehicle[], services: ServiceRecord[]) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: any) => void;
  directoryHandle: any;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  selectedPrinter, onPrinterChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'printers' | 'backups'>('company');
  const [isScanning, setIsScanning] = useState(false);
  const [foundPrinters, setFoundPrinters] = useState<string[]>([]);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScanPrinters = () => {
    setIsScanning(true);
    setFoundPrinters([]);
    setTimeout(() => {
      setFoundPrinters([
        'HP LaserJet Pro M404dn (Kancelář)',
        'Brother HL-L2350DW (Dílna)',
        'Epson Stylus Photo P50',
        'Zebra ZD421 (Štítkovač)',
        'Microsoft Print to PDF'
      ]);
      setIsScanning(false);
    }, 1500);
  };

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const confirmRemoveFixedService = () => {
    if (deletingFixedService) {
      onFixedServicesChange(fixedServices.filter(fs => fs.id !== deletingFixedService.id));
      setDeletingFixedService(null);
    }
  };

  // Helper to generate XML nodes safely
  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="1.0">\n`;

    // Customers
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // Vehicles
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('LastServiceDate', v.lastServiceDate);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // Services
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('EndDate', s.endDate);
      xml += xmlTag('DeliveryDate', s.deliveryDate);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('Unit', p.unit);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        // Parse Customers
        const customerNodes = xmlDoc.querySelectorAll("Customer");
        const importedCustomers: Customer[] = Array.from(customerNodes).map(node => ({
          id: node.getAttribute("id") || `c${Math.random()}`,
          firstName: node.querySelector("FirstName")?.textContent || "",
          lastName: node.querySelector("LastName")?.textContent || "",
          email: node.querySelector("Email")?.textContent || "",
          phone: node.querySelector("Phone")?.textContent || "",
          address: node.querySelector("Address")?.textContent || "",
          createdAt: node.querySelector("CreatedAt")?.textContent || new Date().toISOString().split('T')[0],
          companyName: node.querySelector("CompanyName")?.textContent || undefined,
          companyAddress: node.querySelector("CompanyAddress")?.textContent || undefined,
          ico: node.querySelector("ICO")?.textContent || undefined,
          dic: node.querySelector("DIC")?.textContent || undefined,
        }));

        // Parse Vehicles
        const vehicleNodes = xmlDoc.querySelectorAll("Vehicle");
        const importedVehicles: Vehicle[] = Array.from(vehicleNodes).map(node => ({
          id: node.getAttribute("id") || `v${Math.random()}`,
          customerId: node.getAttribute("customerId") || "",
          make: node.querySelector("Make")?.textContent || "",
          model: node.querySelector("Model")?.textContent || "",
          year: parseInt(node.querySelector("Year")?.textContent || "0"),
          vin: node.querySelector("VIN")?.textContent || "",
          licensePlate: node.querySelector("LicensePlate")?.textContent || "",
          mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
          engineCode: node.querySelector("EngineCode")?.textContent || "",
          color: node.querySelector("Color")?.textContent || "",
          lastServiceDate: node.querySelector("LastServiceDate")?.textContent || "",
          stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent || "",
          nextServiceDate: node.querySelector("NextServiceDate")?.textContent || "",
        }));

        // Parse Services
        const serviceNodes = xmlDoc.querySelectorAll("ServiceRecord");
        const importedServices: ServiceRecord[] = Array.from(serviceNodes).map(node => {
          const partNodes = node.querySelectorAll("Part");
          const parts: PartItem[] = Array.from(partNodes).map(pNode => ({
            id: pNode.getAttribute("id") || `p${Math.random()}`,
            description: pNode.querySelector("Description")?.textContent || "",
            quantity: parseFloat(pNode.querySelector("Quantity")?.textContent || "0"),
            unit: pNode.querySelector("Unit")?.textContent || "ks",
            unitPrice: parseFloat(pNode.querySelector("UnitPrice")?.textContent || "0"),
          }));

          return {
            id: node.getAttribute("id") || `s${Math.random()}`,
            vehicleId: node.getAttribute("vehicleId") || "",
            date: node.querySelector("Date")?.textContent || "",
            endDate: node.querySelector("EndDate")?.textContent || undefined,
            deliveryDate: node.querySelector("DeliveryDate")?.textContent || undefined,
            description: node.querySelector("Description")?.textContent || "",
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: (node.querySelector("Status")?.textContent || "hotovo") as any,
            technician: node.querySelector("Technician")?.textContent || "",
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: parts.length > 0 ? parts : undefined,
          };
        });

        if (importedCustomers.length > 0 || importedVehicles.length > 0) {
          onRestoreData(importedCustomers, importedVehicles, importedServices);
          setBackupStatus('success');
          setTimeout(() => setBackupStatus('idle'), 4000);
        } else {
          throw new Error("Invalid backup structure");
        }
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
        setTimeout(() => setBackupStatus('idle'), 5000);
      }
    };

    reader.onerror = () => {
      setBackupStatus('error');
      setTimeout(() => setBackupStatus('idle'), 5000);
    };

    reader.readAsText(file);
    // Clear input so same file can be selected again
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'printers', label: 'Tiskárna', icon: Printer },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se tisknou na zakázkové listy</p>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Fakturační adresa</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                <input type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Oficiální Email</label>
                <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'services' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center"><DollarSign className="w-8 h-8 text-emerald-600" /></div>
                 <div><h3 className="text-2xl font-black text-slate-900">Standardní sazba</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Základní hodinová cena práce</p></div>
              </div>
              <div className="max-w-xs">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Hodinová sazba (Kč)</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-2xl font-black text-lg mt-2 outline-none" value={hourlyRate} onChange={e => onRateChange(parseInt(e.target.value) || 0)} />
              </div>
            </div>

            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Tag className="w-8 h-8 text-blue-600" /></div>
                   <div><h3 className="text-2xl font-black text-slate-900">Položkový ceník</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Služby s fixní cenou</p></div>
                </div>
                <button 
                  onClick={addFixedService}
                  className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold text-xs flex items-center gap-2"
                >
                  <Plus className="w-4 h-4" /> PŘIDAT ÚKON
                </button>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {fixedServices.map(fs => (
                  <div key={fs.id} className="flex flex-col sm:flex-row gap-4 p-4 bg-slate-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                    <div className="flex-1 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Název úkonu</label>
                      <input 
                        type="text"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-bold"
                        placeholder="Např. Výměna brzdové kapaliny..."
                        value={fs.name}
                        onChange={e => updateFixedService(fs.id, 'name', e.target.value)}
                      />
                    </div>
                    <div className="w-full sm:w-40 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Cena (Kč)</label>
                      <input 
                        type="number"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-black text-blue-600"
                        value={fs.price}
                        onChange={e => updateFixedService(fs.id, 'price', parseInt(e.target.value) || 0)}
                      />
                    </div>
                    <div className="flex items-end pb-1">
                      <button 
                        onClick={() => setDeletingFixedService(fs)}
                        className="p-3 text-slate-300 hover:text-red-500 transition-colors"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'printers' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Printer className="w-8 h-8 text-blue-600" /></div>
                <div><h3 className="text-2xl font-black text-slate-900">Správa tiskáren</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Výběr tiskového zařízení</p></div>
              </div>
              <button onClick={handleScanPrinters} disabled={isScanning} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold text-xs">
                {isScanning ? 'HLEDÁM...' : 'HLEDAT TISKÁRNY'}
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(foundPrinters.length > 0 ? foundPrinters : [selectedPrinter]).map(p => (
                <button key={p} onClick={() => onPrinterChange(p)} className={`p-5 rounded-2xl border-2 text-left flex justify-between items-center ${selectedPrinter === p ? 'bg-blue-50 border-blue-500' : 'bg-slate-50 border-transparent'}`}>
                  <span className="font-bold text-sm">{p}</span>
                  {selectedPrinter === p && <CheckCircle2 className="w-5 h-5 text-blue-600" />}
                </button>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'notifications' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-amber-50 rounded-2xl flex items-center justify-center"><Bell className="w-8 h-8 text-amber-600" /></div>
               <div><h3 className="text-2xl font-black text-slate-900">Upozornění</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Limity pro hlášení (dny)</p></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">STK expirace</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.stkThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, stkThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Servisní prohlídka</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.serviceThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, serviceThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center"><Database className="w-8 h-8 text-slate-900" /></div>
              <div><h3 className="text-2xl font-black text-slate-900">Zálohování a obnova</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Správa databáze</p></div>
            </div>

            {backupStatus !== 'idle' && (
              <div className={`p-4 rounded-2xl flex items-center gap-3 animate-in fade-in zoom-in-95 ${
                backupStatus === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
                backupStatus === 'error' ? 'bg-red-50 text-red-700 border border-red-100' :
                'bg-blue-50 text-blue-700 border border-blue-100'
              }`}>
                {backupStatus === 'processing' ? <Loader2 className="w-5 h-5 animate-spin" /> : <AlertCircle className="w-5 h-5" />}
                <p className="text-sm font-bold">
                  {backupStatus === 'processing' ? 'Probíhá zpracování...' :
                   backupStatus === 'success' ? 'Data byla úspěšně zpracována a obnovena.' :
                   'Při zpracování souboru došlo k chybě. Zkontrolujte formát XML.'}
                </p>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Ruční export</h4>
                <p className="text-xs text-slate-500 font-medium">Stáhne kompletní XML soubor se všemi zákazníky, vozidly a historií.</p>
                <button onClick={handleDownloadBackup} disabled={backupStatus === 'processing'} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-50 transition-all">
                  {backupStatus === 'processing' && activeTab === 'backups' ? <Loader2 className="animate-spin" /> : <DownloadCloud className="w-5 h-5" />} STÁHNOUT ZÁLOHU
                </button>
              </div>
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Obnovit data</h4>
                <p className="text-xs text-slate-500 font-medium">Nahrajte XML soubor vytvořený exportem pro kompletní přepsání databáze.</p>
                <input type="file" accept=".xml" className="hidden" ref={fileInputRef} onChange={handleFileImport} />
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-800 transition-all shadow-lg shadow-slate-900/20">
                  <UploadCloud className="w-5 h-5" /> OBNOVIT ZE SOUBORU
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {deletingFixedService && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingFixedService(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat položku?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat službu <span className="font-bold text-slate-900">{deletingFixedService.name}</span> z ceníku?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingFixedService(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={confirmRemoveFixedService} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Settings;

export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
}

export interface FixedService {
  id: string;
  name: string;
  price: number;
}

export interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string;
  nextServiceDate: string;
}

export interface VehicleChecklist {
  rezerva: boolean;
  zvedak: boolean;
  klic: boolean;
  naradi: boolean;
  hustilka: boolean;
  trojuhelnik: boolean;
  lekarna: boolean;
  radio: boolean;
  reflektory: boolean;
  nosic: boolean;
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  deliveryDate?: string;
  description: string;
  parts?: PartItem[];
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  fuelLevel?: '1/4' | '1/2' | '3/4' | 'Full' | 'Rezerva';
  checklist?: VehicleChecklist;
  mileageAtEntry?: number;
  estimatedPrice?: number;
  paymentType?: 'Hotovost' | 'Faktura' | 'Pojišťovna';
}

export interface CompanyInfo {
  name: string;
  address: string;
  ico: string;
  dic: string;
  phone: string;
  email: string;
}

export interface NotificationSettings {
  stkThresholdDays: number;
  serviceThresholdDays: number;
}

export interface AutoBackupSettings {
  enabled: boolean;
  hour: number;
  lastBackupDate: string | null;
  folderName: string | null;
}

export interface UserSettings {
  enabled: boolean;
  username: string;
  password: string;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'orders' | 'settings';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  autoOpen, 
  onModalOpened, 
  initialOrderId
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'waiting' | 'active' | 'done'>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [previewOrder, setPreviewOrder] = useState<ServiceRecord | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) handleEdit(order);
    }
  }, [initialOrderId, services]);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
  };

  const handleOpenPreview = (order: ServiceRecord) => {
    setPreviewOrder(order);
    setIsPreviewOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);
    if (statusFilter === 'waiting' && order.status !== 'naplánováno') return false;
    if (statusFilter === 'active' && order.status !== 'probíhá') return false;
    if (statusFilter === 'done' && order.status !== 'hotovo') return false;
    if (!search) return true;
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      {/* Real Print Template (Hidden from UI, visible to Browser Print) */}
      <div className="hidden print:block">
        {previewOrder && (
          <PrintTemplate 
            order={previewOrder} 
            company={companyInfo} 
            vehicles={vehicles} 
            customers={customers} 
            hourlyRate={hourlyRate} 
          />
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence zakázkových listů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 print:hidden">
        <div className="flex-1 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat zakázku (ID, SPZ, Jméno)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="bg-slate-200/50 p-1.5 rounded-2xl flex items-center gap-1 shrink-0">
          {(['all', 'waiting', 'active', 'done'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'
              }`}
            >
              {f === 'all' ? 'Vše' : f === 'waiting' ? 'Čeká' : f === 'active' ? 'Aktivní' : 'Hotovo'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12 print:hidden">
        {filteredOrders.map(order => {
          const vehicle = vehicles.find(v => v.id === order.vehicleId);
          const owner = customers.find(c => c.id === vehicle?.customerId);
          return (
            <div key={order.id} className="bg-white rounded-[2rem] border border-slate-100 p-8 hover:shadow-xl transition-all flex flex-col lg:flex-row items-center gap-8 group">
              <div className="flex items-center gap-6 min-w-[250px]">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${
                  order.status === 'hotovo' ? 'bg-emerald-500' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'
                }`}>
                  <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">{order.id}</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{order.date}</p>
                </div>
              </div>
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Vozidlo</p>
                    <p className="text-sm font-bold">{vehicle?.make} {vehicle?.model} <span className="text-blue-600 ml-1">({vehicle?.licensePlate})</span></p>
                 </div>
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Zákazník</p>
                    <p className="text-sm font-bold">{owner?.lastName} {owner?.firstName}</p>
                 </div>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => handleOpenPreview(order)}
                  className="p-4 text-slate-400 hover:text-blue-600 bg-slate-50 rounded-2xl hover:bg-blue-50 transition-all"
                  title="Náhled a tisk"
                >
                  <Eye className="w-6 h-6" />
                </button>
                <button 
                  onClick={() => setDeletingOrder(order)}
                  className="p-4 text-slate-300 hover:text-red-500 rounded-2xl hover:bg-red-50 transition-all"
                >
                  <Trash2 className="w-6 h-6" />
                </button>
                <button 
                  onClick={() => handleEdit(order)}
                  className="bg-slate-900 text-white px-6 py-4 rounded-2xl font-black text-xs hover:bg-blue-600 transition-all"
                >
                  DETAIL
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Tiskový Náhled (Modal) */}
      {isPreviewOpen && previewOrder && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsPreviewOpen(false)}></div>
          <div className="bg-white w-full max-w-5xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col">
            <div className="p-6 border-b flex justify-between items-center shrink-0">
              <h3 className="text-xl font-black tracking-tight">Náhled zakázkového listu</h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => window.print()}
                  className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg shadow-blue-200"
                >
                  <Printer className="w-5 h-5" /> TISKNOUT
                </button>
                <button onClick={() => setIsPreviewOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl">
                  <X className="w-6 h-6 text-slate-400" />
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-xl transform scale-90 origin-top">
                 <PrintTemplate 
                    order={previewOrder} 
                    company={companyInfo} 
                    vehicles={vehicles} 
                    customers={customers} 
                    hourlyRate={hourlyRate} 
                 />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Editor Zakázky (Modal) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <form onSubmit={handleSubmit} className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh]">
            <div className={`p-8 text-white flex justify-between items-center shrink-0 ${editingOrderId ? 'bg-slate-900' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                <ClipboardList className="w-10 h-10" />
                <div>
                  <h3 className="text-3xl font-black uppercase tracking-tight">{editingOrderId ? `UPRAVIT ZAKÁZKU ${editingOrderId}` : 'NOVÁ ZAKÁZKA'}</h3>
                </div>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)}><X className="w-8 h-8" /></button>
            </div>

            <div className="p-10 space-y-10 overflow-y-auto flex-1 custom-scrollbar bg-slate-50/30">

              {/* Sekce: Základní údaje */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">VOZIDLO</label>
                  <select 
                    required
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.vehicleId}
                    onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                  >
                    <option value="">Vyberte vozidlo...</option>
                    {vehicles.map(v => (
                      <option key={v.id} value={v.id}>{v.licensePlate} - {v.make} {v.model}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PLATBA</label>
                  <select 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.paymentType}
                    onChange={e => setFormData({...formData, paymentType: e.target.value as any})}
                  >
                    <option value="Hotovost">Hotovost</option>
                    <option value="Faktura">Faktura</option>
                    <option value="Pojišťovna">Pojišťovna</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PŘEDBĚŽNÁ CENA (KČ)</label>
                  <input 
                    type="number"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.estimatedPrice}
                    onChange={e => setFormData({...formData, estimatedPrice: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>

              {/* Sekce: Checklist výbavy */}
              <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <Car className="w-5 h-5 text-blue-600" /> STAV VOZIDLA PŘI PŘÍJMU
                </h4>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-6">
                  {Object.keys(formData.checklist).map((key) => (
                    <label key={key} className="flex items-center gap-3 cursor-pointer group">
                      <input 
                        type="checkbox"
                        className="hidden"
                        checked={formData.checklist[key as keyof VehicleChecklist]}
                        onChange={() => setFormData({
                          ...formData, 
                          checklist: { ...formData.checklist, [key]: !formData.checklist[key as keyof VehicleChecklist] }
                        })}
                      />
                      <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                        formData.checklist[key as keyof VehicleChecklist] ? 'bg-blue-600 border-blue-600' : 'border-slate-200 group-hover:border-blue-400'
                      }`}>
                        {formData.checklist[key as keyof VehicleChecklist] && <Check className="w-4 h-4 text-white" />}
                      </div>
                      <span className="text-xs font-bold text-slate-600 capitalize">{key}</span>
                    </label>
                  ))}
                </div>

                <div className="mt-10 grid grid-cols-1 sm:grid-cols-2 gap-8 pt-8 border-t border-slate-50">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">STAV PALIVA (PHM)</label>
                    <div className="flex gap-2">
                      {['Rezerva', '1/4', '1/2', '3/4', 'Full'].map(level => (
                        <button
                          key={level}
                          type="button"
                          onClick={() => setFormData({...formData, fuelLevel: level as any})}
                          className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${
                            formData.fuelLevel === level ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                          }`}
                        >
                          {level}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">STAV TACHOMETRU (PŘI PŘÍJMU)</label>
                    <input 
                      type="number"
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                      value={formData.mileageAtEntry}
                      onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
              </div>

              {/* Sekce: Rozsah opravy */}
              <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6">POPIS ZÁVADY / ROZSAH OPRAVY</h4>
                <textarea 
                  required
                  rows={4}
                  className="w-full bg-slate-50 rounded-[1.5rem] p-6 outline-none font-medium text-slate-700 focus:ring-2 focus:ring-blue-500 transition-all"
                  placeholder="Popište podrobně co je potřeba na vozidle opravit..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>

            </div>

            <div className="p-8 border-t bg-white flex justify-end gap-4 shrink-0">
               <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 py-4 rounded-2xl font-black text-sm bg-slate-100 text-slate-500 hover:bg-slate-200 transition-all">ZRUŠIT</button>
               <button type="submit" className="px-12 py-4 rounded-2xl font-black text-sm bg-blue-600 text-white shadow-xl shadow-blue-600/20 hover:bg-blue-700 transition-all uppercase">ULOŽIT ZAKÁZKU</button>
            </div>
          </form>
        </div>
      )}

      <style>{`
        @media print {
          body { visibility: hidden !important; background: white !important; }
          #root { display: none !important; }
          .print-block { visibility: visible !important; position: absolute; left: 0; top: 0; width: 100%; display: block !important; }
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>
    </div>
  );
};

// --- NOVÁ TISKOVÁ ŠABLONA PODLE VZORU ---
const PrintTemplate: React.FC<{ order: ServiceRecord, company: CompanyInfo, vehicles: Vehicle[], customers: Customer[], hourlyRate: number }> = ({ order, company, vehicles, customers, hourlyRate }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
  const customer = vehicle ? customers.find(c => c.id === vehicle.customerId) : null;

  return (
    <div className="print-block p-12 bg-white text-black font-sans w-[210mm] min-h-[297mm] mx-auto border-[1px] border-slate-200" style={{ fontSize: '12px', lineHeight: '1.4' }}>

      {/* Hlavní tabulková mřížka - Vrchní část */}
      <div className="grid grid-cols-12 border-2 border-black">

        {/* Adresa servisu */}
        <div className="col-span-4 border-r-2 border-b-2 border-black p-4">
          <p className="font-bold text-[10px] uppercase mb-1">Opravna - DIČ</p>
          <p className="font-black text-lg leading-tight mb-2 uppercase">{company.name}</p>
          <p className="font-bold">{company.address}</p>
          <p className="mt-2 text-[10px]">IČO: {company.ico}</p>
          <p className="text-[10px]">DIČ: {company.dic}</p>
          <p className="text-[10px] mt-2">Tel: {company.phone}</p>
        </div>

        {/* Zákazník */}
        <div className="col-span-4 border-r-2 border-b-2 border-black p-4 bg-slate-50">
          <p className="font-bold text-[10px] uppercase mb-1">Zákazník</p>
          <p className="font-black text-sm">{customer?.companyName || `${customer?.firstName} ${customer?.lastName}`}</p>
          <p className="font-bold text-xs mt-1">{customer?.address}</p>
          <div className="mt-4 text-[10px] space-y-1">
             <p>Telefon: {customer?.phone}</p>
             <p>Email: {customer?.email}</p>
             {customer?.ico && <p>IČO: {customer?.ico} / DIČ: {customer?.dic}</p>}
          </div>
        </div>

        {/* Název tiskopisu */}
        <div className="col-span-4 border-b-2 border-black p-4 flex flex-col justify-between">
          <h1 className="text-2xl font-black text-center uppercase tracking-tighter">ZAKÁZKOVÝ LIST</h1>
          <div className="flex justify-between items-end">
