const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>(INITIAL_CUSTOMERS);
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [services, setServices] = useState<ServiceRecord[]>(INITIAL_SERVICES);

  // Security State
  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  // Settings States
  const [hourlyRate, setHourlyRate] = useState(850);
  const [fixedServices, setFixedServices] = useState<FixedService[]>(() => {
    const saved = localStorage.getItem('fixedServices');
    return saved ? JSON.parse(saved) : INITIAL_FIXED_SERVICES;
  });

  const [selectedPrinter, setSelectedPrinter] = useState<string>('HP LaserJet Pro M404dn (Kancelář)');
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>({
    name: 'AutoService Pro Praha',
    address: 'Průmyslová 1024/12, 102 00 Praha 10',
    ico: '12345678',
    dic: 'CZ12345678',
    phone: '+420 222 333 444',
    email: 'servis@autoservice.pro'
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>({
    stkThresholdDays: 30,
    serviceThresholdDays: 15
  });
  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  const [directoryHandle, setDirectoryHandle] = useState<FileSystemDirectoryHandle | null>(null);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  // Sync settings with local storage
  useEffect(() => {
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) {
      setIsAuthenticated(true);
    }
  }, [userSettings]);

  useEffect(() => {
    localStorage.setItem('fixedServices', JSON.stringify(fixedServices));
  }, [fixedServices]);

  // XML Generation Logic
  const generateXmlData = useCallback(() => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<AutoServiceBackup version="1.0" timestamp="${timestamp}">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += `      <FirstName>${c.firstName}</FirstName>\n`;
      xml += `      <LastName>${c.lastName}</LastName>\n`;
      xml += `      <Email>${c.email}</Email>\n`;
      xml += `      <Phone>${c.phone}</Phone>\n`;
      xml += `      <Address>${c.address}</Address>\n`;
      xml += `      <CreatedAt>${c.createdAt}</CreatedAt>\n`;
      if (c.companyName) xml += `      <CompanyName>${c.companyName}</CompanyName>\n`;
      if (c.ico) xml += `      <ICO>${c.ico}</ICO>\n`;
      if (c.dic) xml += `      <DIC>${c.dic}</DIC>\n`;
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += `      <Make>${v.make}</Make>\n`;
      xml += `      <Model>${v.model}</Model>\n`;
      xml += `      <Year>${v.year}</Year>\n`;
      xml += `      <VIN>${v.vin}</VIN>\n`;
      xml += `      <LicensePlate>${v.licensePlate}</LicensePlate>\n`;
      xml += `      <Mileage>${v.mileage}</Mileage>\n`;
      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <DeliveryDate>${s.deliveryDate || ''}</DeliveryDate>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  }, [customers, vehicles, services]);

  // Auto-backup check
  useEffect(() => {
    if (!autoBackupSettings.enabled) return;
    const checkBackup = async () => {
      const now = new Date();
      if (now.getHours() === autoBackupSettings.hour && autoBackupSettings.lastBackupDate !== now.toISOString().split('T')[0]) {
        try {
          if (directoryHandle) {
            const xmlData = generateXmlData();
            const options = { mode: 'readwrite' };
            // Fix: Cast to any as queryPermission is not always included in FileSystemDirectoryHandle's standard TS type
            const permission = await (directoryHandle as any).queryPermission(options);
            if (permission === 'granted') {
              const fileHandle = await directoryHandle.getFileHandle(`autoservice_daily_backup.xml`, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(xmlData);
              await writable.close();
              const updated = { ...autoBackupSettings, lastBackupDate: now.toISOString().split('T')[0] };
              setAutoBackupSettings(updated);
              localStorage.setItem('autoBackupSettings', JSON.stringify(updated));
            }
          }
        } catch (err) { console.error("Auto-backup failed:", err); }
      }
    };
    const interval = setInterval(checkBackup, 60000);
    return () => clearInterval(interval);
  }, [autoBackupSettings, directoryHandle, generateXmlData]);

  // Function to sync vehicle mileage based on service record entry
  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices([service, ...services]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (newCustomers: Customer[], newVehicles: Vehicle[], newServices: ServiceRecord[]) => {
    setCustomers(newCustomers);
    setVehicles(newVehicles);
    setServices(newServices);
  };

  const handleNavigateToVehicle = (vId: string) => { setTargetVehicleId(vId); setActiveView('vehicles'); };
  const handleNavigateToOrder = (oId: string) => { setTargetOrderId(oId); setActiveView('orders'); };
  const handleNavigateToCustomer = (cId: string) => { setTargetCustomerId(cId); setActiveView('customers'); };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">{companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'settings' && <Settings hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Car, 
  Fingerprint, 
  Calendar, 
  Gauge, 
  ChevronRight, 
  ChevronDown,
  Cpu, 
  Plus, 
  X, 
  Check, 
  User,
  History,
  CheckCircle2,
  Clock3,
  AlertTriangle,
  Stethoscope,
  Search,
  Edit3,
  MoreHorizontal,
  Trash2,
  AlertCircle
} from 'lucide-react';
import { Vehicle, Customer, ServiceRecord } from '../types';

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle: Vehicle) => void;
  onUpdateVehicle?: (vehicle: Vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  onNavigateToCustomer?: (customerId: string) => void;
  onNavigateToOrder?: (orderId: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [search, setSearch] = useState('');
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) setSearch(v.licensePlate);
    } else if (!autoOpen) {
      setSearch('');
    }
  }, [initialVehicleId, vehicles, autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleHistory = (vehicleId: string) => {
    const newExpanded = new Set(expandedHistories);
    if (newExpanded.has(vehicleId)) newExpanded.delete(vehicleId);
    else newExpanded.add(vehicleId);
    setExpandedHistories(newExpanded);
  };

  const filteredVehicles = vehicles.filter(v => 
    v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
    v.make.toLowerCase().includes(search.toLowerCase()) ||
    v.model.toLowerCase().includes(search.toLowerCase())
  );

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) onUpdateVehicle({ ...vehicleToUpdate, ...formData });
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = { ...formData, id: `v${Date.now()}`, lastServiceDate: new Date().toISOString().split('T')[0] };
      onAddVehicle(newVehicle);
    }
    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-500 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        {initialVehicleId && search && (
          <button onClick={() => setSearch('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredVehicles.map(v => {
          const owner = customers.find(c => c.id === v.customerId);
          const vehicleServices = services.filter(s => s.vehicleId === v.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const isHistoryExpanded = expandedHistories.has(v.id);

          return (
            <div key={v.id} className={`bg-white rounded-[2rem] border shadow-sm overflow-hidden hover:shadow-xl transition-all group flex flex-col ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
              <div className="flex flex-col md:flex-row">
                <div className="md:w-56 bg-slate-50 p-8 flex flex-col items-center justify-center border-r border-slate-100 group-hover:bg-blue-600 group-hover:text-white transition-all duration-500 shrink-0">
                  <div className="w-24 h-24 rounded-full bg-white flex items-center justify-center shadow-lg mb-6 group-hover:scale-110 transition-transform"><Car className="w-12 h-12 text-slate-900" /></div>
                  <div className="bg-slate-900 text-white font-mono font-bold px-4 py-1.5 rounded-lg text-sm border-2 border-slate-700 shadow-sm group-hover:border-white transition-colors uppercase">{v.licensePlate}</div>
                  <p className="mt-4 text-[10px] font-black uppercase tracking-widest opacity-40 group-hover:opacity-100">Registrační značka</p>
                </div>

                <div className="flex-1 p-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none mb-2">{v.make} {v.model}</h3>
                      <button 
                        onClick={() => owner && onNavigateToCustomer?.(owner.id)}
                        className="text-sm font-bold text-blue-600 hover:text-blue-800 hover:underline transition-all text-left"
                      >
                        Vlastník: {owner ? `${owner.firstName} ${owner.lastName}` : 'Neznámý'}
                      </button>
                    </div>
                    <div className="relative">
                      <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-3 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}><MoreHorizontal className="w-5 h-5" /></button>
                      {openMenuId === v.id && (
                        <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit kartu</button>
                          <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat kartu</button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Calendar className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Expirace STK</p><p className="text-sm font-bold text-slate-900">{v.stkExpirationDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Příští servis</p><p className="text-sm font-bold text-slate-900">{v.nextServiceDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Nájezd km</p><p className="text-sm font-bold text-slate-900">{v.mileage.toLocaleString()}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Kód motoru</p><p className="text-sm font-bold text-slate-900">{v.engineCode || 'N/A'}</p></div></div>
                  </div>

                  <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                    <div className="flex items-center gap-2"><Fingerprint className="w-4 h-4 text-slate-300" /><span className="text-[11px] font-bold text-slate-400 font-mono">VIN: {v.vin}</span></div>
                    <button onClick={() => toggleHistory(v.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-wider transition-all ${isHistoryExpanded ? 'bg-slate-900 text-white' : 'text-blue-600 hover:bg-blue-50'}`}><History className="w-4 h-4" />{isHistoryExpanded ? 'Zavřít historii' : 'Detail historie'}{isHistoryExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}</button>
                  </div>
                </div>
              </div>

              {isHistoryExpanded && (
                <div className="bg-slate-50 border-t border-slate-100 p-8 animate-in slide-in-from-top-4 duration-300">
                  <div className="flex items-center gap-3 mb-6"><History className="w-5 h-5 text-slate-400" /><h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">Kompletní servisní historie</h4></div>
                  {vehicleServices.length > 0 ? (
                    <div className="space-y-4">
                      {vehicleServices.map((service, idx) => (
                        <div key={service.id} className="relative flex gap-6">
                          {idx !== vehicleServices.length - 1 && <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-200"></div>}
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 ${service.status === 'hotovo' ? 'bg-emerald-100 text-emerald-600' : service.status === 'naplánováno' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'}`}>{service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}</div>
                          <div 
                            onClick={() => onNavigateToOrder?.(service.id)}
                            className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all group/item cursor-pointer hover:border-blue-300 hover:shadow-md"
                          >
                            <div>
                              <div className="flex items-center gap-2 mb-1"><span className="text-xs font-black text-slate-900">{service.date}</span><span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-700' : service.status === 'naplánováno' ? 'bg-blue-50 text-blue-700' : 'bg-amber-50 text-amber-700'}`}>{service.status}</span></div>
                              <p className="text-sm font-medium text-slate-600 group-hover/item:text-blue-600 transition-colors">{service.description}</p>
                              <div className="flex items-center gap-2 mt-2"><User className="w-3 h-3 text-slate-400" /><span className="text-[10px] font-bold text-slate-400">Technik: {service.technician}</span></div>
                            </div>
                            <div className="text-right shrink-0 flex items-center gap-4">
                              <p className="text-lg font-black text-slate-900">{service.cost.toLocaleString()} Kč</p>
                              <ChevronRight className="w-4 h-4 text-slate-300 group-hover/item:text-blue-500 group-hover/item:translate-x-1 transition-all" />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : <div className="text-center py-10 bg-white/50 rounded-3xl border-2 border-dashed border-slate-200"><p className="text-slate-400 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p></div>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">Opravdu chcete smazat kartu vozidla <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate})</span>?</p>
              <div className="flex gap-3"><button onClick={() => setDeletingVehicle(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200">ZRUŠIT</button><button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 shadow-lg shadow-red-600/20">SMAZAT</button></div>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div><h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3><p className="text-blue-100 text-xs font-bold uppercase tracking-widest mt-1">{editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}</p></div>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto">
              <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník</label><select required className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}><option value="">Vyberte zákazníka...</option>{customers.map(c => (<option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>))}</select></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label><input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.engineCode} onChange={e => setFormData({...formData, engineCode: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nájezd km</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.mileage} onChange={e => setFormData({...formData, mileage: parseInt(e.target.value)})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Barva</label><input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.color} onChange={e => setFormData({...formData, color: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Datum expirace STK</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.stkExpirationDate} onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Termín příštího servisu</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.nextServiceDate} onChange={e => setFormData({...formData, nextServiceDate: e.target.value})} /></div>
              <button type="submit" className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"><Check className="w-5 h-5" />{editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  selectedPrinter
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'waiting' | 'active' | 'done'>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [previewOrder, setPreviewOrder] = useState<ServiceRecord | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) handleEdit(order);
    }
  }, [initialOrderId, services]);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
  };

  const handleOpenPreview = (order: ServiceRecord) => {
    setPreviewOrder(order);
    setIsPreviewOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);
    if (statusFilter === 'waiting' && order.status !== 'naplánováno') return false;
    if (statusFilter === 'active' && order.status !== 'probíhá') return false;
    if (statusFilter === 'done' && order.status !== 'hotovo') return false;
    if (!search) return true;
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      {/* Real Print Template (Hidden from UI, visible to Browser Print) */}
      <div className="hidden print:block">
        {previewOrder && (
          <PrintTemplate 
            order={previewOrder} 
            company={companyInfo} 
            vehicles={vehicles} 
            customers={customers} 
            hourlyRate={hourlyRate} 
          />
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence zakázkových listů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 print:hidden">
        <div className="flex-1 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat zakázku (ID, SPZ, Jméno)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="bg-slate-200/50 p-1.5 rounded-2xl flex items-center gap-1 shrink-0">
          {(['all', 'waiting', 'active', 'done'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'
              }`}
            >
              {f === 'all' ? 'Vše' : f === 'waiting' ? 'Čeká' : f === 'active' ? 'Aktivní' : 'Hotovo'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12 print:hidden">
        {filteredOrders.map(order => {
          const vehicle = vehicles.find(v => v.id === order.vehicleId);
          const owner = customers.find(c => c.id === vehicle?.customerId);
          return (
            <div key={order.id} className="bg-white rounded-[2rem] border border-slate-100 p-8 hover:shadow-xl transition-all flex flex-col lg:flex-row items-center gap-8 group">
              <div className="flex items-center gap-6 min-w-[250px]">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${
                  order.status === 'hotovo' ? 'bg-emerald-500' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'
                }`}>
                  <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">{order.id}</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{order.date}</p>
                </div>
              </div>
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Vozidlo</p>
                    <p className="text-sm font-bold">{vehicle?.make} {vehicle?.model} <span className="text-blue-600 ml-1">({vehicle?.licensePlate})</span></p>
                 </div>
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Zákazník</p>
                    <p className="text-sm font-bold">{owner?.lastName} {owner?.firstName}</p>
                 </div>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => handleOpenPreview(order)}
                  className="p-4 text-slate-400 hover:text-blue-600 bg-slate-50 rounded-2xl hover:bg-blue-50 transition-all"
                  title="Náhled a tisk"
                >
                  <Eye className="w-6 h-6" />
                </button>
                <button 
                  onClick={() => setDeletingOrder(order)}
                  className="p-4 text-slate-300 hover:text-red-500 rounded-2xl hover:bg-red-50 transition-all"
                >
                  <Trash2 className="w-6 h-6" />
                </button>
                <button 
                  onClick={() => handleEdit(order)}
                  className="bg-slate-900 text-white px-6 py-4 rounded-2xl font-black text-xs hover:bg-blue-600 transition-all"
                >
                  DETAIL
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Tiskový Náhled (Modal) */}
      {isPreviewOpen && previewOrder && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsPreviewOpen(false)}></div>
          <div className="bg-white w-full max-w-5xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col">
            <div className="p-6 border-b flex justify-between items-center shrink-0">
              <h3 className="text-xl font-black tracking-tight">Náhled zakázkového listu</h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => window.print()}
                  className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg shadow-blue-200"
                >
                  <Printer className="w-5 h-5" /> TISKNOUT
                </button>
                <button onClick={() => setIsPreviewOpen(false)} className="p-2 hover:bg-slate-100 rounded-xl">
                  <X className="w-6 h-6 text-slate-400" />
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-xl transform scale-90 origin-top">
                 <PrintTemplate 
                    order={previewOrder} 
                    company={companyInfo} 
                    vehicles={vehicles} 
                    customers={customers} 
                    hourlyRate={hourlyRate} 
                 />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Editor Zakázky (Modal) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <form onSubmit={handleSubmit} className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh]">
            <div className={`p-8 text-white flex justify-between items-center shrink-0 ${editingOrderId ? 'bg-slate-900' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                <ClipboardList className="w-10 h-10" />
                <div>
                  <h3 className="text-3xl font-black uppercase tracking-tight">{editingOrderId ? `UPRAVIT ZAKÁZKU ${editingOrderId}` : 'NOVÁ ZAKÁZKA'}</h3>
                </div>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)}><X className="w-8 h-8" /></button>
            </div>

            <div className="p-10 space-y-10 overflow-y-auto flex-1 custom-scrollbar bg-slate-50/30">

              {/* Sekce: Základní údaje */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">VOZIDLO</label>
                  <select 
                    required
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.vehicleId}
                    onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                  >
                    <option value="">Vyberte vozidlo...</option>
                    {vehicles.map(v => (
                      <option key={v.id} value={v.id}>{v.licensePlate} - {v.make} {v.model}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PLATBA</label>
                  <select 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.paymentType}
                    onChange={e => setFormData({...formData, paymentType: e.target.value as any})}
                  >
                    <option value="Hotovost">Hotovost</option>
                    <option value="Faktura">Faktura</option>
                    <option value="Pojišťovna">Pojišťovna</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">PŘEDBĚŽNÁ CENA (KČ)</label>
                  <input 
                    type="number"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                    value={formData.estimatedPrice}
                    onChange={e => setFormData({...formData, estimatedPrice: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>

              {/* Sekce: Checklist výbavy */}
              <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <Car className="w-5 h-5 text-blue-600" /> STAV VOZIDLA PŘI PŘÍJMU
                </h4>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-6">
                  {Object.keys(formData.checklist).map((key) => (
                    <label key={key} className="flex items-center gap-3 cursor-pointer group">
                      <input 
                        type="checkbox"
                        className="hidden"
                        checked={formData.checklist[key as keyof VehicleChecklist]}
                        onChange={() => setFormData({
                          ...formData, 
                          checklist: { ...formData.checklist, [key]: !formData.checklist[key as keyof VehicleChecklist] }
                        })}
                      />
                      <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                        formData.checklist[key as keyof VehicleChecklist] ? 'bg-blue-600 border-blue-600' : 'border-slate-200 group-hover:border-blue-400'
                      }`}>
                        {formData.checklist[key as keyof VehicleChecklist] && <Check className="w-4 h-4 text-white" />}
                      </div>
                      <span className="text-xs font-bold text-slate-600 capitalize">{key}</span>
                    </label>
                  ))}
                </div>

