import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, ChevronRight
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  autoOpen, 
  onModalOpened, 
  initialOrderId
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'waiting' | 'active' | 'done'>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    technician: 'Jan Mechanik',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status']
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) handleEdit(order);
    }
  }, [initialOrderId, services]);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status
    });
    setIsModalOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
    resetForm();
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'úkon', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      technician: 'Jan Mechanik',
      laborHours: 0,
      status: 'naplánováno'
    });
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);
    if (statusFilter === 'waiting' && order.status !== 'naplánováno') return false;
    if (statusFilter === 'active' && order.status !== 'probíhá') return false;
    if (statusFilter === 'done' && order.status !== 'hotovo') return false;
    if (!search) return true;
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence servisních listů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-4">
        <div className="flex-1 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat zakázku (ID, SPZ, Jméno)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="bg-slate-200/50 p-1.5 rounded-2xl flex items-center gap-1 shrink-0">
          {(['all', 'waiting', 'active', 'done'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'
              }`}
            >
              {f === 'all' ? 'Vše' : f === 'waiting' ? 'Čeká' : f === 'active' ? 'Aktivní' : 'Hotovo'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12">
        {filteredOrders.map(order => {
          const vehicle = vehicles.find(v => v.id === order.vehicleId);
          const owner = customers.find(c => c.id === vehicle?.customerId);
          return (
            <div key={order.id} className="bg-white rounded-[2rem] border border-slate-100 p-8 hover:shadow-xl transition-all flex flex-col lg:flex-row items-center gap-8 group">
              <div className="flex items-center gap-6 min-w-[250px]">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${
                  order.status === 'hotovo' ? 'bg-emerald-500' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'
                }`}>
                  <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">{order.id}</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{order.date}</p>
                </div>
              </div>
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Vozidlo</p>
                    <p className="text-sm font-bold">{vehicle?.make} {vehicle?.model} <span className="text-blue-600 ml-1">({vehicle?.licensePlate})</span></p>
                 </div>
                 <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Zákazník</p>
                    <p className="text-sm font-bold">{owner?.lastName} {owner?.firstName}</p>
                 </div>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => handleEdit(order)}
                  className="bg-slate-900 text-white px-6 py-4 rounded-2xl font-black text-xs hover:bg-blue-600 transition-all"
                >
                  DETAIL
                </button>
                <button 
                  onClick={() => setDeletingOrder(order)}
                  className="p-4 text-slate-300 hover:text-red-500 rounded-2xl hover:bg-red-50 transition-all"
                >
                  <Trash2 className="w-6 h-6" />
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Editor Zakázky (Modal) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <form onSubmit={handleSubmit} className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[95vh]">
            <div className={`p-8 text-white flex justify-between items-center shrink-0 ${editingOrderId ? 'bg-slate-900' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                <ClipboardList className="w-10 h-10" />
                <h3 className="text-2xl font-black uppercase tracking-tight">{editingOrderId ? `Editace zakázky ${editingOrderId}` : 'Nová zakázka'}</h3>
              </div>
              <button type="button" onClick={() => setIsModalOpen(false)}><X className="w-8 h-8" /></button>
            </div>

            <div className="p-10 space-y-8 overflow-y-auto flex-1 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Vozidlo</label>
                    <select 
                      required
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                      value={formData.vehicleId}
                      onChange={e => setFormData({...formData, vehicleId: e.target.value})}
                    >
                      <option value="">Vyberte vozidlo...</option>
                      {vehicles.map(v => (
                        <option key={v.id} value={v.id}>{v.licensePlate} - {v.make} {v.model}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Popis práce / Závada</label>
                    <textarea 
                      required
                      rows={4}
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold resize-none"
                      value={formData.description}
                      onChange={e => setFormData({...formData, description: e.target.value})}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Datum příjmu</label>
                      <input type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Status</label>
                      <select className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})}>
                        <option value="naplánováno">Naplánováno</option>
                        <option value="probíhá">Probíhá</option>
                        <option value="hotovo">Hotovo</option>
                        <option value="zrušeno">Zrušeno</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50 p-8 rounded-[2rem] space-y-6">
                  <div className="flex items-center justify-between">
                    <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">Práce a materiál</h4>
                    <div className="flex gap-2">
                      <button type="button" onClick={() => setIsPriceListPickerOpen(true)} className="p-2 bg-blue-100 text-blue-600 rounded-lg hover:bg-blue-200 transition-all"><Tag className="w-4 h-4" /></button>
                      <button type="button" onClick={addPart} className="p-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition-all"><Plus className="w-4 h-4" /></button>
                    </div>
                  </div>

                  <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                    {formData.parts.map(p => (
                      <div key={p.id} className="flex gap-2 items-center bg-white p-2 rounded-xl border border-slate-100 shadow-sm">
                        <input type="text" className="flex-1 bg-transparent border-none text-xs font-bold outline-none" placeholder="Popis..." value={p.description} onChange={e => updatePart(p.id, 'description', e.target.value)} />
                        <input type="number" className="w-12 bg-slate-50 rounded-lg p-1 text-center text-xs font-black" value={p.quantity} onChange={e => updatePart(p.id, 'quantity', parseFloat(e.target.value) || 0)} />
                        <input type="number" className="w-20 bg-slate-50 rounded-lg p-1 text-right text-xs font-black text-blue-600" value={p.unitPrice} onChange={e => updatePart(p.id, 'unitPrice', parseFloat(e.target.value) || 0)} />
                        <button type="button" onClick={() => removePart(p.id)} className="text-red-300 hover:text-red-500 p-1"><X className="w-4 h-4" /></button>
                      </div>
                    ))}
                  </div>

                  <div className="pt-6 border-t border-slate-200 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hodin práce (sazba {hourlyRate} Kč)</label>
                        <input type="number" className="w-24 bg-white border-2 border-slate-100 rounded-xl px-3 py-2 font-black text-sm" value={formData.laborHours} onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})} />
                      </div>
                      <div className="text-right">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Celkem k úhradě</p>
                        <p className="text-3xl font-black text-slate-900">{calculatedCost.toLocaleString()} Kč</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-8 border-t bg-slate-50 flex justify-end gap-4 shrink-0">
               <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 py-4 rounded-2xl font-black text-sm text-slate-400 hover:text-slate-600 transition-all uppercase">Zavřít</button>
               <button type="submit" className="px-12 py-4 rounded-2xl font-black text-sm bg-blue-600 text-white shadow-xl shadow-blue-600/20 hover:bg-blue-700 transition-all uppercase">Uložit zakázku</button>
            </div>
          </form>
        </div>
      )}

      {/* Price List Picker */}
      {isPriceListPickerOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsPriceListPickerOpen(false)}></div>
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="p-6 border-b flex justify-between items-center bg-slate-50">
                <h4 className="font-black text-xs uppercase tracking-widest">Výběr z ceníku</h4>
                <button onClick={() => setIsPriceListPickerOpen(false)}><X className="w-4 h-4 text-slate-400" /></button>
             </div>
             <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto custom-scrollbar">
                {fixedServices.map(item => (
                  <button 
                    key={item.id} 
                    type="button" 
                    onClick={() => addFromPriceList(item)}
                    className="w-full p-4 rounded-2xl hover:bg-blue-50 transition-all flex justify-between items-center group"
                  >
                    <span className="font-bold text-sm text-slate-700 group-hover:text-blue-700">{item.name}</span>
                    <span className="font-black text-blue-600">{item.price} Kč</span>
                  </button>
                ))}
             </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat zakázku?</h3>
              <p className="text-slate-500 font-medium mb-8">Opravdu chcete odstranit zakázku <span className="font-bold text-slate-900">{deletingOrder.id}</span>?</p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingOrder(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20 uppercase">Smazat</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>
    </div>
  );
};

