                          <input 
                            type="number"
                            className="bg-white border border-slate-200 rounded px-2 py-1 font-black text-xs outline-none w-24"
                            value={formData.laborHours}
                            onChange={e => setFormData({...formData, laborHours: parseFloat(e.target.value) || 0})}
                          />
                       </div>
                       <div className="flex justify-between font-black text-xs">
                          <span>CELKEM BEZ DPH</span>
                          <span>{calculatedCost.toLocaleString()} Kč</span>
                       </div>
                       <div className="flex justify-between font-bold text-[10px] text-slate-500">
                          <span>DPH 21%</span>
                          <span>{(calculatedCost * 0.21).toLocaleString(undefined, {maximumFractionDigits:0})} Kč</span>
                       </div>
                       <div className="bg-slate-900 text-white p-3 rounded-xl mt-4 text-center">
                          <p className="text-[8px] font-black uppercase tracking-widest opacity-60">Cena celkem k úhradě</p>
                          <p className="text-2xl font-black">{(calculatedCost * 1.21).toLocaleString(undefined, {maximumFractionDigits:0})} Kč</p>
                       </div>
                    </div>
                  </div>
