                   <span>ID: {formData.id || 'NEW'}</span>
                   <span>Generováno: {new Date().toLocaleString()}</span>
                   <span>AutoService Pro DB v2.5</span>
                </div>

              </div>
            </div>
          </div>
        </div>
      )}

      {/* Price List Picker - Overlay */}
      {isPriceListPickerOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsPriceListPickerOpen(false)}></div>
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="p-6 border-b flex justify-between items-center bg-slate-50">
                <h4 className="font-black text-xs uppercase tracking-widest">Výběr z ceníku úkonů</h4>
                <button onClick={() => setIsPriceListPickerOpen(false)}><X className="w-4 h-4 text-slate-400" /></button>
             </div>
             <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto custom-scrollbar">
                {fixedServices.map(item => (
                  <button 
                    key={item.id} 
                    type="button" 
                    onClick={() => addFromPriceList(item)}
                    className="w-full p-4 rounded-2xl hover:bg-blue-50 transition-all flex justify-between items-center group"
                  >
                    <span className="font-bold text-sm text-slate-700 group-hover:text-blue-700">{item.name}</span>
                    <span className="font-black text-blue-600">{item.price} Kč</span>
                  </button>
                ))}
             </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat zakázku?</h3>
              <p className="text-slate-500 font-medium mb-8">Opravdu chcete odstranit zakázku <span className="font-bold text-slate-900">{deletingOrder.id}</span>?</p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingOrder(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20 uppercase">Smazat</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @media print {
          body { visibility: hidden !important; background: white !important; }
          #root { display: none !important; }
          .print-block { visibility: visible !important; position: absolute; left: 0; top: 0; width: 100%; display: block !important; }
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

