          <p className="text-2xl font-black mt-2">č. {order.id}</p>
        </div>
        <div className="col-span-8 border-r-2 border-black grid grid-cols-4">
           {/* Checklist for print */}
           {[
             { k: 'rezerva', l: 'Rezerva' }, { k: 'trojuhelnik', l: 'Trojúhelník' },
             { k: 'zvedak', l: 'Zvedák' }, { k: 'lekarna', l: 'Lékárna' },
             { k: 'klic', l: 'Klíč kol.' }, { k: 'radio', l: 'Radio' },
             { k: 'naradi', l: 'Nářadí' }, { k: 'reflektory', l: 'Reflektory' },
             { k: 'hustilka', l: 'Hustilka' }, { k: 'nosic', l: 'Nosič' },
           ].map(i => (
             <div key={i.k} className="p-1 border-r border-b border-black flex items-center justify-between">
                <span className="text-[8px] font-bold uppercase">{i.l}</span>
                {order.checklist?.[i.k as keyof VehicleChecklist] ? <CheckSquare className="w-3 h-3" /> : <Square className="w-3 h-3" />}
             </div>
           ))}
           <div className="col-span-2 p-1 border-b border-black font-black uppercase text-[8px]">Vozidlo: {vehicle?.make} {vehicle?.model}</div>
           <div className="col-span-2 p-1 border-b border-black font-black uppercase text-[8px]">RZ: {vehicle?.licensePlate}</div>
           <div className="col-span-1 p-1 border-r border-black font-bold text-[8px]">VIN: {vehicle?.vin}</div>
           <div className="col-span-1 p-1 border-r border-black font-black text-[8px]">Motor: {vehicle?.engineCode}</div>
           <div className="p-1 border-r border-black font-bold text-[8px]">Palivo: {order.fuelLevel}</div>
           <div className="p-1 font-bold text-[8px]">KM: {order.mileageAtEntry}</div>
        </div>
        <div className="col-span-4 grid grid-rows-4">
           <div className="p-2 border-b border-black font-bold text-[8px]">CENA VČ. DPH: {order.estimatedPrice} Kč</div>
           <div className="p-2 border-b border-black font-bold text-[8px]">PLATBA: {order.paymentType}</div>
           <div className="p-2 border-b border-black font-bold text-[8px]">PŘÍJEM: {order.date}</div>
           <div className="p-2 font-black text-[8px] text-red-600">TERMÍN: {order.deliveryDate}</div>
        </div>
        {/* Zvětšení výšky v tiskové šabloně na min-h-[550px] */}
        <div className="col-span-6 border-t-2 border-r-2 border-black min-h-[550px] p-6 text-sm font-bold italic">
           {order.description}
        </div>
        <div className="col-span-6 border-t-2 border-black flex flex-col">
           <table className="w-full text-[8px]">
              <thead>
                <tr className="border-b border-black bg-slate-100">
                  <th className="p-1 border-r border-black text-left">Položka</th>
                  <th className="p-1 border-r border-black text-center w-8">Ks</th>
                  <th className="p-1 border-r border-black text-right w-16">Cena/ks</th>
                  <th className="p-1 text-right w-20">Celkem</th>
                </tr>
              </thead>
              <tbody>
                {order.parts?.map((p, ix) => (
                  <tr key={ix} className="border-b border-black/10">
                    <td className="p-1 border-r border-black">{p.description}</td>
                    <td className="p-1 border-r border-black text-center">{p.quantity}</td>
                    <td className="p-1 border-r border-black text-right">{p.unitPrice}</td>
                    <td className="p-1 text-right">{(p.quantity * p.unitPrice).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
           </table>
           <div className="mt-auto p-4 border-t-2 border-black bg-slate-50">
              <div className="flex justify-between font-black text-[10px]"><span>SOUČET BEZ DPH</span><span>{order.cost} Kč</span></div>
              <div className="bg-black text-white p-2 mt-2 text-center text-lg font-black">CELKEM: {(order.cost * 1.21).toLocaleString(undefined, {maximumFractionDigits:0})} Kč</div>
           </div>
        </div>
      </div>
      <div className="mt-20 flex justify-between px-10">
         <div className="text-center border-t border-black pt-2 px-10"><p className="text-[9px] font-black uppercase">Za AutoServis</p></div>
         <div className="text-center border-t border-black pt-2 px-10"><p className="text-[9px] font-black uppercase">Za Zákazníka</p></div>
      </div>
    </div>
  );
};

export default OrderManager;

