                <h3 className="text-xl font-black tracking-tight uppercase">Editace Zakázkového Listu</h3>
              </div>
              <div className="flex gap-4">
                <button 
                  type="button"
                  onClick={() => window.print()}
                  className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl font-black text-sm flex items-center gap-2 hover:bg-slate-200"
