                  {/* Blok: Opravna */}
                  <div className="col-span-4 border-r-2 border-b-2 border-black p-3 bg-slate-50/50">
                    <p className="text-[8px] font-black uppercase mb-1">Opravna - DIČ</p>
                    <p className="font-black text-sm uppercase leading-tight">{companyInfo.name}</p>
                    <p className="font-bold text-[10px] mt-1">{companyInfo.address}</p>
                    <p className="text-[8px] mt-1">IČO: {companyInfo.ico} | DIČ: {companyInfo.dic}</p>
                  </div>

                  {/* Blok: Zákazník (Selectable/Auto) */}
