                    <p className="text-[8px] font-black uppercase mb-1">Zákazník</p>
                    <div className="font-black text-xs">
                       {currentCustomer ? (
                         <>
                           <p className="text-blue-700 uppercase">{currentCustomer.companyName || `${currentCustomer.firstName} ${currentCustomer.lastName}`}</p>
                           <p className="text-[10px] font-bold mt-1">{currentCustomer.address}</p>
                           <p className="text-[9px] mt-1">Tel: {currentCustomer.phone}</p>
                         </>
