const CACHE_NAME = 'autoservice-pro-v2';
const STATIC_ASSETS = [
  './',
  './index.html',
  './index.tsx', // Důležité: bez tohoto souboru aplikace offline nenaběhne
  './manifest.json',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap'
];

// Install Event - Pre-cache critical files
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => {
      console.log('Service Worker: Caching critical assets');
      return cache.addAll(STATIC_ASSETS);
    })
  );
  self.skipWaiting();
});

// Activate Event - Clean up old caches
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys => {
      return Promise.all(
        keys.filter(key => key !== CACHE_NAME)
            .map(key => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

// Fetch Event - Strategic Caching
self.addEventListener('fetch', event => {
  // Skip cross-origin non-GET requests (Gemini API, etc.)
  if (event.request.method !== 'GET') return;

  // For Gemini API or other external services, use Network Only
  if (event.request.url.includes('generativelanguage.googleapis.com')) {
    return;
  }

  // Strategy: Network First, Fallback to Cache
  event.respondWith(
    fetch(event.request)
      .then(networkResponse => {
        // If the request is successful, clone it and save to cache
        if (networkResponse && networkResponse.status === 200) {
          const responseClone = networkResponse.clone();
          caches.open(CACHE_NAME).then(cache => {
            cache.put(event.request, responseClone);
          });
        }
        return networkResponse;
      })
      .catch(() => {
        // If network fails (offline), return from cache
        return caches.match(event.request).then(cachedResponse => {
          if (cachedResponse) {
            return cachedResponse;
          }

          // Fallback for navigation requests (SPA)
          if (event.request.mode === 'navigate') {
            return caches.match('./index.html');
          }

          return null;
        });
      })
  );
});

const CACHE_NAME = 'autoservice-pro-v3';
const STATIC_ASSETS = [
  './',
  'index.html',
  'index.tsx',
  'manifest.json',
  'https://cdn.tailwindcss.com',
