          <p className="font-black text-[12px] uppercase leading-tight">{company.name}</p>
          <p className="font-bold text-[10px] mt-1">{company.address}</p>
          <p className="text-[7px] mt-1 font-bold">IČO: {company.ico} | DIČ: {company.dic}</p>
        </div>

        {/* Zákazník */}
        <div className="col-span-4 border-r-[2px] border-b-[2px] border-black p-4">
          <p className="text-[7px] font-black uppercase mb-1">Zákazník</p>
          <p className="font-black text-[12px] uppercase leading-tight">{customerName}</p>
          <p className="font-bold text-[9px] mt-1">{customer?.address || '---'}</p>
          <p className="text-[7px] mt-1 font-bold">Tel: {customer?.phone || '---'}</p>
