  const customer = vehicle ? customers.find(c => c.id === vehicle.customerId) : null;

  // Safe extraction of names to avoid "UNDEFINED"
  const getCustomerName = () => {
    if (!customer) return "---";
    if (customer.companyName) return customer.companyName.toUpperCase();
    const first = customer.firstName || "";
    const last = customer.lastName || "";
    return `${first} ${last}`.trim().toUpperCase() || "---";
  };

  return (
    <div className="print-block bg-white text-black font-sans">
