      xml += `      <EngineCode>${v.engineCode}</EngineCode>\n`;
      xml += `      <Color>${v.color}</Color>\n`;
      xml += `      <STKExpiration>${v.stkExpirationDate}</STKExpiration>\n`;
      xml += `      <NextService>${v.nextServiceDate}</NextService>\n`;
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += `      <Date>${s.date}</Date>\n`;
      xml += `      <DeliveryDate>${s.deliveryDate || ''}</DeliveryDate>\n`;
      xml += `      <Description>${s.description.replace(/[<>&"']/g, (c: string) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c))}</Description>\n`;
      xml += `      <Cost>${s.cost}</Cost>\n`;
      xml += `      <Status>${s.status}</Status>\n`;
      xml += `      <Technician>${s.technician}</Technician>\n`;
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part>\n`;
          xml += `          <Description>${p.description}</Description>\n`;
          xml += `          <Quantity>${p.quantity}</Quantity>\n`;
          xml += `          <UnitPrice>${p.unitPrice}</UnitPrice>\n`;
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  }, [customers, vehicles, services]);

  useEffect(() => {
    if (!autoBackupSettings.enabled) return;
    const checkBackup = async () => {
      const now = new Date();
      if (now.getHours() === autoBackupSettings.hour && autoBackupSettings.lastBackupDate !== now.toISOString().split('T')[0]) {
        try {
          if (directoryHandle) {
            const xmlData = generateXmlData();
            const options = { mode: 'readwrite' };
            const permission = await (directoryHandle as any).queryPermission(options);
            if (permission === 'granted') {
              const fileHandle = await directoryHandle.getFileHandle(`autoservice_daily_backup.xml`, { create: true });
              const writable = await fileHandle.createWritable();
              await writable.write(xmlData);
              await writable.close();
              const updated = { ...autoBackupSettings, lastBackupDate: now.toISOString().split('T')[0] };
              setAutoBackupSettings(updated);
              localStorage.setItem('autoBackupSettings', JSON.stringify(updated));
            }
          }
        } catch (err) { console.error("Auto-backup failed:", err); }
      }
    };
    const interval = setInterval(checkBackup, 60000);
    return () => clearInterval(interval);
  }, [autoBackupSettings, directoryHandle, generateXmlData]);

  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices([service, ...services]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (newCustomers: Customer[], newVehicles: Vehicle[], newServices: ServiceRecord[]) => {
    setCustomers(newCustomers);
    setVehicles(newVehicles);
    setServices(newServices);
  };

  const handleNavigateToVehicle = (vId: string) => { setTargetVehicleId(vId); setActiveView('vehicles'); };
  const handleNavigateToOrder = (oId: string) => { setTargetOrderId(oId); setActiveView('orders'); };
  const handleNavigateToCustomer = (cId: string) => { setTargetCustomerId(cId); setActiveView('customers'); };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">{companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} technicians={technicians} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PartItem } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onRestoreData: (customers: Customer[], vehicles: Vehicle[], services: ServiceRecord[]) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: any) => void;
  directoryHandle: any;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  selectedPrinter, onPrinterChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'notifications' | 'services' | 'backups' | 'team'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [newTechName, setNewTechName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const confirmRemoveFixedService = () => {
    if (deletingFixedService) {
      onFixedServicesChange(fixedServices.filter(fs => fs.id !== deletingFixedService.id));
      setDeletingFixedService(null);
    }
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  // Helper to generate XML nodes safely
  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="1.0">\n`;

    // Customers
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // Vehicles
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('LastServiceDate', v.lastServiceDate);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // Services
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('EndDate', s.endDate);
      xml += xmlTag('DeliveryDate', s.deliveryDate);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('Unit', p.unit);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        // Parse Customers
        const customerNodes = xmlDoc.querySelectorAll("Customer");
        const importedCustomers: Customer[] = Array.from(customerNodes).map(node => ({
          id: node.getAttribute("id") || `c${Math.random()}`,
          firstName: node.querySelector("FirstName")?.textContent || "",
          lastName: node.querySelector("LastName")?.textContent || "",
          email: node.querySelector("Email")?.textContent || "",
          phone: node.querySelector("Phone")?.textContent || "",
          address: node.querySelector("Address")?.textContent || "",
          createdAt: node.querySelector("CreatedAt")?.textContent || new Date().toISOString().split('T')[0],
          companyName: node.querySelector("CompanyName")?.textContent || undefined,
          companyAddress: node.querySelector("CompanyAddress")?.textContent || undefined,
          ico: node.querySelector("ICO")?.textContent || undefined,
          dic: node.querySelector("DIC")?.textContent || undefined,
        }));

        // Parse Vehicles
        const vehicleNodes = xmlDoc.querySelectorAll("Vehicle");
        const importedVehicles: Vehicle[] = Array.from(vehicleNodes).map(node => ({
          id: node.getAttribute("id") || `v${Math.random()}`,
          customerId: node.getAttribute("customerId") || "",
          make: node.querySelector("Make")?.textContent || "",
          model: node.querySelector("Model")?.textContent || "",
          year: parseInt(node.querySelector("Year")?.textContent || "0"),
          vin: node.querySelector("VIN")?.textContent || "",
          licensePlate: node.querySelector("LicensePlate")?.textContent || "",
          mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
          engineCode: node.querySelector("EngineCode")?.textContent || "",
          color: node.querySelector("Color")?.textContent || "",
          lastServiceDate: node.querySelector("LastServiceDate")?.textContent || "",
          stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent || "",
          nextServiceDate: node.querySelector("NextServiceDate")?.textContent || "",
        }));

        // Parse Services
        const serviceNodes = xmlDoc.querySelectorAll("ServiceRecord");
        const importedServices: ServiceRecord[] = Array.from(serviceNodes).map(node => {
          const partNodes = node.querySelectorAll("Part");
          const parts: PartItem[] = Array.from(partNodes).map(pNode => ({
            id: pNode.getAttribute("id") || `p${Math.random()}`,
            description: pNode.querySelector("Description")?.textContent || "",
            quantity: parseFloat(pNode.querySelector("Quantity")?.textContent || "0"),
            unit: pNode.querySelector("Unit")?.textContent || "ks",
            unitPrice: parseFloat(pNode.querySelector("UnitPrice")?.textContent || "0"),
          }));

          return {
            id: node.getAttribute("id") || `s${Math.random()}`,
            vehicleId: node.getAttribute("vehicleId") || "",
            date: node.querySelector("Date")?.textContent || "",
            endDate: node.querySelector("EndDate")?.textContent || undefined,
            deliveryDate: node.querySelector("DeliveryDate")?.textContent || undefined,
            description: node.querySelector("Description")?.textContent || "",
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: (node.querySelector("Status")?.textContent || "hotovo") as any,
            technician: node.querySelector("Technician")?.textContent || "",
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: parts.length > 0 ? parts : undefined,
          };
        });

        if (importedCustomers.length > 0 || importedVehicles.length > 0) {
          onRestoreData(importedCustomers, importedVehicles, importedServices);
          setBackupStatus('success');
          setTimeout(() => setBackupStatus('idle'), 4000);
        } else {
          throw new Error("Invalid backup structure");
        }
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
        setTimeout(() => setBackupStatus('idle'), 5000);
      }
    };

    reader.onerror = () => {
      setBackupStatus('error');
      setTimeout(() => setBackupStatus('idle'), 5000);
    };

    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button 
          onClick={handleSave}
          className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${
            saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'team', label: 'Tým', icon: User },
          { id: 'services', label: 'Ceník & Služby', icon: DollarSign },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                  <Building className="w-8 h-8 text-blue-600" />
               </div>
               <div>
                  <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Tyto údaje se tisknou na zakázkové listy</p>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
              </div>
