const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');
  const autoBackupTriggeredRef = useRef<string | null>(null);

  // Persisted States - Primary Data
  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : INITIAL_CUSTOMERS;
  });
  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('vehicles');
    return saved ? JSON.parse(saved) : INITIAL_VEHICLES;
  });
  const [services, setServices] = useState<ServiceRecord[]>(() => {
    const saved = localStorage.getItem('services');
    return saved ? JSON.parse(saved) : INITIAL_SERVICES;
  });
  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Persisted States - Settings
  const [hourlyRate, setHourlyRate] = useState<number>(() => {
    const saved = localStorage.getItem('hourlyRate');
    return saved ? JSON.parse(saved) : 850;
  });
  const [fixedServices, setFixedServices] = useState<FixedService[]>(() => {
    const saved = localStorage.getItem('fixedServices');
    return saved ? JSON.parse(saved) : INITIAL_FIXED_SERVICES;
  });
  const [predefinedTasks, setPredefinedTasks] = useState<PredefinedTask[]>(() => {
    const saved = localStorage.getItem('predefinedTasks');
    return saved ? JSON.parse(saved) : INITIAL_PREDEFINED_TASKS;
  });
  const [discountLevels, setDiscountLevels] = useState<number[]>(() => {
    const saved = localStorage.getItem('discountLevels');
    return saved ? JSON.parse(saved) : [0, 5, 10, 15, 20, 25, 50];
  });
  const [technicians, setTechnicians] = useState<string[]>(() => {
    const saved = localStorage.getItem('technicians');
    return saved ? JSON.parse(saved) : ['Jan Mechanik', 'Petr Rychlý', 'Marek Šikovný', 'Tomáš Pečlivý'];
  });
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>(() => {
    const saved = localStorage.getItem('companyInfo');
    return saved ? JSON.parse(saved) : {
      name: 'AutoService Pro Praha',
      address: 'Průmyslová 1024/12, 102 00 Praha 10',
      ico: '12345678',
      dic: 'CZ12345678',
      phone: '+420 222 333 444',
      email: 'servis@autoservice.pro'
    };
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>(() => {
    const saved = localStorage.getItem('notifSettings');
    return saved ? JSON.parse(saved) : {
      stkThresholdDays: 30,
      serviceThresholdDays: 15
    };
  });
  const [selectedPrinter, setSelectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('selectedPrinter');
    return saved ? JSON.parse(saved) : 'HP LaserJet Pro M404dn (Kancelář)';
  });

  // Security State
  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  // Backup automation state
  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });
  const [directoryHandle, setDirectoryHandle] = useState<FileSystemDirectoryHandle | null>(null);

  // Effects for Persisting State
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);
  useEffect(() => { localStorage.setItem('vehicles', JSON.stringify(vehicles)); }, [vehicles]);
  useEffect(() => { localStorage.setItem('services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('invoices', JSON.stringify(invoices)); }, [invoices]);
  useEffect(() => { localStorage.setItem('hourlyRate', JSON.stringify(hourlyRate)); }, [hourlyRate]);
  useEffect(() => { localStorage.setItem('fixedServices', JSON.stringify(fixedServices)); }, [fixedServices]);
  useEffect(() => { localStorage.setItem('predefinedTasks', JSON.stringify(predefinedTasks)); }, [predefinedTasks]);
  useEffect(() => { localStorage.setItem('discountLevels', JSON.stringify(discountLevels)); }, [discountLevels]);
  useEffect(() => { localStorage.setItem('technicians', JSON.stringify(technicians)); }, [technicians]);
  useEffect(() => { localStorage.setItem('companyInfo', JSON.stringify(companyInfo)); }, [companyInfo]);
  useEffect(() => { localStorage.setItem('notifSettings', JSON.stringify(notifSettings)); }, [notifSettings]);
  useEffect(() => { localStorage.setItem('selectedPrinter', JSON.stringify(selectedPrinter)); }, [selectedPrinter]);
  useEffect(() => { 
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) setIsAuthenticated(true);
  }, [userSettings]);

  // Logic for Auto Backup Heartbeat
  useEffect(() => {
    if (!autoBackupSettings.enabled || !directoryHandle) return;

    const checkAndBackup = async () => {
      const now = new Date();
      const currentHour = now.getHours();
      const todayDate = now.toISOString().split('T')[0];

      // Trigger if current hour matches and we haven't backed up today
      if (currentHour === autoBackupSettings.hour && autoBackupSettings.lastBackupDate !== todayDate && autoBackupTriggeredRef.current !== todayDate) {
        autoBackupTriggeredRef.current = todayDate;
        console.log("Triggering auto backup...");

        try {
          const xmlData = generateFullBackupXml();
          const fileName = `autoservice_auto_backup_${todayDate}.xml`;

          // @ts-ignore
          const fileHandle = await directoryHandle.getFileHandle(fileName, { create: true });
          // @ts-ignore
          const writable = await fileHandle.createWritable();
          await writable.write(xmlData);
          await writable.close();

          const newSettings = { ...autoBackupSettings, lastBackupDate: todayDate };
          setAutoBackupSettings(newSettings);
          localStorage.setItem('autoBackupSettings', JSON.stringify(newSettings));
          console.log("Auto backup successful.");
        } catch (err) {
          console.error("Auto backup failed:", err);
          autoBackupTriggeredRef.current = null; // Retry next check if failed
        }
      }
    };

    const interval = setInterval(checkAndBackup, 60000); // Check every minute
    return () => clearInterval(interval);
  }, [autoBackupSettings, directoryHandle]);

  // Sync Mileage Function
  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (!mileageAtEntry || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices([service, ...services]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
  };

  const handleUpdateInvoice = (updatedInvoice: Invoice) => {
    setInvoices(prev => prev.map(inv => inv.id === updatedInvoice.id ? updatedInvoice : inv));
  };

  const handleRestoreData = (fullState: any) => {
    if (fullState.customers) setCustomers(fullState.customers);
    if (fullState.vehicles) setVehicles(fullState.vehicles);
    if (fullState.services) setServices(fullState.services);
    if (fullState.invoices) setInvoices(fullState.invoices);

    // Restore settings if present
    if (fullState.settings) {
      const s = fullState.settings;
      if (s.hourlyRate) setHourlyRate(s.hourlyRate);
      if (s.fixedServices) setFixedServices(s.fixedServices);
      if (s.predefinedTasks) setPredefinedTasks(s.predefinedTasks);
      if (s.discountLevels) setDiscountLevels(s.discountLevels);
      if (s.technicians) setTechnicians(s.technicians);
      if (s.companyInfo) setCompanyInfo(s.companyInfo);
      if (s.notifSettings) setNotifSettings(s.notifSettings);
    }
  };

  const generateFullBackupXml = () => {
    const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.0">\n`;

    // Customers
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // Vehicles
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // Services (Orders)
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    // Invoices
    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    // Settings
    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleCreateInvoiceFromOrder = (orderId: string) => {
    const order = services.find(s => s.id === orderId);
    if (!order) return;
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    if (!vehicle) return;

    if (invoices.some(inv => inv.orderId === orderId)) {
      setActiveView('invoices');
      return;
    }

    const issueDate = new Date();
    const invoiceId = `INV-${orderId.replace(/\//g, '-')}`;
    const dueDate = new Date();
    dueDate.setDate(issueDate.getDate() + 14);

    const newInvoice: Invoice = {
      id: invoiceId,
      orderId: order.id,
      issueDate: issueDate.toISOString().split('T')[0],
      dueDate: dueDate.toISOString().split('T')[0],
      customerId: vehicle.customerId,
      vehicleInfo: `${vehicle.make} ${vehicle.model} (${vehicle.licensePlate})`,
      items: order.parts || [],
      totalExclDph: order.cost,
      totalInclDph: Math.round(order.cost * 1.21),
      paymentType: 'Převodem',
      status: 'neuhrazeno',
      discount: 0
    };

    setInvoices([newInvoice, ...invoices]);
    setActiveView('invoices');
  };

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleNavigateToVehicle = (vId: string) => { setTargetVehicleId(vId); setActiveView('vehicles'); };
  const handleNavigateToOrder = (oId: string) => { setTargetOrderId(oId); setActiveView('orders'); };
  const handleNavigateToCustomer = (cId: string) => { setTargetCustomerId(cId); setActiveView('customers'); };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">{companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span></h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-100 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-500 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} technicians={technicians} predefinedTasks={predefinedTasks} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} onCreateInvoice={handleCreateInvoiceFromOrder} />}
          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(id) => setInvoices(prev => prev.filter(inv => inv.id !== id))} onUpdateInvoiceStatus={(id, status) => setInvoices(prev => prev.map(inv => inv.id === id ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const handleSelectFolder = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setDirectoryHandle(handle);
      onAutoBackupSettingsChange({ ...autoBackupSettings, folderName: handle.name });
    } catch (err) {
      console.error("Folder picker cancelled or failed", err);
    }
  };

  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.0">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const importedData: any = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id"),
            firstName: node.querySelector("FirstName")?.textContent,
            lastName: node.querySelector("LastName")?.textContent,
            email: node.querySelector("Email")?.textContent,
            phone: node.querySelector("Phone")?.textContent,
            address: node.querySelector("Address")?.textContent,
            createdAt: node.querySelector("CreatedAt")?.textContent,
            companyName: node.querySelector("CompanyName")?.textContent,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id"),
            customerId: node.getAttribute("customerId"),
            make: node.querySelector("Make")?.textContent,
            model: node.querySelector("Model")?.textContent,
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent,
            licensePlate: node.querySelector("LicensePlate")?.textContent,
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent,
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent,
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent,
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => ({
            id: node.getAttribute("id"),
            vehicleId: node.getAttribute("vehicleId"),
            date: node.querySelector("Date")?.textContent,
            description: node.querySelector("Description")?.textContent,
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            technician: node.querySelector("Technician")?.textContent,
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: Array.from(node.querySelectorAll("Part")).map(p => ({
              id: p.getAttribute("id"),
              description: p.querySelector("Description")?.textContent,
              quantity: parseFloat(p.querySelector("Quantity")?.textContent || "0"),
              unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
            }))
          })),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id"),
            orderId: node.getAttribute("orderId"),
            issueDate: node.querySelector("IssueDate")?.textContent,
            dueDate: node.querySelector("DueDate")?.textContent,
            customerId: node.querySelector("CustomerId")?.textContent,
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent,
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            paymentType: node.querySelector("PaymentType")?.textContent,
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id"),
              name: node.querySelector("Name")?.textContent,
              price: parseInt(node.querySelector("Price")?.textContent || "0")
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id"),
              label: node.querySelector("Label")?.textContent,
              description: node.querySelector("Description")?.textContent
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button onClick={handleSave} className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}>
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'invoicing', label: 'Fakturace', icon: Percent },
          { id: 'team', label: 'Tým', icon: User },
          { id: 'services', label: 'Ceník', icon: DollarSign },
          { id: 'templates', label: 'Šablony', icon: Layout },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
            <tab.icon className="w-4 h-4" /> {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center"><Database className="w-8 h-8 text-slate-900" /></div>
              <div><h3 className="text-2xl font-black text-slate-900">Zálohování a obnova</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Kompletní ochrana dat servisu</p></div>
            </div>

            {backupStatus !== 'idle' && (
              <div className={`p-4 rounded-2xl flex items-center gap-3 animate-in fade-in zoom-in-95 ${backupStatus === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : backupStatus === 'error' ? 'bg-red-50 text-red-700 border border-red-100' : 'bg-blue-50 text-blue-700 border border-blue-100'}`}>
                {backupStatus === 'processing' ? <Loader2 className="w-5 h-5 animate-spin" /> : <AlertCircle className="w-5 h-5" />}
                <p className="text-sm font-bold">{backupStatus === 'processing' ? 'Probíhá zpracování...' : backupStatus === 'success' ? 'Všechna data (vozidla, zakázky, faktury, nastavení) byla zpracována.' : 'Chyba při zpracování zálohy.'}</p>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Ruční export</h4>
                <p className="text-xs text-slate-500 font-medium leading-relaxed">Stáhne jeden XML soubor obsahující úplně všechna data vašeho servisu včetně ceníků a personálu.</p>
                <button onClick={handleDownloadBackup} disabled={backupStatus === 'processing'} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-50 transition-all">
                  <DownloadCloud className="w-5 h-5" /> STÁHNOUT KOMPLETNÍ ZÁLOHU
                </button>
              </div>
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Obnovit systém</h4>
                <p className="text-xs text-slate-500 font-medium leading-relaxed">Nahrajte XML soubor pro kompletní obnovu. Pozor: Aktuální data v prohlížeči budou přepsána daty ze zálohy.</p>
                <input type="file" accept=".xml" className="hidden" ref={fileInputRef} onChange={handleFileImport} />
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-800 transition-all">
                  <UploadCloud className="w-5 h-5" /> OBNOVIT ZE SOUBORU
                </button>
              </div>
            </div>

            <div className="pt-8 border-t border-slate-100">
               <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center"><CheckCircle2 className="w-6 h-6 text-blue-600" /></div>
                  <h4 className="text-xl font-black text-slate-900 uppercase tracking-tight">Automatizace na HDD</h4>
               </div>

               <div className="bg-slate-900 rounded-[2rem] p-8 text-white space-y-8">
                  <div className="flex items-center justify-between">
                     <div>
                        <p className="font-black text-sm uppercase tracking-widest text-blue-400">Automatické zálohy</p>
                        <p className="text-slate-400 text-xs font-medium mt-1">Ukládá denní zálohu přímo do zvolené složky na vašem počítači.</p>
                     </div>
                     <button 
                        onClick={() => onAutoBackupSettingsChange({...autoBackupSettings, enabled: !autoBackupSettings.enabled})}
                        className={`w-14 h-8 rounded-full transition-all relative ${autoBackupSettings.enabled ? 'bg-blue-500' : 'bg-slate-700'}`}
                     >
                        <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${autoBackupSettings.enabled ? 'left-7' : 'left-1'}`}></div>
                     </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Cílová složka</label>
                       <div className="flex gap-2">
                          <div className="flex-1 bg-slate-800 rounded-xl px-4 py-3 text-xs font-bold text-slate-300 truncate">
                             {autoBackupSettings.folderName || 'Není vybrána...'}
                          </div>
                          <button onClick={handleSelectFolder} className="bg-white text-slate-900 px-4 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-blue-400 transition-colors">Změnit</button>
                       </div>
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><Clock className="w-3 h-3" /> Čas zálohování</label>
                       <div className="flex items-center gap-3">
                          <input 
                            type="number" 
                            min="0" max="23" 
                            className="w-20 bg-slate-800 rounded-xl px-4 py-3 text-sm font-black text-center outline-none border border-slate-700 focus:border-blue-500" 
                            value={autoBackupSettings.hour}
                            onChange={(e) => onAutoBackupSettingsChange({...autoBackupSettings, hour: parseInt(e.target.value) || 0})}
                          />
                          <span className="text-xs font-bold text-slate-500">hodin (každý den)</span>
                       </div>
                    </div>
                  </div>

                  {!directoryHandle && autoBackupSettings.enabled && (
                    <div className="bg-amber-500/10 border border-amber-500/30 p-4 rounded-xl flex items-center gap-3">
                       <AlertCircle className="w-5 h-5 text-amber-500" />
                       <p className="text-xs font-bold text-amber-200">Pro fungování automatické zálohy je nutné po každém startu aplikace "Změnit" složku pro udělení oprávnění prohlížeči.</p>
                    </div>
                  )}

                  {autoBackupSettings.lastBackupDate && (
                    <div className="pt-4 border-t border-slate-800 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                       Poslední úspěšná auto-záloha: <span className="text-emerald-400 ml-2">{autoBackupSettings.lastBackupDate}</span>
                    </div>
                  )}
               </div>
            </div>
          </div>
        )}

        {/* Rest of the tabs... */}
        {activeTab === 'company' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                    <Building className="w-8 h-8 text-blue-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Základní identifikace firmy</p>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Fakturační adresa</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                  <input type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Oficiální Email</label>
                  <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
                </div>
              </div>
            </div>
          </div>
        )}
        {/* ... (Keep existing implementation for invoicing, team, services, templates, notifications tabs) ... */}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const handleSelectFolder = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setDirectoryHandle(handle);
      onAutoBackupSettingsChange({ ...autoBackupSettings, folderName: handle.name });
    } catch (err) {
      console.error("Folder picker cancelled or failed", err);
    }
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => {
    onDiscountLevelsChange(discountLevels.filter(d => d !== val));
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const addTemplate = () => {
    onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  };

  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => {
    onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.0">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const importedData: any = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id"),
            firstName: node.querySelector("FirstName")?.textContent,
            lastName: node.querySelector("LastName")?.textContent,
            email: node.querySelector("Email")?.textContent,
            phone: node.querySelector("Phone")?.textContent,
            address: node.querySelector("Address")?.textContent,
            createdAt: node.querySelector("CreatedAt")?.textContent,
            companyName: node.querySelector("CompanyName")?.textContent,
            companyAddress: node.querySelector("CompanyAddress")?.textContent,
            ico: node.querySelector("ICO")?.textContent,
            dic: node.querySelector("DIC")?.textContent,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id"),
            customerId: node.getAttribute("customerId"),
            make: node.querySelector("Make")?.textContent,
            model: node.querySelector("Model")?.textContent,
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent,
            licensePlate: node.querySelector("LicensePlate")?.textContent,
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent,
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent,
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent,
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => ({
            id: node.getAttribute("id"),
            vehicleId: node.getAttribute("vehicleId"),
            date: node.querySelector("Date")?.textContent,
            description: node.querySelector("Description")?.textContent,
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            technician: node.querySelector("Technician")?.textContent,
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: Array.from(node.querySelectorAll("Part")).map(p => ({
              id: p.getAttribute("id"),
              description: p.querySelector("Description")?.textContent,
              quantity: parseFloat(p.querySelector("Quantity")?.textContent || "0"),
              unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
            }))
          })),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id"),
            orderId: node.getAttribute("orderId"),
            issueDate: node.querySelector("IssueDate")?.textContent,
            dueDate: node.querySelector("DueDate")?.textContent,
            customerId: node.querySelector("CustomerId")?.textContent,
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent,
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            paymentType: node.querySelector("PaymentType")?.textContent,
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id"),
              name: node.querySelector("Name")?.textContent,
              price: parseInt(node.querySelector("Price")?.textContent || "0")
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id"),
              label: node.querySelector("Label")?.textContent,
              description: node.querySelector("Description")?.textContent
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button onClick={handleSave} className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}>
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'invoicing', label: 'Fakturace', icon: Percent },
          { id: 'team', label: 'Tým', icon: User },
          { id: 'services', label: 'Ceník', icon: DollarSign },
          { id: 'templates', label: 'Šablony', icon: Layout },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
            <tab.icon className="w-4 h-4" /> {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                    <Building className="w-8 h-8 text-blue-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Základní identifikace firmy</p>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Fakturační adresa</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                  <input type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Oficiální Email</label>
                  <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'invoicing' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center">
                    <Percent className="w-8 h-8 text-red-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Fakturační nastavení</h3>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Správa slev a výchozích hodnot</p>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Stupně slev (%)</label>
                <div className="flex flex-wrap gap-3">
                  {discountLevels.map(level => (
                    <div key={level} className="flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 group">
                      <span className="font-bold text-slate-900">{level}%</span>
                      <button 
                        onClick={() => removeDiscountLevel(level)}
                        className="p-1 text-slate-300 hover:text-red-500 transition-colors"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                  <div className="flex gap-2">
                    <input 
                      type="number" 
                      placeholder="%"
                      className="w-16 px-3 py-2 bg-slate-50 border-2 border-transparent focus:border-red-500 rounded-xl outline-none font-bold text-center"
                      value={newDiscount}
                      onChange={e => setNewDiscount(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && addDiscountLevel()}
                    />
                    <button 
                      onClick={addDiscountLevel}
                      className="p-2 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors"
                    >
                      <Plus className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'team' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                <User className="w-8 h-8 text-blue-600" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900">Správa týmu</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Seznam mechaniků pro zakázky</p>
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex gap-4 p-4 bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <input 
                  type="text" 
                  placeholder="Jméno nového mechanika..." 
                  className="flex-1 px-5 py-4 bg-white border-none rounded-2xl outline-none font-bold shadow-sm"
                  value={newTechName}
                  onChange={e => setNewTechName(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && addTechnician()}
                />
                <button 
                  onClick={addTechnician}
                  className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-sm hover:bg-blue-700 transition-all shadow-lg shadow-blue-600/20"
                >
                  PŘIDAT
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {technicians.map(tech => (
                  <div key={tech} className="bg-white p-5 rounded-2xl border border-slate-100 flex items-center justify-between group hover:shadow-lg transition-all">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center">
                        <User className="w-5 h-5 text-slate-400" />
                      </div>
                      <span className="font-bold text-slate-900">{tech}</span>
                    </div>
                    <button 
                      onClick={() => removeTechnician(tech)}
                      className="p-3 text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'services' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center"><DollarSign className="w-8 h-8 text-emerald-600" /></div>
                 <div><h3 className="text-2xl font-black text-slate-900">Standardní sazba</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Základní hodinová cena práce</p></div>
              </div>
              <div className="max-w-xs">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Hodinová sazba (Kč)</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-2xl font-black text-lg mt-2 outline-none" value={hourlyRate} onChange={e => onRateChange(parseInt(e.target.value) || 0)} />
              </div>
            </div>

            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Tag className="w-8 h-8 text-blue-600" /></div>
                   <div><h3 className="text-2xl font-black text-slate-900">Položkový ceník</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Služby s fixní cenou</p></div>
                </div>
                <button 
                  onClick={addFixedService}
                  className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold text-xs flex items-center gap-2"
                >
                  <Plus className="w-4 h-4" /> PŘIDAT ÚKON
                </button>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {fixedServices.map(fs => (
                  <div key={fs.id} className="flex flex-col sm:flex-row gap-4 p-4 bg-slate-50 rounded-2xl border border-transparent hover:border-blue-100 transition-all">
                    <div className="flex-1 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Název úkonu</label>
                      <input 
                        type="text"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-bold"
                        placeholder="Např. Výměna brzdové kapaliny..."
                        value={fs.name}
                        onChange={e => updateFixedService(fs.id, 'name', e.target.value)}
                      />
                    </div>
                    <div className="w-full sm:w-40 space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase">Cena (Kč)</label>
                      <input 
                        type="number"
                        className="w-full bg-white border-none rounded-xl px-4 py-2 font-black text-blue-600"
                        value={fs.price}
                        onChange={e => updateFixedService(fs.id, 'price', parseInt(e.target.value) || 0)}
                      />
                    </div>
                    <div className="flex items-end pb-1">
                      <button 
                        onClick={() => setDeletingFixedService(fs)}
                        className="p-3 text-slate-300 hover:text-red-500 transition-colors"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'templates' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center"><Layout className="w-8 h-8 text-blue-600" /></div>
                 <div><h3 className="text-2xl font-black text-slate-900">Šablony závad</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase tracking-widest">Předdefinované popisy oprav</p></div>
              </div>
              <button 
                onClick={addTemplate}
                className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold text-xs flex items-center gap-2"
              >
                <Plus className="w-4 h-4" /> PŘIDAT ŠABLONU
              </button>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {predefinedTasks.map(pt => (
                <div key={pt.id} className="flex flex-col gap-4 p-6 bg-slate-50 rounded-[2rem] border border-transparent hover:border-blue-100 transition-all">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název šablony</label>
                    <input 
                      type="text"
                      className="w-full bg-white border-none rounded-xl px-5 py-3 font-bold shadow-sm"
                      placeholder="Např. Výměna oleje..."
                      value={pt.label}
                      onChange={e => updateTemplate(pt.id, 'label', e.target.value)}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Detailní popis závady/opravy</label>
                    <textarea 
                      className="w-full bg-white border-none rounded-xl px-5 py-3 font-medium text-sm min-h-[80px] shadow-sm resize-none"
                      placeholder="Detailní text, který se vloží do zakázky..."
                      value={pt.description}
                      onChange={e => updateTemplate(pt.id, 'description', e.target.value)}
                    />
                  </div>
                  <div className="flex justify-end">
                    <button 
                      onClick={() => setDeletingTemplate(pt)}
                      className="flex items-center gap-2 text-[10px] font-black text-red-400 hover:text-red-600 uppercase tracking-widest transition-colors"
                    >
                      <Trash2 className="w-4 h-4" /> Odstranit šablonu
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'notifications' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
               <div className="w-16 h-16 bg-amber-50 rounded-2xl flex items-center justify-center"><Bell className="w-8 h-8 text-amber-600" /></div>
               <div><h3 className="text-2xl font-black text-slate-900">Upozornění</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Limity pro hlášení (dny)</p></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">STK expirace</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.stkThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, stkThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Servisní prohlídka</label>
                <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={notifSettings.serviceThresholdDays} onChange={e => onNotifSettingsChange({...notifSettings, serviceThresholdDays: parseInt(e.target.value) || 0})} />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'backups' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-10 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-slate-100 rounded-2xl flex items-center justify-center"><Database className="w-8 h-8 text-slate-900" /></div>
              <div><h3 className="text-2xl font-black text-slate-900">Zálohování a obnova</h3><p className="text-slate-400 text-xs font-bold mt-1 uppercase">Kompletní ochrana dat servisu</p></div>
            </div>

            {backupStatus !== 'idle' && (
              <div className={`p-4 rounded-2xl flex items-center gap-3 animate-in fade-in zoom-in-95 ${backupStatus === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : backupStatus === 'error' ? 'bg-red-50 text-red-700 border border-red-100' : 'bg-blue-50 text-blue-700 border border-blue-100'}`}>
                {backupStatus === 'processing' ? <Loader2 className="w-5 h-5 animate-spin" /> : <AlertCircle className="w-5 h-5" />}
                <p className="text-sm font-bold">{backupStatus === 'processing' ? 'Probíhá zpracování...' : backupStatus === 'success' ? 'Všechna data byla zpracována.' : 'Chyba při zpracování zálohy.'}</p>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Ruční export</h4>
                <p className="text-xs text-slate-500 font-medium leading-relaxed">Stáhne jeden XML soubor obsahující úplně všechna data vašeho servisu.</p>
                <button onClick={handleDownloadBackup} disabled={backupStatus === 'processing'} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-50 transition-all">
                  <DownloadCloud className="w-5 h-5" /> STÁHNOUT KOMPLETNÍ ZÁLOHU
                </button>
              </div>
              <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4">
                <h4 className="font-black text-sm uppercase">Obnovit systém</h4>
                <p className="text-xs text-slate-500 font-medium leading-relaxed">Nahrajte XML soubor pro kompletní obnovu. Aktuální data budou přepsána.</p>
                <input type="file" accept=".xml" className="hidden" ref={fileInputRef} onChange={handleFileImport} />
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 hover:bg-slate-800 transition-all">
                  <UploadCloud className="w-5 h-5" /> OBNOVIT ZE SOUBORU
                </button>
              </div>
            </div>

            <div className="pt-8 border-t border-slate-100">
               <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center"><CheckCircle2 className="w-6 h-6 text-blue-600" /></div>
                  <h4 className="text-xl font-black text-slate-900 uppercase tracking-tight">Automatizace na HDD</h4>
               </div>

               <div className="bg-slate-900 rounded-[2rem] p-8 text-white space-y-8">
                  <div className="flex items-center justify-between">
                     <div>
                        <p className="font-black text-sm uppercase tracking-widest text-blue-400">Automatické zálohy</p>
                        <p className="text-slate-400 text-xs font-medium mt-1">Ukládá denní zálohu přímo do zvolené složky.</p>
                     </div>
                     <button 
                        onClick={() => onAutoBackupSettingsChange({...autoBackupSettings, enabled: !autoBackupSettings.enabled})}
                        className={`w-14 h-8 rounded-full transition-all relative ${autoBackupSettings.enabled ? 'bg-blue-500' : 'bg-slate-700'}`}
                     >
                        <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${autoBackupSettings.enabled ? 'left-7' : 'left-1'}`}></div>
                     </button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Cílová složka</label>
                       <div className="flex gap-2">
                          <div className="flex-1 bg-slate-800 rounded-xl px-4 py-3 text-xs font-bold text-slate-300 truncate">
                             {autoBackupSettings.folderName || 'Není vybrána...'}
                          </div>
                          <button onClick={handleSelectFolder} className="bg-white text-slate-900 px-4 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-blue-400 transition-colors">Změnit</button>
                       </div>
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2"><Clock className="w-3 h-3" /> Čas zálohování</label>
                       <div className="flex items-center gap-3">
                          <input 
                            type="number" 
                            min="0" max="23" 
                            className="w-20 bg-slate-800 rounded-xl px-4 py-3 text-sm font-black text-center outline-none border border-slate-700 focus:border-blue-500" 
                            value={autoBackupSettings.hour}
                            onChange={(e) => onAutoBackupSettingsChange({...autoBackupSettings, hour: parseInt(e.target.value) || 0})}
                          />
                          <span className="text-xs font-bold text-slate-500">hodin</span>
                       </div>
                    </div>
                  </div>

                  {!directoryHandle && autoBackupSettings.enabled && (
                    <div className="bg-amber-500/10 border border-amber-500/30 p-4 rounded-xl flex items-center gap-3">
                       <AlertCircle className="w-5 h-5 text-amber-500" />
                       <p className="text-xs font-bold text-amber-200">Pro fungování automatické zálohy je nutné po každém startu aplikace "Změnit" složku.</p>
                    </div>
                  )}
               </div>
            </div>
          </div>
        )}
      </div>

      {deletingFixedService && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingFixedService(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat položku?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat službu <span className="font-bold text-slate-900">{deletingFixedService.name}</span> z ceníku?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingFixedService(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={() => { onFixedServicesChange(fixedServices.filter(fs => fs.id !== deletingFixedService.id)); setDeletingFixedService(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {deletingTemplate && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingTemplate(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat šablonu?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat šablonu <span className="font-bold text-slate-900">{deletingTemplate.label}</span>?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingTemplate(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm">ZRUŠIT</button>
                <button onClick={() => { onPredefinedTasksChange(predefinedTasks.filter(pt => pt.id !== deletingTemplate.id)); setDeletingTemplate(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-red-600/20">SMAZAT</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Settings;

export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
}

export interface FixedService {
  id: string;
  name: string;
  price: number;
}

export interface PredefinedTask {
  id: string;
  label: string;
  description: string;
}

export interface Invoice {
  id: string;
  orderId: string;
  issueDate: string;
  dueDate: string;
  customerId: string;
  vehicleInfo: string;
  items: PartItem[];
  totalExclDph: number;
  totalInclDph: number;
  paymentType: 'Hotově' | 'Převodem';
  status: 'uhrazeno' | 'neuhrazeno';
  discount?: number;
}

export interface Customer {
  id: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string;
  nextServiceDate: string;
  notes?: string;
}

export interface VehicleChecklist {
  rezerva: boolean;
  zvedak: boolean;
  klic: boolean;
  naradi: boolean;
  hustilka: boolean;
  trojuhelnik: boolean;
  lekarna: boolean;
  radio: boolean;
  reflektory: boolean;
  nosic: boolean;
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  deliveryDate?: string;
  description: string;
  parts?: PartItem[];
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  fuelLevel?: '1/4' | '1/2' | '3/4' | 'Full' | 'Rezerva';
  checklist?: VehicleChecklist;
  mileageAtEntry?: number;
  estimatedPrice?: number;
  paymentType?: 'Hotovost' | 'Faktura' | 'Pojišťovna';
}

export interface CompanyInfo {
  name: string;
  address: string;
  ico: string;
  dic: string;
  phone: string;
  email: string;
}

export interface NotificationSettings {
  stkThresholdDays: number;
  serviceThresholdDays: number;
}

export interface AutoBackupSettings {
  enabled: boolean;
  hour: number;
  lastBackupDate: string | null;
  folderName: string | null;
}

export interface UserSettings {
  enabled: boolean;
  username: string;
  password: string;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'orders' | 'settings' | 'invoices';

import React, { useState, useEffect, useRef } from 'react';
import { 
  Car, 
  Fingerprint, 
  Calendar, 
  Gauge, 
  ChevronRight, 
  ChevronDown,
  Cpu, 
  Plus, 
  X, 
  Check, 
  User,
  History,
  CheckCircle2,
  Clock3,
  AlertTriangle,
  Stethoscope,
  Search,
  Edit3,
  MoreHorizontal,
  Trash2,
  AlertCircle,
  StickyNote
} from 'lucide-react';
import { Vehicle, Customer, ServiceRecord } from '../types';

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle: Vehicle) => void;
  onUpdateVehicle?: (vehicle: Vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  onNavigateToCustomer?: (customerId: string) => void;
  onNavigateToOrder?: (orderId: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [search, setSearch] = useState('');
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    notes: '',
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) setSearch(v.licensePlate);
    } else if (!autoOpen) {
      setSearch('');
    }
  }, [initialVehicleId, vehicles, autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleHistory = (vehicleId: string) => {
    const newExpanded = new Set(expandedHistories);
    if (newExpanded.has(vehicleId)) newExpanded.delete(vehicleId);
    else newExpanded.add(vehicleId);
    setExpandedHistories(newExpanded);
  };

  const filteredVehicles = vehicles.filter(v => 
    v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
    v.make.toLowerCase().includes(search.toLowerCase()) ||
    v.model.toLowerCase().includes(search.toLowerCase())
  );

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
      notes: vehicle.notes || '',
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) onUpdateVehicle({ ...vehicleToUpdate, ...formData });
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = { ...formData, id: `v${Date.now()}`, lastServiceDate: new Date().toISOString().split('T')[0] };
      onAddVehicle(newVehicle);
    }
    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-500 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        {initialVehicleId && search && (
          <button onClick={() => setSearch('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredVehicles.map(v => {
          const owner = customers.find(c => c.id === v.customerId);
          const vehicleServices = services.filter(s => s.vehicleId === v.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const isHistoryExpanded = expandedHistories.has(v.id);

          return (
            <div key={v.id} className={`bg-white rounded-[2rem] border shadow-sm overflow-hidden hover:shadow-xl transition-all group flex flex-col ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
              <div className="flex flex-col md:flex-row">
                <div className="md:w-56 bg-slate-50 p-8 flex flex-col items-center justify-center border-r border-slate-100 group-hover:bg-blue-600 group-hover:text-white transition-all duration-500 shrink-0">
                  <div className="w-24 h-24 rounded-full bg-white flex items-center justify-center shadow-lg mb-6 group-hover:scale-110 transition-transform"><Car className="w-12 h-12 text-slate-900" /></div>
                  <div className="bg-slate-900 text-white font-mono font-bold px-4 py-1.5 rounded-lg text-sm border-2 border-slate-700 shadow-sm group-hover:border-white transition-colors uppercase">{v.licensePlate}</div>
                  <p className="mt-4 text-[10px] font-black uppercase tracking-widest opacity-40 group-hover:opacity-100">Registrační značka</p>
                </div>

                <div className="flex-1 p-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none mb-2">{v.make} {v.model}</h3>
                      <button 
                        onClick={() => owner && onNavigateToCustomer?.(owner.id)}
                        className="text-sm font-bold text-blue-600 hover:text-blue-800 hover:underline transition-all text-left"
                      >
                        Vlastník: {owner ? `${owner.firstName} ${owner.lastName}` : 'Neznámý'}
                      </button>
                    </div>
                    <div className="relative">
                      <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-3 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}><MoreHorizontal className="w-5 h-5" /></button>
                      {openMenuId === v.id && (
                        <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit kartu</button>
                          <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat kartu</button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Calendar className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Expirace STK</p><p className="text-sm font-bold text-slate-900">{v.stkExpirationDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Příští servis</p><p className="text-sm font-bold text-slate-900">{v.nextServiceDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Nájezd km</p><p className="text-sm font-bold text-slate-900">{v.mileage.toLocaleString()}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Kód motoru</p><p className="text-sm font-bold text-slate-900">{v.engineCode || 'N/A'}</p></div></div>
                  </div>

                  {v.notes && (
                    <div className="mb-6 p-4 bg-amber-50 rounded-2xl border border-amber-100 flex gap-3">
                      <StickyNote className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                      <div>
                        <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">Poznámky k vozidlu</p>
                        <p className="text-sm font-medium text-amber-900 leading-relaxed whitespace-pre-wrap">{v.notes}</p>
                      </div>
                    </div>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                    <div className="flex items-center gap-2"><Fingerprint className="w-4 h-4 text-slate-300" /><span className="text-[11px] font-bold text-slate-400 font-mono">VIN: {v.vin}</span></div>
                    <button onClick={() => toggleHistory(v.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-wider transition-all ${isHistoryExpanded ? 'bg-slate-900 text-white' : 'text-blue-600 hover:bg-blue-50'}`}><History className="w-4 h-4" />{isHistoryExpanded ? 'Zavřít historii' : 'Detail historie'}{isHistoryExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}</button>
                  </div>
                </div>
              </div>

              {isHistoryExpanded && (
                <div className="bg-slate-50 border-t border-slate-100 p-8 animate-in slide-in-from-top-4 duration-300">
                  <div className="flex items-center gap-3 mb-6"><History className="w-5 h-5 text-slate-400" /><h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">Kompletní servisní historie</h4></div>
                  {vehicleServices.length > 0 ? (
                    <div className="space-y-4">
                      {vehicleServices.map((service, idx) => (
                        <div key={service.id} className="relative flex gap-6">
                          {idx !== vehicleServices.length - 1 && <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-200"></div>}
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 ${service.status === 'hotovo' ? 'bg-emerald-100 text-emerald-600' : service.status === 'naplánováno' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'}`}>{service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}</div>
                          <div 
                            onClick={() => onNavigateToOrder?.(service.id)}
                            className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all group/item cursor-pointer hover:border-blue-300 hover:shadow-md"
                          >
                            <div>
                              <div className="flex items-center gap-2 mb-1"><span className="text-xs font-black text-slate-900">{service.date}</span><span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-700' : service.status === 'naplánováno' ? 'bg-blue-50 text-blue-700' : 'bg-amber-50 text-amber-700'}`}>{service.status}</span></div>
                              <p className="text-sm font-medium text-slate-600 group-hover/item:text-blue-600 transition-colors">{service.description}</p>
                              <div className="flex items-center gap-2 mt-2"><User className="w-3 h-3 text-slate-400" /><span className="text-[10px] font-bold text-slate-400">Technik: {service.technician}</span></div>
                            </div>
                            <div className="text-right shrink-0 flex items-center gap-4">
                              <p className="text-lg font-black text-slate-900">{service.cost.toLocaleString()} Kč</p>
                              <ChevronRight className="w-4 h-4 text-slate-300 group-hover/item:text-blue-500 group-hover/item:translate-x-1 transition-all" />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : <div className="text-center py-10 bg-white/50 rounded-3xl border-2 border-dashed border-slate-200"><p className="text-slate-400 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p></div>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">Opravdu chcete smazat kartu vozidla <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate})</span>?</p>
              <div className="flex gap-3"><button onClick={() => setDeletingVehicle(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200">ZRUŠIT</button><button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 shadow-lg shadow-red-600/20">SMAZAT</button></div>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
              <div><h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3><p className="text-blue-100 text-xs font-bold uppercase tracking-widest mt-1">{editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}</p></div>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto">
              <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník</label><select required className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}><option value="">Vyberte zákazníka...</option>{customers.map(c => (<option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>))}</select></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value)})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label><input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.engineCode} onChange={e => setFormData({...formData, engineCode: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nájezd km</label><input required type="number" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.mileage} onChange={e => setFormData({...formData, mileage: parseInt(e.target.value)})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Barva</label><input type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.color} onChange={e => setFormData({...formData, color: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Datum expirace STK</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.stkExpirationDate} onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Termín příštího servisu</label><input required type="date" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.nextServiceDate} onChange={e => setFormData({...formData, nextServiceDate: e.target.value})} /></div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Poznámky</label>
                <textarea 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold min-h-[100px] resize-none"
                  value={formData.notes}
                  onChange={e => setFormData({...formData, notes: e.target.value})}
                  placeholder="Zapište důležité informace o vozidle..."
                />
              </div>
              <button type="submit" className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"><Check className="w-5 h-5" />{editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const handleSelectFolder = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setDirectoryHandle(handle);
      onAutoBackupSettingsChange({ ...autoBackupSettings, folderName: handle.name });
    } catch (err) {
      console.error("Folder picker cancelled or failed", err);
    }
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => {
    onDiscountLevelsChange(discountLevels.filter(d => d !== val));
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const addTemplate = () => {
    onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  };

  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => {
    onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.0">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      if (v.notes) xml += xmlTag('Notes', v.notes);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const importedData: any = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id"),
            firstName: node.querySelector("FirstName")?.textContent,
            lastName: node.querySelector("LastName")?.textContent,
            email: node.querySelector("Email")?.textContent,
            phone: node.querySelector("Phone")?.textContent,
            address: node.querySelector("Address")?.textContent,
            createdAt: node.querySelector("CreatedAt")?.textContent,
            companyName: node.querySelector("CompanyName")?.textContent,
            companyAddress: node.querySelector("CompanyAddress")?.textContent,
            ico: node.querySelector("ICO")?.textContent,
            dic: node.querySelector("DIC")?.textContent,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id"),
            customerId: node.getAttribute("customerId"),
            make: node.querySelector("Make")?.textContent,
            model: node.querySelector("Model")?.textContent,
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent,
            licensePlate: node.querySelector("LicensePlate")?.textContent,
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent,
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent,
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent,
            notes: node.querySelector("Notes")?.textContent || undefined,
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => ({
            id: node.getAttribute("id"),
            vehicleId: node.getAttribute("vehicleId"),
            date: node.querySelector("Date")?.textContent,
            description: node.querySelector("Description")?.textContent,
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            technician: node.querySelector("Technician")?.textContent,
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: Array.from(node.querySelectorAll("Part")).map(p => ({
              id: p.getAttribute("id"),
              description: p.querySelector("Description")?.textContent,
              quantity: parseFloat(p.querySelector("Quantity")?.textContent || "0"),
              unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
            }))
          })),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id"),
            orderId: node.getAttribute("orderId"),
            issueDate: node.querySelector("IssueDate")?.textContent,
            dueDate: node.querySelector("DueDate")?.textContent,
            customerId: node.querySelector("CustomerId")?.textContent,
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent,
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            paymentType: node.querySelector("PaymentType")?.textContent,
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id"),
              name: node.querySelector("Name")?.textContent,
              price: parseInt(node.querySelector("Price")?.textContent || "0")
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id"),
              label: node.querySelector("Label")?.textContent,
              description: node.querySelector("Description")?.textContent
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button onClick={handleSave} className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}>
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-fit rounded-2xl">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'invoicing', label: 'Fakturace', icon: Percent },
          { id: 'team', label: 'Tým', icon: User },
          { id: 'services', label: 'Ceník', icon: DollarSign },
          { id: 'templates', label: 'Šablony', icon: Layout },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
            <tab.icon className="w-4 h-4" /> {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                    <Building className="w-8 h-8 text-blue-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Firemní údaje</h3>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Základní identifikace firmy</p>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název servisu</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Fakturační adresa</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                  <input type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Oficiální Email</label>
                  <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'invoicing' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center">
                    <Percent className="w-8 h-8 text-red-600" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-slate-900">Fakturační nastavení</h3>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Správa slev a výchozích hodnot</p>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Stupně slev (%)</label>
                <div className="flex flex-wrap gap-3">
                  {discountLevels.map(level => (
                    <div key={level} className="flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 group">
                      <span className="font-bold text-slate-900">{level}%</span>
                      <button 
                        onClick={() => removeDiscountLevel(level)}
                        className="p-1 text-slate-300 hover:text-red-500 transition-colors"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                  <div className="flex gap-2">
                    <input 
                      type="number" 
                      placeholder="%"
                      className="w-16 px-3 py-2 bg-slate-50 border-2 border-transparent focus:border-red-500 rounded-xl outline-none font-bold text-center"
                      value={newDiscount}
                      onChange={e => setNewDiscount(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && addDiscountLevel()}
                    />
                    <button 
                      onClick={addDiscountLevel}
                      className="p-2 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors"
                    >
                      <Plus className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'team' && (
          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center">
                <User className="w-8 h-8 text-blue-600" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900">Správa týmu</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Seznam mechaniků pro zakázky</p>
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex gap-4 p-4 bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <input 
