                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Příští servis</p><p className="text-sm font-bold text-slate-900">{v.nextServiceDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Nájezd km</p><p className="text-sm font-bold text-slate-900">{v.mileage.toLocaleString()}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3"><div className="p-2 bg-white rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Kód motoru</p><p className="text-sm font-bold text-slate-900">{v.engineCode || 'N/A'}</p></div></div>
                  </div>

                  {v.notes && (
                    <div className="mb-6 p-4 bg-amber-50 rounded-2xl border border-amber-100 flex gap-3">
                      <StickyNote className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
