              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Kontakt</p>
                  <p className="text-sm font-bold text-slate-100">{selectedDetailCustomer.firstName} {selectedDetailCustomer.lastName}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Email</p>
                  <p className="text-sm font-bold text-slate-100">{selectedDetailCustomer.email}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Telefon</p>
                  <p className="text-sm font-bold text-slate-100">{selectedDetailCustomer.phone}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Adresa</p>
                  <p className="text-sm font-bold text-slate-100">{selectedDetailCustomer.address || 'Neuvedeno'}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedDetailCustomer(null)}
                className="w-full bg-slate-100 text-slate-950 font-black py-4 rounded-2xl transition-all"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* New / Edit Customer Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl border border-slate-800 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-950 p-8 text-white flex justify-between items-center border-b border-slate-800">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingCustomer ? 'Upravit zákazníka' : 'Nový zákazník'}</h3>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">
                  {editingCustomer ? `Editace ID ${editingCustomer.id}` : 'Registrace do systému'}
                </p>
              </div>
              <button onClick={() => setIsAddModalOpen(false)} className="p-2 hover:bg-slate-800 rounded-xl transition-colors">
                <X className="w-6 h-6 text-slate-500" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800 pb-2">Osobní údaje</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Jméno *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100"
                      value={formData.firstName}
                      onChange={e => setFormData({...formData, firstName: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Příjmení *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100"
                      value={formData.lastName}
                      onChange={e => setFormData({...formData, lastName: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800 pb-2">Firemní údaje (volitelné)</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Název firmy</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-800 border-2 border-transparent focus:border-slate-100 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100"
                      value={formData.companyName}
                      onChange={e => setFormData({...formData, companyName: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800 pb-2">Kontaktní údaje</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Email *</label>
                    <input 
                      required
                      type="email" 
                      className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100"
                      value={formData.email}
                      onChange={e => setFormData({...formData, email: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Telefon *</label>
                    <input 
                      required
                      type="tel" 
                      className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100"
                      value={formData.phone}
                      onChange={e => setFormData({...formData, phone: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingCustomer ? 'ULOŽIT ZMĚNY' : 'ULOŽIT ZÁKAZNÍKA'}
