            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerManager;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Car, 
  Fingerprint, 
  Calendar, 
  Gauge, 
  ChevronRight, 
  ChevronDown,
  Cpu, 
  Plus, 
  X, 
  Check, 
  User,
  History,
  CheckCircle2,
  Clock3,
  AlertTriangle,
  Stethoscope,
  Search,
  Edit3,
  MoreHorizontal,
  Trash2,
  AlertCircle,
  StickyNote
} from 'lucide-react';
import { Vehicle, Customer, ServiceRecord } from '../types';

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle: Vehicle) => void;
  onUpdateVehicle?: (vehicle: Vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  onNavigateToCustomer?: (customerId: string) => void;
  onNavigateToOrder?: (orderId: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    notes: '',
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleHistory = (vehicleId: string) => {
    const newExpanded = new Set(expandedHistories);
    if (newExpanded.has(vehicleId)) newExpanded.delete(vehicleId);
    else newExpanded.add(vehicleId);
    setExpandedHistories(newExpanded);
  };

  const filteredVehicles = vehicles.filter(v => 
    v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
    v.make.toLowerCase().includes(search.toLowerCase()) ||
    v.model.toLowerCase().includes(search.toLowerCase())
  );

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
      notes: vehicle.notes || '',
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) onUpdateVehicle({ ...vehicleToUpdate, ...formData });
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = { ...formData, id: `v${Date.now()}`, lastServiceDate: new Date().toISOString().split('T')[0] };
      onAddVehicle(newVehicle);
    }
    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-100 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-400 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-900/40"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-slate-900 p-4 rounded-2xl border border-slate-800 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-500" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent text-slate-100 placeholder-slate-500"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-400 font-bold text-xs px-3 py-1 hover:bg-slate-800 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredVehicles.map(v => {
          const owner = customers.find(c => c.id === v.customerId);
          const vehicleServices = services.filter(s => s.vehicleId === v.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const isHistoryExpanded = expandedHistories.has(v.id);

          return (
            <div key={v.id} className={`bg-slate-900 rounded-[2rem] border shadow-sm overflow-hidden hover:shadow-2xl transition-all group flex flex-col ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-800'}`}>
              <div className="flex flex-col md:flex-row">
                <div className="md:w-56 bg-slate-950 p-8 flex flex-col items-center justify-center border-r border-slate-800 group-hover:bg-blue-600 group-hover:text-white transition-all duration-500 shrink-0">
                  <div className="w-24 h-24 rounded-full bg-slate-900 flex items-center justify-center shadow-2xl mb-6 group-hover:scale-110 transition-transform group-hover:bg-white/10">
                    <Car className="w-12 h-12 text-slate-400 group-hover:text-white" />
                  </div>
                  <div className="bg-slate-800 text-slate-100 font-mono font-bold px-4 py-1.5 rounded-lg text-sm border-2 border-slate-700 shadow-sm group-hover:border-white transition-colors uppercase">{v.licensePlate}</div>
                  <p className="mt-4 text-[10px] font-black uppercase tracking-widest opacity-40 group-hover:opacity-100">Registrační značka</p>
                </div>

                <div className="flex-1 p-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-2xl font-black text-slate-100 tracking-tight leading-none mb-2">{v.make} {v.model}</h3>
                      <button 
                        onClick={() => owner && onNavigateToCustomer?.(owner.id)}
                        className="text-sm font-bold text-blue-400 hover:text-blue-300 hover:underline transition-all text-left"
                      >
                        Vlastník: {owner ? `${owner.firstName} ${owner.lastName}` : 'Neznámý'}
                      </button>
                    </div>
                    <div className="relative">
                      <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-3 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-800 text-slate-100' : 'bg-slate-800/50 text-slate-500 hover:text-blue-400 hover:bg-slate-800'}`}><MoreHorizontal className="w-5 h-5" /></button>
                      {openMenuId === v.id && (
                        <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-slate-800 rounded-2xl shadow-2xl border border-slate-700 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-700 text-slate-200 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit kartu</button>
                          <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-950 text-red-400 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat kartu</button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                    <div className="bg-slate-800/50 p-3 rounded-2xl flex items-center gap-3 border border-slate-800/50"><div className="p-2 bg-slate-900 rounded-xl shadow-sm"><Calendar className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Expirace STK</p><p className="text-sm font-bold text-slate-100">{v.stkExpirationDate}</p></div></div>
                    <div className="bg-slate-800/50 p-3 rounded-2xl flex items-center gap-3 border border-slate-800/50"><div className="p-2 bg-slate-900 rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Příští servis</p><p className="text-sm font-bold text-slate-100">{v.nextServiceDate}</p></div></div>
                    <div className="bg-slate-800/50 p-3 rounded-2xl flex items-center gap-3 border border-slate-800/50"><div className="p-2 bg-slate-900 rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Nájezd km</p><p className="text-sm font-bold text-slate-100">{v.mileage.toLocaleString()}</p></div></div>
                    <div className="bg-slate-800/50 p-3 rounded-2xl flex items-center gap-3 border border-slate-800/50"><div className="p-2 bg-slate-900 rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-500" /></div><div><p className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Kód motoru</p><p className="text-sm font-bold text-slate-100">{v.engineCode || 'N/A'}</p></div></div>
                  </div>

                  {v.notes && (
                    <div className="mb-6 p-4 bg-amber-950/20 rounded-2xl border border-amber-900/30 flex gap-3">
                      <StickyNote className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                      <div>
                        <p className="text-[10px] font-black text-amber-500 uppercase tracking-widest mb-1">Poznámky k vozidlu</p>
                        <p className="text-sm font-medium text-amber-100/70 leading-relaxed whitespace-pre-wrap">{v.notes}</p>
                      </div>
                    </div>
