                  <div className="flex items-center justify-between pt-6 border-t border-slate-800">
                    <div className="flex items-center gap-2"><Fingerprint className="w-4 h-4 text-slate-600" /><span className="text-[11px] font-bold text-slate-500 font-mono">VIN: {v.vin}</span></div>
                    <button onClick={() => toggleHistory(v.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-wider transition-all ${isHistoryExpanded ? 'bg-slate-100 text-slate-950' : 'text-blue-400 hover:bg-slate-800'}`}><History className="w-4 h-4" />{isHistoryExpanded ? 'Zavřít historii' : 'Detail historie'}{isHistoryExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}</button>
                  </div>
                </div>
              </div>

              {isHistoryExpanded && (
                <div className="bg-slate-950 border-t border-slate-800 p-8 animate-in slide-in-from-top-4 duration-300">
                  <div className="flex items-center gap-3 mb-6"><History className="w-5 h-5 text-slate-600" /><h4 className="text-sm font-black text-slate-300 uppercase tracking-widest">Kompletní servisní historie</h4></div>
                  {vehicleServices.length > 0 ? (
                    <div className="space-y-4">
                      {vehicleServices.map((service, idx) => (
                        <div key={service.id} className="relative flex gap-6">
                          {idx !== vehicleServices.length - 1 && <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-800"></div>}
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 border border-slate-800 ${service.status === 'hotovo' ? 'bg-emerald-950 text-emerald-400' : service.status === 'naplánováno' ? 'bg-blue-950 text-blue-400' : 'bg-amber-950 text-amber-400'}`}>{service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}</div>
                          <div 
                            onClick={() => onNavigateToOrder?.(service.id)}
                            className="bg-slate-900 p-5 rounded-2xl shadow-sm border border-slate-800 flex-1 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all group/item cursor-pointer hover:border-slate-700 hover:bg-slate-800"
                          >
                            <div>
                              <div className="flex items-center gap-2 mb-1"><span className="text-xs font-black text-slate-100">{service.date}</span><span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${service.status === 'hotovo' ? 'bg-emerald-950 text-emerald-400 border border-emerald-900/30' : service.status === 'naplánováno' ? 'bg-blue-950 text-blue-400 border border-blue-900/30' : 'bg-amber-950 text-amber-400 border border-amber-900/30'}`}>{service.status}</span></div>
                              <p className="text-sm font-medium text-slate-400 group-hover/item:text-blue-400 transition-colors">{service.description}</p>
                            </div>
                            <div className="text-right shrink-0 flex items-center gap-4">
                              <p className="text-lg font-black text-slate-100">{service.cost.toLocaleString()} Kč</p>
                              <ChevronRight className="w-4 h-4 text-slate-600 group-hover/item:text-blue-400 group-hover/item:translate-x-1 transition-all" />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : <div className="text-center py-10 bg-slate-900 rounded-3xl border-2 border-dashed border-slate-800"><p className="text-slate-500 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p></div>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl border border-slate-800 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-950 p-8 text-white flex justify-between items-center border-b border-slate-800">
              <div><h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3><p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">{editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}</p></div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-500 hover:text-white"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Vlastník</label><select required className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}><option value="">Vyberte zákazníka...</option>{customers.map(c => (<option key={c.id} value={c.id} className="bg-slate-800">{c.firstName} {c.lastName}</option>))}</select></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Značka</label><input required type="text" className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Model</label><input required type="text" className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">SPZ</label><input required type="text" className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase text-slate-100" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">VIN</label><input required type="text" className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase text-slate-100" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} /></div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Poznámky</label>
                <textarea 
                  className="w-full bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold text-slate-100 min-h-[100px] resize-none"
                  value={formData.notes}
                  onChange={e => setFormData({...formData, notes: e.target.value})}
                  placeholder="Zapište důležité informace o vozidle..."
                />
              </div>
              <button type="submit" className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"><Check className="w-5 h-5" />{editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { 
  AlertCircle, 
  Plus, 
  Car, 
  Wrench, 
  ShieldAlert, 
  UserPlus,
  ClipboardPlus,
  Clock,
  ChevronRight,
  ClipboardList
} from 'lucide-react';
import { Customer, Vehicle, ServiceRecord, AppView, NotificationSettings } from '../types';

interface DashboardProps {
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onNavigate: (view: AppView, autoOpen?: boolean) => void;
  onViewVehicle: (vehicleId: string) => void;
  onViewOrder: (orderId: string) => void;
  notifSettings: NotificationSettings;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onNavigate, 
  onViewVehicle, 
  onViewOrder,
  notifSettings 
}) => {
  const [isQuickActionOpen, setIsQuickActionOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsQuickActionOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const vehicleAlerts = useMemo(() => {
    const alerts: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();
    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);
      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      if (diffStk >= 0 && diffStk <= notifSettings.stkThresholdDays) {
        alerts.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      }
      if (diffService >= 0 && diffService <= notifSettings.serviceThresholdDays) {
        alerts.push({ type: 'service', vehicle: v, daysLeft: diffService });
      }
    });
    return alerts.sort((a, b) => a.daysLeft - b.daysLeft);
  }, [vehicles, notifSettings]);

  const activeOrders = useMemo(() => {
    return services.filter(s => s.status === 'naplánováno' || s.status === 'probíhá')
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [services]);

  const quickActions = [
    { label: 'Nový zákazník', icon: UserPlus, view: 'customers' as AppView, desc: 'Registrace nového klienta' },
    { label: 'Nové vozidlo', icon: Car, view: 'vehicles' as AppView, desc: 'Evidence nového vozu' },
    { label: 'Nová zakázka', icon: ClipboardPlus, view: 'orders' as AppView, desc: 'Založení servisního listu' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-100 tracking-tight">Přehled servisu</h2>
          <p className="text-slate-400 font-medium">AutoService Pro v tmavém režimu.</p>
        </div>

        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={() => setIsQuickActionOpen(!isQuickActionOpen)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-blue-600/30 hover:bg-blue-700 hover:-translate-y-0.5 transition-all flex items-center gap-3"
          >
            <Plus className={`w-6 h-6 transition-transform duration-300 ${isQuickActionOpen ? 'rotate-45' : ''}`} />
            Rychlá akce
          </button>
          {isQuickActionOpen && (
            <div className="absolute top-20 right-0 w-72 bg-slate-900 rounded-[2rem] shadow-2xl border border-slate-800 p-4 z-50 animate-in fade-in zoom-in-95 duration-200">
              <div className="space-y-2">
                {quickActions.map((action, idx) => (
                  <button
                    key={idx}
                    onClick={() => { onNavigate(action.view, true); setIsQuickActionOpen(false); }}
                    className="w-full flex items-center gap-4 p-4 rounded-2xl hover:bg-slate-800 transition-colors group text-left"
                  >
                    <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-blue-400 group-hover:bg-blue-600 group-hover:text-white transition-all">
                      <action.icon className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-sm font-black text-slate-100">{action.label}</p>
                      <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">{action.desc}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white border border-slate-800 relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-red-500/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
          <div className="relative z-10 flex flex-col h-full">
            <div className="flex items-center gap-3 mb-8 text-amber-500 shrink-0">
              <AlertCircle className="w-6 h-6" />
              <h3 className="text-2xl font-black tracking-tight text-slate-100">Důležitá upozornění</h3>
            </div>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar relative">
              {vehicleAlerts.length > 0 ? vehicleAlerts.map((alert, idx) => (
                <div key={idx} className={`p-6 rounded-3xl border transition-all hover:scale-[1.02] cursor-pointer ${alert.type === 'stk' ? 'bg-red-950/20 border-red-900/30 text-red-200 hover:bg-red-900/30' : 'bg-blue-950/20 border-blue-900/30 text-blue-200 hover:bg-blue-900/30'}`} onClick={() => onViewVehicle(alert.vehicle.id)}>
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-2">{alert.type === 'stk' ? <ShieldAlert className="w-4 h-4" /> : <Wrench className="w-4 h-4" />}<span className="text-[10px] font-black uppercase tracking-widest">{alert.type === 'stk' ? 'Expirace STK' : 'Plánovaný servis'}</span></div>
                    <span className={`text-[11px] font-black px-2 py-0.5 rounded-full ${alert.daysLeft <= 5 ? 'bg-red-600 text-white shadow-lg' : 'bg-white/10 text-white'}`}>Zbývá {alert.daysLeft} dní</span>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center shrink-0"><Car className="w-6 h-6" /></div>
                    <div><p className="text-base font-black tracking-tight">{alert.vehicle.make} {alert.vehicle.model}</p><p className="text-xs font-bold font-mono opacity-50">{alert.vehicle.licensePlate}</p></div>
                  </div>
                </div>
              )) : (
                <div className="h-full bg-slate-950/50 p-10 rounded-[2rem] border border-slate-800 text-center flex flex-col items-center justify-center">
                  <ShieldAlert className="w-12 h-12 text-slate-700 mb-4" /><p className="text-slate-500 font-bold italic">Žádná upozornění podle nastavení.</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl text-white border border-slate-800 relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
          <div className="relative z-10 flex flex-col h-full">
            <div className="flex items-center gap-3 mb-8 text-blue-400 shrink-0">
              <ClipboardList className="w-6 h-6" />
              <h3 className="text-2xl font-black tracking-tight text-slate-100">Aktivní zakázky</h3>
            </div>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar relative">
              {activeOrders.length > 0 ? activeOrders.map((order) => {
                const vehicle = vehicles.find(v => v.id === order.vehicleId);
                return (
                  <div key={order.id} className="p-6 rounded-3xl border border-blue-900/30 bg-blue-950/20 text-blue-100 transition-all hover:scale-[1.02] hover:bg-blue-900/30 cursor-pointer" onClick={() => onViewOrder(order.id)}>
                    <div className="flex justify-between items-start mb-4">
                      <div className="flex items-center gap-2"><Clock className="w-4 h-4" /><span className="text-[10px] font-black uppercase tracking-widest">{order.status}</span></div>
                      <span className="text-[11px] font-black px-2 py-0.5 rounded-full bg-white/10 text-white">{order.date}</span>
                    </div>
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center shrink-0 text-blue-300"><Car className="w-6 h-6" /></div>
                        <div>
                          <p className="text-base font-black tracking-tight truncate max-w-[150px]">{vehicle ? `${vehicle.make} ${vehicle.model}` : 'Neznámý vůz'}</p>
                          <p className="text-xs font-bold text-blue-400/60 truncate max-w-[200px]">{order.description}</p>
                        </div>
                      </div>
                      <ChevronRight className="w-5 h-5 text-blue-500/50 shrink-0" />
                    </div>
                  </div>
                );
              }) : (
                <div className="h-full bg-slate-950/50 p-10 rounded-[2rem] border border-slate-800 text-center flex flex-col items-center justify-center">
                  <ClipboardList className="w-12 h-12 text-slate-700 mb-4" /><p className="text-slate-500 font-bold italic">Žádné aktivní zakázky.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Wrench, Lock, User, LogIn, AlertCircle } from 'lucide-react';
import { UserSettings } from '../types';

interface LoginProps {
  settings: UserSettings;
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ settings, onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === settings.username && password === settings.password) {
      onLogin();
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 text-slate-100">
      <div className="w-full max-w-md animate-in fade-in zoom-in-95 duration-700">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center p-4 bg-blue-600 rounded-[2rem] shadow-2xl shadow-blue-900/40 mb-6">
            <Wrench className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-3xl font-black tracking-tight text-white">
            AutoService <span className="text-blue-400">Pro</span>
          </h1>
          <p className="text-slate-500 font-bold uppercase text-[10px] tracking-[0.2em] mt-2">Interní systém servisu</p>
        </div>

        <div className="bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-800 p-10 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>

          <form onSubmit={handleSubmit} className="space-y-6 relative z-10">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Uživatelské jméno</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-600" />
                <input 
                  type="text" 
                  autoFocus
                  className="w-full pl-12 pr-4 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold transition-all text-white placeholder-slate-600"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="admin"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Heslo</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-600" />
                <input 
                  type="password" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold transition-all text-white placeholder-slate-600"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-950/30 border border-red-900/50 p-4 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                <AlertCircle className="w-5 h-5 text-red-500" />
                <p className="text-xs font-bold text-red-400">Nesprávné přihlašovací údaje!</p>
              </div>
            )}

            <button 
              type="submit"
              className="w-full bg-blue-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-blue-900/20 hover:bg-blue-700 transition-all flex items-center justify-center gap-3 mt-4"
            >
              <LogIn className="w-5 h-5" />
              PŘIHLÁSIT SE
            </button>
          </form>
        </div>

        <p className="text-center mt-10 text-[10px] font-black text-slate-600 uppercase tracking-[0.2em]">
          &copy; {new Date().getFullYear()} AutoService Pro DB System
        </p>
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake {
          animation: shake 0.2s ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default Login;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const handleSelectFolder = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setDirectoryHandle(handle);
      onAutoBackupSettingsChange({ ...autoBackupSettings, folderName: handle.name });
    } catch (err) {
      console.error("Folder picker cancelled or failed", err);
    }
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => {
    onDiscountLevelsChange(discountLevels.filter(d => d !== val));
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0 }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const addTemplate = () => {
    onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  };

  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => {
    onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  const xmlTag = (name: string, value: any) => `    <${name}>${value !== undefined && value !== null ? String(value).replace(/[<>&"']/g, (c) => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":"&apos;"}[c] || c)) : ''}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="2.0">\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${c.id}">\n`;
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${v.id}" customerId="${v.customerId}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      if (v.notes) xml += xmlTag('Notes', v.notes);
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${s.id}" vehicleId="${s.vehicleId}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      if (s.parts) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${p.id}">\n`;
          xml += xmlTag('Description', p.description);
          xml += xmlTag('Quantity', p.quantity);
          xml += xmlTag('UnitPrice', p.unitPrice);
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${inv.id}" orderId="${inv.orderId}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${fs.id}">\n`;
      xml += xmlTag('Name', fs.name);
      xml += xmlTag('Price', fs.price);
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${pt.id}">\n`;
      xml += xmlTag('Label', pt.label);
      xml += xmlTag('Description', pt.description);
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${t}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { setBackupStatus('error'); }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const importedData: any = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id"),
            firstName: node.querySelector("FirstName")?.textContent,
            lastName: node.querySelector("LastName")?.textContent,
            email: node.querySelector("Email")?.textContent,
            phone: node.querySelector("Phone")?.textContent,
            address: node.querySelector("Address")?.textContent,
            createdAt: node.querySelector("CreatedAt")?.textContent,
            companyName: node.querySelector("CompanyName")?.textContent,
            companyAddress: node.querySelector("CompanyAddress")?.textContent,
            ico: node.querySelector("ICO")?.textContent,
            dic: node.querySelector("DIC")?.textContent,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id"),
            customerId: node.getAttribute("customerId"),
            make: node.querySelector("Make")?.textContent,
            model: node.querySelector("Model")?.textContent,
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent,
            licensePlate: node.querySelector("LicensePlate")?.textContent,
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent,
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent,
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent,
            notes: node.querySelector("Notes")?.textContent || undefined,
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => ({
            id: node.getAttribute("id"),
            vehicleId: node.getAttribute("vehicleId"),
            date: node.querySelector("Date")?.textContent,
            description: node.querySelector("Description")?.textContent,
            cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            technician: node.querySelector("Technician")?.textContent,
            laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
            parts: Array.from(node.querySelectorAll("Part")).map(p => ({
              id: p.getAttribute("id"),
              description: p.querySelector("Description")?.textContent,
              quantity: parseFloat(p.querySelector("Quantity")?.textContent || "0"),
              unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
            }))
          })),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id"),
            orderId: node.getAttribute("orderId"),
            issueDate: node.querySelector("IssueDate")?.textContent,
            dueDate: node.querySelector("DueDate")?.textContent,
            customerId: node.querySelector("CustomerId")?.textContent,
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent,
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent,
            paymentType: node.querySelector("PaymentType")?.textContent,
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id"),
              name: node.querySelector("Name")?.textContent,
              price: parseInt(node.querySelector("Price")?.textContent || "0")
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id"),
              label: node.querySelector("Label")?.textContent,
              description: node.querySelector("Description")?.textContent
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-white tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
        <button onClick={handleSave} className={`px-8 py-4 rounded-2xl font-black text-xs transition-all flex items-center gap-3 shadow-xl ${saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-900/40'}`}>
          {saveStatus === 'saving' ? <Loader2 className="w-4 h-4 animate-spin" /> : saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
          {saveStatus === 'saving' ? 'UKLÁDÁM...' : saveStatus === 'saved' ? 'ULOŽENO' : 'ULOŽIT VŠE'}
        </button>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-900/50 w-fit rounded-2xl border border-slate-800">
        {[
          { id: 'company', label: 'Moje Firma', icon: Building },
          { id: 'invoicing', label: 'Fakturace', icon: Percent },
          { id: 'team', label: 'Tým', icon: User },
          { id: 'services', label: 'Ceník', icon: DollarSign },
          { id: 'templates', label: 'Šablony', icon: Layout },
          { id: 'notifications', label: 'Upozornění', icon: Bell },
          { id: 'backups', label: 'Zálohování', icon: Database }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-slate-800 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
            <tab.icon className="w-4 h-4" /> {tab.label}
          </button>
        ))}
      </div>

      <div className="max-w-5xl">
        {activeTab === 'company' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-950 rounded-2xl flex items-center justify-center border border-blue-900/30">
                    <Building className="w-8 h-8 text-blue-400" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-white">Firemní údaje</h3>
                    <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">Základní identifikace firmy</p>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Název servisu</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Fakturační adresa</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">IČO</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.ico} onChange={e => onCompanyChange({...companyInfo, ico: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">DIČ</label>
                  <input type="text" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.dic} onChange={e => onCompanyChange({...companyInfo, dic: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Telefonní kontakt</label>
                  <input type="tel" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.phone} onChange={e => onCompanyChange({...companyInfo, phone: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Oficiální Email</label>
                  <input type="email" className="w-full px-5 py-4 bg-slate-800 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold text-white" value={companyInfo.email} onChange={e => onCompanyChange({...companyInfo, email: e.target.value})} />
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'invoicing' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-left-4">
            <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 shadow-sm p-10 space-y-8">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-red-950 rounded-2xl flex items-center justify-center border border-red-900/30">
                    <Percent className="w-8 h-8 text-red-500" />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-white">Fakturační nastavení</h3>
                    <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">Správa slev a výchozích hodnot</p>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Stupně slev (%)</label>
                <div className="flex flex-wrap gap-3">
                  {discountLevels.map(level => (
                    <div key={level} className="flex items-center gap-2 bg-slate-800 px-4 py-2 rounded-xl border border-slate-700 group">
                      <span className="font-bold text-white">{level}%</span>
                      <button 
                        onClick={() => removeDiscountLevel(level)}
                        className="p-1 text-slate-500 hover:text-red-500 transition-colors"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                  <div className="flex gap-2">
                    <input 
                      type="number" 
                      placeholder="%"
                      className="w-16 px-3 py-2 bg-slate-800 border-2 border-transparent focus:border-red-500 rounded-xl outline-none font-bold text-center text-white"
                      value={newDiscount}
                      onChange={e => setNewDiscount(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && addDiscountLevel()}
                    />
                    <button 
                      onClick={addDiscountLevel}
                      className="p-2 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors shadow-lg shadow-red-900/20"
                    >
                      <Plus className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'team' && (
          <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 shadow-sm p-10 space-y-8 animate-in fade-in slide-in-from-left-4">
