            min-height: 297mm !important;
            margin: 0 !important;
            padding: 10mm 15mm !important;
            box-sizing: border-box !important;
            background: white !important;
            color: black !important;
            font-family: 'Inter', sans-serif !important;
          }
          .print-block-invoice * {
            visibility: visible !important;
          }
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; border-radius: 10px; }
      `}</style>
    </div>
  );
};

const InvoiceCard: React.FC<{ 
  inv: Invoice, 
  customers: Customer[], 
  today: string, 
  onSelect: (i: Invoice) => void, 
  onDelete: (i: Invoice) => void 
}> = ({ inv, customers, today, onSelect, onDelete }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;

  return (
    <div className={`bg-slate-900 rounded-[2rem] border p-6 shadow-sm hover:shadow-2xl transition-all group relative ${isOverdue ? 'border-red-900/50 bg-red-950/10' : 'border-slate-800'}`}>
      <div className="flex items-center justify-between mb-4">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center border ${inv.status === 'uhrazeno' ? 'bg-emerald-950 text-emerald-400 border-emerald-900/30' : isOverdue ? 'bg-red-950 text-red-500 border-red-900/30' : 'bg-blue-950 text-blue-400 border-blue-900/30'}`}>
          <Receipt className="w-5 h-5" />
        </div>
        <div className="flex items-center gap-2">
          {isOverdue && (
            <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-600 text-white text-[9px] font-black uppercase animate-pulse">
              <span className="w-1.5 h-1.5 rounded-full bg-white"></span>
