            </div>
          )}
          {inv.discount && inv.discount > 0 && (
            <span className="text-[9px] font-black uppercase px-2 py-1 rounded-lg bg-slate-800 text-slate-400 border border-slate-700">
              Sleva {inv.discount}%
            </span>
          )}
        </div>
      </div>

      <div className="mb-4">
        <h3 className="text-lg font-black text-white leading-none">{inv.id}</h3>
        <p className="text-[10px] font-bold text-blue-400 mt-1 uppercase tracking-tight">{inv.vehicleInfo}</p>
