        <p className="text-sm font-bold text-slate-300 truncate">{customer?.companyName || `${customer?.firstName} ${customer?.lastName}`}</p>
        <div className="flex items-center gap-2 text-[10px] text-slate-500 font-medium">
          {inv.paymentType === 'Hotově' ? <Wallet className="w-3 h-3" /> : <CreditCard className="w-3 h-3" />}
          <span className={isOverdue ? 'text-red-500 font-bold' : ''}>Splatnost: {inv.dueDate}</span>
        </div>
      </div>

      <div className="flex items-end justify-between pt-4 border-t border-slate-800">
        <div>
          <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Částka</p>
          <p className={`text-xl font-black ${isOverdue ? 'text-red-500' : 'text-white'}`}>{inv.totalInclDph.toLocaleString()} Kč</p>
        </div>
        <div className="flex gap-1.5">
           <button 
            onClick={() => onSelect(inv)}
            className="p-2.5 bg-slate-800 text-white rounded-xl hover:bg-blue-600 transition-all border border-slate-700 shadow-lg"
           >
             <Printer className="w-4 h-4" />
           </button>
           <button 
            onClick={() => onDelete(inv)}
            className="p-2.5 bg-red-950/30 text-red-500 rounded-xl hover:bg-red-600 hover:text-white transition-all border border-red-900/30"
           >
             <Trash2 className="w-4 h-4" />
           </button>
        </div>
      </div>
    </div>
  );
};

