    setInvoices(prev => prev.map(inv => inv.id === updatedInvoice.id ? updatedInvoice : inv));
  };

  const handleCreateInvoiceFromOrder = (orderId: string) => {
    const order = services.find(s => s.id === orderId);
    if (!order) return;

    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    if (!vehicle) return;

    const existingInvoice = invoices.find(inv => inv.orderId === orderId);
    if (existingInvoice) {
      setActiveView('invoices');
      return;
    }

    const items: PartItem[] = [
      ...(order.parts || []),
      { 
        id: `labor-${Date.now()}`, 
        description: `Servisní práce (${order.laborHours || 0} h)`, 
        quantity: order.laborHours || 0, 
        unit: 'h', 
        unitPrice: hourlyRate 
      }
    ];

    const issueDate = new Date();
    const year = issueDate.getFullYear().toString().slice(-2);
    const month = (issueDate.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyInvoices = invoices.filter(inv => inv.id.startsWith(prefix));
    const nextSequence = (monthlyInvoices.length + 1).toString().padStart(3, '0');
    const invoiceId = `${prefix}${nextSequence}`;

    const dueDate = new Date();
    dueDate.setDate(issueDate.getDate() + 14);

    const newInvoice: Invoice = {
      id: invoiceId,
      orderId: order.id,
      issueDate: issueDate.toISOString().split('T')[0],
      dueDate: dueDate.toISOString().split('T')[0],
      customerId: vehicle.customerId,
      vehicleInfo: `${vehicle.make} ${vehicle.model} (${vehicle.licensePlate})`,
      items: items,
      totalExclDph: order.cost,
      totalInclDph: Math.round(order.cost * 1.21),
      paymentType: 'Převodem',
      status: 'neuhrazeno',
      discount: 0
    };

    setInvoices([newInvoice, ...invoices]);
    resetAllSearches();
    setActiveView('invoices');
  };

  const resetAllSearches = () => {
    setCustomerSearch('');
    setVehicleSearch('');
    setOrderSearch('');
    setInvoiceSearch('');
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    resetAllSearches();
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (fullState: any) => {
    if (fullState.customers) setCustomers(fullState.customers);
    if (fullState.vehicles) setVehicles(fullState.vehicles);
    if (fullState.services) setServices(fullState.services);
    if (fullState.invoices) setInvoices(fullState.invoices);

    if (fullState.settings) {
      if (fullState.settings.hourlyRate !== undefined) setHourlyRate(fullState.settings.hourlyRate);
      if (fullState.settings.fixedServices) setFixedServices(fullState.settings.fixedServices);
      if (fullState.settings.predefinedTasks) setPredefinedTasks(fullState.settings.predefinedTasks);
      if (fullState.settings.technicians) setTechnicians(fullState.settings.technicians);
      if (fullState.settings.discountLevels) setDiscountLevels(fullState.settings.discountLevels);
    }
  };

  const handleNavigateToVehicle = (vId: string) => { 
    resetAllSearches();
    const v = vehicles.find(item => item.id === vId);
    if (v) setVehicleSearch(v.licensePlate);
    setTargetVehicleId(vId); 
    setActiveView('vehicles'); 
  };

  const handleNavigateToOrder = (oId: string) => { 
    resetAllSearches();
    const o = services.find(item => item.id === oId);
    if (o) setOrderSearch(o.id);
    setTargetOrderId(oId); 
    setActiveView('orders'); 
  };

  const handleNavigateToCustomer = (cId: string) => { 
    resetAllSearches();
    const c = customers.find(item => item.id === cId);
    if (c) setCustomerSearch(c.lastName || c.companyName || '');
    setTargetCustomerId(cId); 
    setActiveView('customers'); 
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setIsMobileMenuOpen(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-600/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">
                {companyInfo.name.split(' ')[0]} <span className="text-blue-600 font-black">{companyInfo.name.split(' ').slice(1).join(' ')}</span>
              </h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl">
              {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="lg:hidden border-t border-slate-200 bg-white p-4 animate-in slide-in-from-top-4 duration-200 shadow-xl">
            <nav className="flex flex-col gap-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { handleNavigate(item.id as AppView); setIsMobileMenuOpen(false); }}
                  className={`flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${
                    activeView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-500 hover:bg-slate-100'
                  }`}
                >
                  <item.icon className="w-5 h-5" />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
              {userSettings.enabled && (
                <>
                  <div className="h-px bg-slate-100 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-5 py-4 text-red-600 font-bold"
                  >
                    <LogOut className="w-5 h-5" />
                    Odhlásit se
                  </button>
                </>
              )}
            </nav>
          </div>
        )}
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} technicians={technicians} predefinedTasks={predefinedTasks} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} initialOrderId={targetOrderId} selectedPrinter={selectedPrinter} onCreateInvoice={handleCreateInvoiceFromOrder} search={orderSearch} onSearchChange={setOrderSearch} />}
          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(id) => setInvoices(prev => prev.filter(inv => inv.id !== id))} onUpdateInvoiceStatus={(id, status) => setInvoices(prev => prev.map(inv => inv.id === id ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} search={invoiceSearch} onSearchChange={setInvoiceSearch} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} search={customerSearch} onSearchChange={setCustomerSearch} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => setShouldOpenModal(false)} search={vehicleSearch} onSearchChange={setVehicleSearch} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={(s) => { setAutoBackupSettings(s); localStorage.setItem('autoBackupSettings', JSON.stringify(s)); }} setDirectoryHandle={setDirectoryHandle} directoryHandle={directoryHandle} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { 
  AlertCircle, 
  Plus, 
  Car, 
  Wrench, 
  ShieldAlert, 
  UserPlus,
  ClipboardPlus,
  Clock,
  ChevronRight,
  ClipboardList
} from 'lucide-react';
import { Customer, Vehicle, ServiceRecord, AppView, NotificationSettings } from '../types';

interface DashboardProps {
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  onNavigate: (view: AppView, autoOpen?: boolean) => void;
  onViewVehicle: (vehicleId: string) => void;
  onViewOrder: (orderId: string) => void;
  notifSettings: NotificationSettings;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onNavigate, 
  onViewVehicle, 
  onViewOrder,
  notifSettings 
}) => {
  const [isQuickActionOpen, setIsQuickActionOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsQuickActionOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const vehicleAlerts = useMemo(() => {
    const alerts: { type: 'stk' | 'service'; vehicle: Vehicle; daysLeft: number }[] = [];
    const now = new Date();
    vehicles.forEach(v => {
      const stkDate = new Date(v.stkExpirationDate);
      const serviceDate = new Date(v.nextServiceDate);
      const diffStk = Math.ceil((stkDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      const diffService = Math.ceil((serviceDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      if (diffStk >= 0 && diffStk <= notifSettings.stkThresholdDays) {
        alerts.push({ type: 'stk', vehicle: v, daysLeft: diffStk });
      }
      if (diffService >= 0 && diffService <= notifSettings.serviceThresholdDays) {
        alerts.push({ type: 'service', vehicle: v, daysLeft: diffService });
      }
    });
    return alerts.sort((a, b) => a.daysLeft - b.daysLeft);
  }, [vehicles, notifSettings]);

  const activeOrders = useMemo(() => {
    return services.filter(s => s.status === 'naplánováno' || s.status === 'probíhá')
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [services]);

  const quickActions = [
    { label: 'Nový zákazník', icon: UserPlus, view: 'customers' as AppView, desc: 'Registrace nového klienta' },
    { label: 'Nové vozidlo', icon: Car, view: 'vehicles' as AppView, desc: 'Evidence nového vozu' },
    { label: 'Nová zakázka', icon: ClipboardPlus, view: 'orders' as AppView, desc: 'Založení servisního listu' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Přehled servisu</h2>
          <p className="text-slate-500 font-medium">AutoService Pro v přehledném světlém režimu.</p>
        </div>

        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={() => setIsQuickActionOpen(!isQuickActionOpen)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-blue-600/30 hover:bg-blue-700 hover:-translate-y-0.5 transition-all flex items-center gap-3"
          >
            <Plus className={`w-6 h-6 transition-transform duration-300 ${isQuickActionOpen ? 'rotate-45' : ''}`} />
            Rychlá akce
          </button>
          {isQuickActionOpen && (
            <div className="absolute top-20 right-0 w-72 bg-white rounded-[2rem] shadow-2xl border border-slate-100 p-4 z-50 animate-in fade-in zoom-in-95 duration-200">
              <div className="space-y-2">
                {quickActions.map((action, idx) => (
                  <button
                    key={idx}
                    onClick={() => { onNavigate(action.view, true); setIsQuickActionOpen(false); }}
                    className="w-full flex items-center gap-4 p-4 rounded-2xl hover:bg-slate-50 transition-colors group text-left"
                  >
                    <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-all">
                      <action.icon className="w-5 h-5" />
                    </div>
                    <div>
                      <p className="text-sm font-black text-slate-900">{action.label}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{action.desc}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-200 relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-red-500/[0.03] rounded-full -mr-32 -mt-32 blur-3xl"></div>
          <div className="relative z-10 flex flex-col h-full">
            <div className="flex items-center gap-3 mb-8 text-amber-600 shrink-0">
              <AlertCircle className="w-6 h-6" />
              <h3 className="text-2xl font-black tracking-tight text-slate-900">Důležitá upozornění</h3>
            </div>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar relative">
              {vehicleAlerts.length > 0 ? vehicleAlerts.map((alert, idx) => (
                <div key={idx} className={`p-6 rounded-3xl border transition-all hover:scale-[1.02] cursor-pointer ${alert.type === 'stk' ? 'bg-red-50 border-red-100 text-red-900 hover:bg-red-100' : 'bg-blue-50 border-blue-100 text-blue-900 hover:bg-blue-100'}`} onClick={() => onViewVehicle(alert.vehicle.id)}>
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-2">{alert.type === 'stk' ? <ShieldAlert className="w-4 h-4" /> : <Wrench className="w-4 h-4" />}<span className="text-[10px] font-black uppercase tracking-widest">{alert.type === 'stk' ? 'Expirace STK' : 'Plánovaný servis'}</span></div>
                    <span className={`text-[11px] font-black px-2 py-0.5 rounded-full ${alert.daysLeft <= 5 ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-slate-900 shadow-sm'}`}>Zbývá {alert.daysLeft} dní</span>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-white flex items-center justify-center shadow-sm shrink-0"><Car className="w-6 h-6 text-slate-400" /></div>
                    <div><p className="text-base font-black tracking-tight">{alert.vehicle.make} {alert.vehicle.model}</p><p className="text-xs font-bold font-mono text-slate-400">{alert.vehicle.licensePlate}</p></div>
                  </div>
                </div>
              )) : (
                <div className="h-full bg-slate-50 p-10 rounded-[2rem] border-2 border-dashed border-slate-200 text-center flex flex-col items-center justify-center">
                  <ShieldAlert className="w-12 h-12 text-slate-200 mb-4" /><p className="text-slate-400 font-bold italic">Žádná upozornění podle nastavení.</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-200 relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/[0.03] rounded-full -mr-32 -mt-32 blur-3xl"></div>
          <div className="relative z-10 flex flex-col h-full">
            <div className="flex items-center gap-3 mb-8 text-blue-600 shrink-0">
              <ClipboardList className="w-6 h-6" />
              <h3 className="text-2xl font-black tracking-tight text-slate-900">Aktivní zakázky</h3>
            </div>
            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar relative">
              {activeOrders.length > 0 ? activeOrders.map((order) => {
                const vehicle = vehicles.find(v => v.id === order.vehicleId);
                return (
                  <div key={order.id} className="p-6 rounded-3xl border border-slate-100 bg-white text-slate-900 transition-all hover:scale-[1.02] hover:shadow-lg cursor-pointer" onClick={() => onViewOrder(order.id)}>
                    <div className="flex justify-between items-start mb-4">
                      <div className="flex items-center gap-2"><Clock className="w-4 h-4 text-blue-600" /><span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{order.status}</span></div>
                      <span className="text-[11px] font-black px-2 py-0.5 rounded-full bg-slate-100 text-slate-600">{order.date}</span>
                    </div>
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center shrink-0 text-blue-600"><Car className="w-6 h-6" /></div>
                        <div>
                          <p className="text-base font-black tracking-tight truncate max-w-[150px]">{vehicle ? `${vehicle.make} ${vehicle.model}` : 'Neznámý vůz'}</p>
                          <p className="text-xs font-bold text-slate-400 truncate max-w-[200px]">{order.description}</p>
                        </div>
                      </div>
                      <ChevronRight className="w-5 h-5 text-slate-300 shrink-0" />
                    </div>
                  </div>
                );
              }) : (
                <div className="h-full bg-slate-50 p-10 rounded-[2rem] border-2 border-dashed border-slate-200 text-center flex flex-col items-center justify-center">
                  <ClipboardList className="w-12 h-12 text-slate-200 mb-4" /><p className="text-slate-400 font-bold italic">Žádné aktivní zakázky.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle,
  Building2,
  Briefcase
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filtered = customers.filter(c => 
    `${c.firstName} ${c.lastName}`.toLowerCase().includes(search.toLowerCase()) ||
    c.email.toLowerCase().includes(search.toLowerCase()) ||
    (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
    c.phone.includes(search)
  );

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      phone: customer.phone,
      address: customer.address,
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const submissionData = {
      ...formData,
      companyName: formData.companyName.trim() || undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        });
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      };
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle jména, emailu, firmy nebo telefonu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl hover:border-slate-200 transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-600'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
