            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105 ${c.companyName ? 'bg-slate-900' : 'bg-blue-600'}`}>
                {c.companyName ? <Building2 className="w-8 h-8" /> : <>{c.firstName[0]}{c.lastName[0]}</>}
