            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-700 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
