            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black ${selectedDetailCustomer.companyName ? 'bg-slate-800' : 'bg-blue-600'}`}>
                  {selectedDetailCustomer.companyName ? <Building2 className="w-6 h-6" /> : <>{selectedDetailCustomer.firstName[0]}{selectedDetailCustomer.lastName[0]}</>}
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">
                    {selectedDetailCustomer.companyName || `${selectedDetailCustomer.firstName} ${selectedDetailCustomer.lastName}`}
                  </h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Kompletní karta zákazníka</p>
                </div>
              </div>
              <button onClick={() => setSelectedDetailCustomer(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
