              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kontakt</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.firstName} {selectedDetailCustomer.lastName}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Email</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.email}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Telefon</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.phone}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Adresa</p>
                  <p className="text-sm font-bold text-slate-900">{selectedDetailCustomer.address || 'Neuvedeno'}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedDetailCustomer(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl hover:bg-slate-800 transition-all shadow-lg shadow-slate-200"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* New / Edit Customer Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingCustomer ? 'Upravit zákazníka' : 'Nový zákazník'}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">
                  {editingCustomer ? `Editace ID ${editingCustomer.id}` : 'Registrace do systému'}
                </p>
              </div>
              <button onClick={() => setIsAddModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">Osobní údaje</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Jméno *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.firstName}
                      onChange={e => setFormData({...formData, firstName: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Příjmení *</label>
                    <input 
                      required
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.lastName}
                      onChange={e => setFormData({...formData, lastName: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">Firemní údaje (volitelné)</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název firmy</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.companyName}
                      onChange={e => setFormData({...formData, companyName: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">Kontaktní údaje</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email *</label>
                    <input 
                      required
                      type="email" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.email}
                      onChange={e => setFormData({...formData, email: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefon *</label>
                    <input 
                      required
                      type="tel" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.phone}
                      onChange={e => setFormData({...formData, phone: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-200 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingCustomer ? 'ULOŽIT ZMĚNY' : 'ULOŽIT ZÁKAZNÍKA'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerManager;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Car, 
  Fingerprint, 
  Calendar, 
  Gauge, 
  ChevronRight, 
  ChevronDown,
  Cpu, 
  Plus, 
  X, 
  Check, 
  User,
  History,
  CheckCircle2,
  Clock3,
  AlertTriangle,
  Stethoscope,
  Search,
  Edit3,
  MoreHorizontal,
  Trash2,
  AlertCircle,
  StickyNote
} from 'lucide-react';
import { Vehicle, Customer, ServiceRecord } from '../types';

interface VehicleProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle?: (vehicle) => void;
  onUpdateVehicle?: (vehicle) => void;
  onDeleteVehicle?: (id: string) => void;
  onNavigateToCustomer?: (customerId: string) => void;
  onNavigateToOrder?: (orderId: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const VehicleManager: React.FC<VehicleProps> = ({ 
  vehicles, 
  customers, 
  services, 
  onAddVehicle, 
  onUpdateVehicle,
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormState = {
    customerId: '',
    make: '',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    nextServiceDate: new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    notes: '',
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleHistory = (vehicleId: string) => {
    const newExpanded = new Set(expandedHistories);
    if (newExpanded.has(vehicleId)) newExpanded.delete(vehicleId);
    else newExpanded.add(vehicleId);
    setExpandedHistories(newExpanded);
  };

  const filteredVehicles = vehicles.filter(v => 
    v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
    v.make.toLowerCase().includes(search.toLowerCase()) ||
    v.model.toLowerCase().includes(search.toLowerCase())
  );

  const handleEdit = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({
      customerId: vehicle.customerId,
      make: vehicle.make,
      model: vehicle.model,
      year: vehicle.year,
      vin: vehicle.vin,
      licensePlate: vehicle.licensePlate,
      mileage: vehicle.mileage,
      engineCode: vehicle.engineCode,
      color: vehicle.color,
      stkExpirationDate: vehicle.stkExpirationDate,
      nextServiceDate: vehicle.nextServiceDate,
      notes: vehicle.notes || '',
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleAddNew = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicleId) {
      if (!onUpdateVehicle) return;
      const vehicleToUpdate = vehicles.find(v => v.id === editingVehicleId);
      if (vehicleToUpdate) onUpdateVehicle({ ...vehicleToUpdate, ...formData });
    } else {
      if (!onAddVehicle) return;
      const newVehicle: Vehicle = { ...formData, id: `v${Date.now()}`, lastServiceDate: new Date().toISOString().split('T')[0] };
      onAddVehicle(newVehicle);
    }
    setIsModalOpen(false);
    setFormData(initialFormState);
    setEditingVehicleId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle && onDeleteVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Evidence vozidel</h2>
          <p className="text-slate-500 font-medium">Celkem {vehicles.length} vozidel v péči.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat podle SPZ, značky nebo modelu..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredVehicles.map(v => {
          const owner = customers.find(c => c.id === v.customerId);
          const vehicleServices = services.filter(s => s.vehicleId === v.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const isHistoryExpanded = expandedHistories.has(v.id);

          return (
            <div key={v.id} className={`bg-white rounded-[2rem] border shadow-sm overflow-hidden hover:shadow-xl transition-all group flex flex-col ${initialVehicleId === v.id ? 'ring-4 ring-blue-500/20 border-blue-500' : 'border-slate-100'}`}>
              <div className="flex flex-col md:flex-row">
                <div className="md:w-56 bg-slate-50 p-8 flex flex-col items-center justify-center border-r border-slate-100 group-hover:bg-slate-900 group-hover:text-white transition-all duration-500 shrink-0">
                  <div className="w-24 h-24 rounded-full bg-white flex items-center justify-center shadow-xl mb-6 group-hover:scale-110 transition-transform">
                    <Car className="w-12 h-12 text-slate-400" />
                  </div>
                  <div className="bg-white text-slate-900 font-mono font-bold px-4 py-1.5 rounded-lg text-sm border-2 border-slate-100 shadow-sm transition-colors uppercase">{v.licensePlate}</div>
                  <p className="mt-4 text-[10px] font-black uppercase tracking-widest opacity-40">Registrační značka</p>
                </div>

                <div className="flex-1 p-8">
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none mb-2">{v.make} {v.model}</h3>
