                    </div>
                    <div className="relative">
                      <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-3 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-blue-600 hover:bg-slate-50'}`}><MoreHorizontal className="w-5 h-5" /></button>
                      {openMenuId === v.id && (
                        <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit kartu</button>
                          <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat kartu</button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3 border border-slate-100/50"><div className="p-2 bg-white rounded-xl shadow-sm"><Calendar className="w-4 h-4 text-slate-400" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Expirace STK</p><p className="text-sm font-bold text-slate-900">{v.stkExpirationDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3 border border-slate-100/50"><div className="p-2 bg-white rounded-xl shadow-sm"><Stethoscope className="w-4 h-4 text-slate-400" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Příští servis</p><p className="text-sm font-bold text-slate-900">{v.nextServiceDate}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3 border border-slate-100/50"><div className="p-2 bg-white rounded-xl shadow-sm"><Gauge className="w-4 h-4 text-slate-400" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Nájezd km</p><p className="text-sm font-bold text-slate-900">{v.mileage.toLocaleString()}</p></div></div>
                    <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-3 border border-slate-100/50"><div className="p-2 bg-white rounded-xl shadow-sm"><Cpu className="w-4 h-4 text-slate-400" /></div><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Kód motoru</p><p className="text-sm font-bold text-slate-900">{v.engineCode || 'N/A'}</p></div></div>
                  </div>

                  {v.notes && (
                    <div className="mb-6 p-4 bg-amber-50 rounded-2xl border border-amber-100 flex gap-3">
                      <StickyNote className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                      <div>
                        <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-1">Poznámky k vozidlu</p>
                        <p className="text-sm font-medium text-amber-900 leading-relaxed whitespace-pre-wrap">{v.notes}</p>
                      </div>
                    </div>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-slate-50">
                    <div className="flex items-center gap-2"><Fingerprint className="w-4 h-4 text-slate-300" /><span className="text-[11px] font-bold text-slate-400 font-mono">VIN: {v.vin}</span></div>
                    <button onClick={() => toggleHistory(v.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-wider transition-all ${isHistoryExpanded ? 'bg-slate-900 text-white' : 'text-blue-600 hover:bg-slate-50'}`}><History className="w-4 h-4" />{isHistoryExpanded ? 'Zavřít historii' : 'Detail historie'}{isHistoryExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}</button>
                  </div>
                </div>
              </div>

              {isHistoryExpanded && (
                <div className="bg-slate-50 border-t border-slate-100 p-8 animate-in slide-in-from-top-4 duration-300">
                  <div className="flex items-center gap-3 mb-6"><History className="w-5 h-5 text-slate-400" /><h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">Kompletní servisní historie</h4></div>
                  {vehicleServices.length > 0 ? (
                    <div className="space-y-4">
                      {vehicleServices.map((service, idx) => (
                        <div key={service.id} className="relative flex gap-6">
                          {idx !== vehicleServices.length - 1 && <div className="absolute left-[19px] top-10 bottom-[-16px] w-0.5 bg-slate-200"></div>}
                          <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-sm z-10 border-2 border-white ${service.status === 'hotovo' ? 'bg-emerald-500 text-white' : service.status === 'naplánováno' ? 'bg-blue-500 text-white' : 'bg-amber-500 text-white'}`}>{service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : service.status === 'naplánováno' ? <Clock3 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}</div>
                          <div 
                            onClick={() => onNavigateToOrder?.(service.id)}
                            className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all group/item cursor-pointer hover:border-blue-100"
                          >
                            <div>
                              <div className="flex items-center gap-2 mb-1"><span className="text-xs font-black text-slate-900">{service.date}</span><span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : service.status === 'naplánováno' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'}`}>{service.status}</span></div>
                              <p className="text-sm font-medium text-slate-500 group-hover/item:text-blue-600 transition-colors">{service.description}</p>
                            </div>
                            <div className="text-right shrink-0 flex items-center gap-4">
                              <p className="text-lg font-black text-slate-900">{service.cost.toLocaleString()} Kč</p>
                              <ChevronRight className="w-4 h-4 text-slate-300 group-hover/item:text-blue-600 group-hover/item:translate-x-1 transition-all" />
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : <div className="text-center py-10 bg-white rounded-3xl border-2 border-dashed border-slate-100"><p className="text-slate-400 font-bold italic">Zatím žádné servisní záznamy pro toto vozidlo.</p></div>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <div><h3 className="text-2xl font-black tracking-tight">{editingVehicleId ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3><p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">{editingVehicleId ? `Editace vozu ${formData.licensePlate}` : 'Registrace do vozového parku'}</p></div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="md:col-span-2 space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník</label><select required className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}><option value="">Vyberte zákazníka...</option>{customers.map(c => (<option key={c.id} value={c.id}>{c.firstName} {c.lastName}</option>))}</select></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value})} /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN</label><input required type="text" className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold uppercase" value={formData.vin} onChange={e => setFormData({...formData, vin: e.target.value})} /></div>
              <div className="md:col-span-2 space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Poznámky</label>
                <textarea 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold min-h-[100px] resize-none"
                  value={formData.notes}
                  onChange={e => setFormData({...formData, notes: e.target.value})}
                  placeholder="Zapište důležité informace o vozidle..."
                />
              </div>
              <button type="submit" className="md:col-span-2 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-200 transition-all flex items-center justify-center gap-2 mt-4"><Check className="w-5 h-5" />{editingVehicleId ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask } from '../types';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers, 
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<'all' | 'waiting' | 'active' | 'done'>('all');
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '1/2' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
      trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
    } as VehicleChecklist
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) handleEdit(order);
    }
  }, [initialOrderId, services]);

  const handleAddNew = () => {
    resetForm();
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '1/2',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
    setIsModalOpen(true);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);

    setIsModalOpen(false);

    if (serviceData.status === 'hotovo') {
      setShowInvoicePrompt(finalId);
    }

    resetForm();
  };

  const resetForm = () => {
    setFormData({
      id: '',
      vehicleId: '',
      description: '',
      parts: [],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '1/2',
      mileageAtEntry: 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, naradi: false, hustilka: false,
        trojuhelnik: false, lekarna: false, radio: false, reflektory: false, nosic: false
      }
    });
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const addFromPriceList = (item: FixedService) => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: item.name, quantity: 1, unit: 'úkon', unitPrice: item.price }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({
      ...formData,
      description: `${currentDesc}${separator}${item.description}`
    });
    setIsTemplatePickerOpen(false);
  };

  const toggleChecklist = (key: keyof VehicleChecklist) => {
    setFormData({
      ...formData,
      checklist: { ...formData.checklist, [key]: !formData.checklist[key] }
    });
  };

  const filteredOrders = services.filter(order => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    const owner = customers.find(c => c.id === vehicle?.customerId);
    if (statusFilter === 'waiting' && order.status !== 'naplánováno') return false;
    if (statusFilter === 'active' && order.status !== 'probíhá') return false;
    if (statusFilter === 'done' && order.status !== 'hotovo') return false;
    if (!search) return true;
    return (
      order.id.toLowerCase().includes(search.toLowerCase()) ||
      order.description.toLowerCase().includes(search.toLowerCase()) ||
      vehicle?.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
      owner?.lastName.toLowerCase().includes(search.toLowerCase())
    );
  });

  const currentVehicle = vehicles.find(v => v.id === formData.vehicleId);
  const currentCustomer = currentVehicle ? customers.find(c => c.id === currentVehicle.customerId) : null;

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      {/* Real Print Template */}
      <div className="hidden print:block">
        <PrintTemplate 
          order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} 
          company={companyInfo} 
          vehicles={vehicles} 
          customers={customers} 
          hourlyRate={hourlyRate} 
        />
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Správa zakázek</h2>
          <p className="text-slate-500 font-medium">Evidence zakázkových listů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 print:hidden">
        <div className="flex-1 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat zakázku (ID, SPZ, Jméno)..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
        </div>
        <div className="bg-slate-200/50 p-1.5 rounded-2xl flex items-center gap-1 shrink-0">
          {(['all', 'waiting', 'active', 'done'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setStatusFilter(f)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'
              }`}
            >
              {f === 'all' ? 'Vše' : f === 'waiting' ? 'Čeká' : f === 'active' ? 'Aktivní' : 'Hotovo'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 pb-12 print:hidden">
        {filteredOrders.map(order => {
          const v = vehicles.find(v => v.id === order.vehicleId);
          const c = customers.find(c => c.id === v?.customerId);
          return (
            <div key={order.id} className="bg-white rounded-[2rem] border border-slate-100 p-8 hover:shadow-xl transition-all flex flex-col lg:flex-row items-center gap-8 group">
              <div className="flex items-center gap-6 min-w-[250px]">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white shadow-lg ${
                  order.status === 'hotovo' ? 'bg-emerald-500' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'
                }`}>
                  <ClipboardList className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">{order.id}</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{order.date}</p>
                </div>
              </div>
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
