import React, { useState, useMemo } from 'react';
import { Search, Receipt, Printer, Trash2, CheckCircle, XCircle, AlertCircle, FileText, X, Percent, CreditCard, Wallet, CalendarDays, TrendingUp, AlertOctagon } from 'lucide-react';
import { Invoice, CompanyInfo, Customer } from '../types';

interface InvoiceManagerProps {
  invoices: Invoice[];
  customers: Customer[];
  companyInfo: CompanyInfo;
  discountLevels: number[];
  onDeleteInvoice: (id: string) => void;
  onUpdateInvoiceStatus: (id: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onUpdateInvoice: (invoice: Invoice) => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        inv.id.toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        inv.vehicleInfo.toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');
    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: unpaid.reduce((sum, inv) => sum + inv.totalInclDph, 0),
      totalPaid: paid.reduce((sum, inv) => sum + inv.totalInclDph, 0)
    };
  }, [filteredInvoices]);

  const handlePrint = () => {
    window.print();
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;
    let updated = { ...selectedInvoice, [field]: value };
    if (field === 'paymentType') {
      if (value === 'Hotově') { updated.dueDate = updated.issueDate; } 
      else { const date = new Date(updated.issueDate); date.setDate(date.getDate() + 14); updated.dueDate = date.toISOString().split('T')[0]; }
    }
    if (field === 'discount') {
      const baseTotal = updated.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
      const discountedBase = baseTotal * (1 - (value / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = Math.round(discountedBase * 1.21);
    }
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="hidden print:block">
        {selectedInvoice && <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />}
      </div>
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Fakturační systém</h2>
          <p className="text-slate-500 font-medium">Správa vydaných faktur a sledování plateb.</p>
        </div>
        <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-8 px-8">
          <div className="flex flex-col"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">K úhradě celkem</span><span className="text-xl font-black text-blue-600">{totalUnpaid.toLocaleString()} Kč</span></div>
          <div className="w-px h-10 bg-slate-100"></div>
          <div className="flex flex-col"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uhrazeno celkem</span><span className="text-xl font-black text-emerald-600">{totalPaid.toLocaleString()} Kč</span></div>
        </div>
      </div>
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat fakturu..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-0 lg:divide-x divide-slate-200 print:hidden pb-12">
        <div className="lg:pr-8 space-y-6">
          <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><AlertOctagon className="w-4 h-4 text-blue-500" /> K úhradě ({unpaidInvoices.length})</h3>
          <div className="grid grid-cols-1 gap-6">
            {unpaidInvoices.map(inv => <InvoiceCard key={inv.id} inv={inv} customers={customers} today={today} onSelect={setSelectedInvoice} onDelete={setDeletingInvoice} />)}
            {unpaidInvoices.length === 0 && <div className="py-12 text-center bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200"><p className="text-slate-400 font-bold italic">Žádné faktury k úhradě.</p></div>}
          </div>
        </div>
        <div className="lg:pl-8 space-y-6 mt-12 lg:mt-0">
          <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><CheckCircle className="w-4 h-4 text-emerald-500" /> Uhrazeno ({paidInvoices.length})</h3>
          <div className="grid grid-cols-1 gap-6">
            {paidInvoices.map(inv => <InvoiceCard key={inv.id} inv={inv} customers={customers} today={today} onSelect={setSelectedInvoice} onDelete={setDeletingInvoice} />)}
            {paidInvoices.length === 0 && <div className="py-12 text-center bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200"><p className="text-slate-400 font-bold italic">Žádné uhrazené faktury.</p></div>}
          </div>
        </div>
      </div>
      {selectedInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedInvoice(null)}></div>
          <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex flex-col gap-4 bg-slate-50">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4"><FileText className="w-6 h-6 text-blue-600" /><h3 className="text-xl font-black uppercase">Faktura {selectedInvoice.id}</h3></div>
                <div className="flex gap-4">
                  <button onClick={() => onUpdateInvoiceStatus(selectedInvoice.id, selectedInvoice.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno')} className={`px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 ${selectedInvoice.status === 'uhrazeno' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>{selectedInvoice.status === 'uhrazeno' ? 'NEUHRAZENO' : 'UHRAZENO'}</button>
                  <button onClick={handlePrint} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-blue-200"><Printer className="w-4 h-4" /> TISK / PDF</button>
                  <button onClick={() => setSelectedInvoice(null)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
                </div>
              </div>
              <div className="flex flex-wrap items-center gap-6 p-4 bg-white rounded-[2rem] border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Úhrada:</span><div className="flex bg-slate-100 p-1 rounded-xl"><button onClick={() => handleUpdateActiveInvoice('paymentType', 'Hotově')} className={`px-4 py-2 rounded-lg text-xs font-bold ${selectedInvoice.paymentType === 'Hotově' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Hotově</button><button onClick={() => handleUpdateActiveInvoice('paymentType', 'Převodem')} className={`px-4 py-2 rounded-lg text-xs font-bold ${selectedInvoice.paymentType === 'Převodem' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}>Převodem</button></div></div>
                <div className="flex items-center gap-3"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sleva:</span><select value={selectedInvoice.discount || 0} onChange={(e) => handleUpdateActiveInvoice('discount', parseInt(e.target.value))} className="bg-slate-100 border-none rounded-xl px-4 py-2 text-xs font-bold outline-none cursor-pointer">{discountLevels.map(level => <option key={level} value={level}>{level}% sleva</option>)}</select></div>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar"><InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} /></div>
          </div>
        </div>
      )}
      <style>{`
        @media print { @page { size: A4 portrait; margin: 0; } html, body { height: 100%; margin: 0 !important; padding: 0 !important; overflow: visible !important; background: white !important; } #root { display: none !important; } .print-block-invoice { display: block !important; visibility: visible !important; position: absolute !important; left: 0 !important; top: 0 !important; width: 210mm !important; min-height: 297mm !important; margin: 0 !important; padding: 10mm 15mm !important; box-sizing: border-box !important; background: white !important; color: black !important; font-family: 'Inter', sans-serif !important; } .print-block-invoice * { visibility: visible !important; } }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; } .custom-scrollbar::-webkit-scrollbar-track { background: transparent; } .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

const InvoiceCard: React.FC<{ inv: Invoice, customers: Customer[], today: string, onSelect: (i: Invoice) => void, onDelete: (i: Invoice) => void }> = ({ inv, customers, today, onSelect, onDelete }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;
  return (
    <div className={`bg-white rounded-[2rem] border p-6 shadow-sm hover:shadow-xl transition-all group relative ${isOverdue ? 'border-red-200 bg-red-50/10' : 'border-slate-100'}`}>
      <div className="flex items-center justify-between mb-4"><div className={`w-10 h-10 rounded-xl flex items-center justify-center ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : isOverdue ? 'bg-red-100 text-red-600' : 'bg-blue-50 text-blue-600'}`}><Receipt className="w-5 h-5" /></div></div>
      <div className="mb-4"><h3 className="text-lg font-black text-slate-900 leading-none">{inv.id}</h3><p className="text-[10px] font-bold text-blue-600 mt-1 uppercase">{inv.vehicleInfo}</p></div>
      <div className="space-y-1 mb-6"><p className="text-sm font-bold text-slate-700 truncate">{customer?.companyName || `${customer?.firstName} ${customer?.lastName}`}</p><div className="text-[10px] text-slate-400 font-medium"><span className={isOverdue ? 'text-red-500 font-bold' : ''}>Splatnost: {inv.dueDate}</span></div></div>
      <div className="flex items-end justify-between pt-4 border-t border-slate-50"><div><p className="text-xl font-black ${isOverdue ? 'text-red-600' : 'text-slate-900'}">{inv.totalInclDph.toLocaleString()} Kč</p></div><div className="flex gap-1.5"><button onClick={() => onSelect(inv)} className="p-2.5 bg-slate-900 text-white rounded-xl shadow-lg"><Printer className="w-4 h-4" /></button><button onClick={() => onDelete(inv)} className="p-2.5 bg-red-50 text-red-500 rounded-xl"><Trash2 className="w-4 h-4" /></button></div></div>
    </div>
  );
};

const InvoicePrintTemplate: React.FC<{ invoice: Invoice, company: CompanyInfo, customers: Customer[] }> = ({ invoice, company, customers }) => {
  const customer = customers.find(c => c.id === invoice.customerId);
