      <div className="grid grid-cols-12 border-x-2 border-t-2 border-black"><div className="col-span-6 border-r-2 border-b-2 border-black p-6"><p className="text-[8px] font-black uppercase mb-4 text-slate-400">DODAVATEL</p><p className="text-xl font-black uppercase leading-tight mb-2">{company.name}</p><p className="font-bold text-sm mb-4">{company.address}</p><div className="grid grid-cols-2 gap-2 text-sm"><p>IČO: {company.ico}</p><p>DIČ: {company.dic}</p></div></div><div className="col-span-6 border-b-2 border-black p-6 bg-slate-50/50"><p className="text-[8px] font-black uppercase mb-4 text-slate-400">ODBĚRATEL</p><p className="text-xl font-black uppercase leading-tight mb-2">{customer?.companyName || `${customer?.firstName} ${customer?.lastName}`}</p><p className="font-bold text-sm mb-4">{customer?.address || "---"}</p><div className="col-span-2 mt-4 pt-4 border-t border-black/10"><p className="text-[9px] font-black text-blue-600 uppercase tracking-widest mb-1">Vozidlo</p><p className="font-black text-blue-800">{invoice.vehicleInfo}</p></div></div></div>
      <div className="grid grid-cols-4 border-x-2 border-b-2 border-black"><div className="p-4 border-r-2 border-black bg-slate-100/50"><p className="text-[8px] font-black text-slate-500">Úhrada</p><p className="font-black text-sm uppercase">{invoice.paymentType}</p></div><div className="p-4 border-r-2 border-black"><p className="text-[8px] font-black text-slate-500">Vystaveno</p><p className="font-black text-sm">{invoice.issueDate}</p></div><div className="p-4 bg-red-50"><p className="text-[8px] font-black text-red-400">Splatnost</p><p className="font-black text-sm text-red-600">{invoice.dueDate}</p></div></div>
      <div className="mt-8 border-2 border-black flex-1 min-h-[450px] flex flex-col"><table className="w-full border-collapse"><thead><tr className="bg-slate-100 border-b-2 border-black text-[9px] font-black uppercase"><th className="p-3 text-left border-r-2 border-black">Popis</th><th className="p-3 text-center border-r-2 border-black w-24">Ks</th><th className="p-3 text-right border-r-2 border-black w-32">Cena/ks</th><th className="p-3 text-right w-36">Celkem (bez DPH)</th></tr></thead><tbody className="text-sm font-bold divide-y divide-black/10">{invoice.items.map((item, idx) => (<tr key={idx}><td className="p-3 border-r-2 border-black">{item.description}</td><td className="p-3 text-center border-r-2 border-black">{item.quantity}</td><td className="p-3 text-right border-r-2 border-black">{item.unitPrice.toLocaleString()} Kč</td><td className="p-3 text-right">{(item.quantity * item.unitPrice).toLocaleString()} Kč</td></tr>))}{Array.from({ length: Math.max(0, 10 - invoice.items.length) }).map((_, i) => (<tr key={`f-${i}`} className="h-10"><td className="p-3 border-r-2 border-black"></td><td className="p-3 border-r-2 border-black"></td><td className="p-3 border-r-2 border-black"></td><td className="p-3"></td></tr>))}</tbody></table></div>
      <div className="grid grid-cols-12 border-x-2 border-b-2 border-black"><div className="col-span-7 p-6 border-r-2 border-black flex items-center justify-center bg-slate-50/20"><div className="text-center"><div className="w-32 h-32 border-2 border-slate-200 bg-white rounded-xl flex items-center justify-center mb-2 mx-auto relative overflow-hidden"><span className="text-[8px] font-black text-slate-300 uppercase relative z-10">QR PLATBA</span></div><p className="text-[7px] font-black text-slate-400 uppercase">Platební údaje jsou v dodavateli</p></div></div><div className="col-span-5 flex flex-col"><div className="p-3 border-b border-black flex justify-between text-xs font-bold text-slate-500"><span>Základ (21 %):</span><span>{discountedBaseTotal.toLocaleString()} Kč</span></div><div className="p-3 border-b border-black flex justify-between text-xs font-bold text-slate-500"><span>DPH:</span><span>{dph.toLocaleString()} Kč</span></div><div className="p-6 bg-slate-900 text-white flex flex-col items-center justify-center h-full"><p className="text-[10px] font-black uppercase opacity-60 mb-2">CELKEM K ÚHRADĚ</p><p className="text-4xl font-black">{totalWithDph.toLocaleString()} Kč</p></div></div></div>
    </div>
  );
};

