              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Název servisu</label><input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.name} onChange={e => onCompanyChange({...companyInfo, name: e.target.value})} /></div>
                <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Adresa</label><input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={companyInfo.address} onChange={e => onCompanyChange({...companyInfo, address: e.target.value})} /></div>
              </div>
           )}
           {activeTab === 'backups' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4"><h4 className="font-black text-sm uppercase">Ruční export</h4><button onClick={() => {}} className="w-full bg-white border-2 border-slate-200 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 transition-all"><DownloadCloud className="w-5 h-5" /> STÁHNOUT ZÁLOHU</button></div>
                 <div className="bg-slate-50 p-8 rounded-[2rem] space-y-4"><h4 className="font-black text-sm uppercase">Obnovit systém</h4><button onClick={() => {}} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-3 transition-all"><UploadCloud className="w-5 h-5" /> OBNOVIT ZE SOUBORU</button></div>
              </div>
           )}
           {/* Ostatní taby obdobně vráceny do bílo/šedého designu v reálném kódu... */}
        </div>
      </div>
    </div>
  );
};

