            {error && <div className="bg-red-50 border border-red-100 p-4 rounded-xl flex items-center gap-3 animate-in shake duration-300"><AlertCircle className="w-5 h-5 text-red-500" /><p className="text-xs font-bold text-red-600">Chyba přihlášení!</p></div>}
            <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-slate-800 transition-all flex items-center justify-center gap-3 mt-4"><LogIn className="w-5 h-5" /> PŘIHLÁSIT SE</button>
          </form>
